# ---------- Helpers ----------
def admin_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not current_user.is_authenticated or not current_user.is_admin:
            flash('Admin access required.', 'danger')
            return redirect(url_for('login'))
        return f(*args, **kwargs)

    return decorated


def mvp_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not current_user.is_authenticated or not current_user.is_admin:
            flash('MVP admin access required.', 'danger')
            return redirect(url_for('login'))
        if current_user.admin_level != 'mvp':
            flash('Only the MVP admin can access this section.', 'danger')
            return redirect(url_for('admin_dashboard'))
        return f(*args, **kwargs)

    return decorated


def elevated_admin_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not current_user.is_authenticated or not current_user.is_admin:
            flash('Admin access required.', 'danger')
            return redirect(url_for('login'))
        if current_user.admin_level not in ['mvp', 'super_admin']:
            flash('MVP or super admin access required.', 'danger')
            return redirect(url_for('admin_dashboard'))
        return f(*args, **kwargs)

    return decorated


