def apply_auto_discount(product):
    """Auto-calculate discount based on sales performance without causing loss"""
    if product.buying_price <= 0:
        return  # Can't calculate without buying price

    max_discount = ((product.selling_price - product.buying_price) / product.selling_price) * 100
    max_discount = max(0, max_discount - 1)  # Keep 1% profit margin

    # Check sales performance
    thirty_days_ago = utcnow() - timedelta(days=30)
    recent_sales = OrderItem.query.join(Order).filter(
        OrderItem.product_id == product.id,
        Order.created_at >= thirty_days_ago
    ).count()

    expected_sales = max(5, product.sales_count * 0.1 if product.sales_count > 0 else 10)

    if recent_sales < expected_sales and max_discount > 0:
        # Apply discount based on how far below expectations
        performance_ratio = recent_sales / expected_sales if expected_sales > 0 else 0
        if performance_ratio < 0.5:
            discount_to_apply = min(max_discount, 30)
            product.discount_percent = discount_to_apply


def calculate_shipping_cost(shipping_rate_id, weight_kg):
    """Legacy rate-card arithmetic, kept for the admin shipping console only.

    Checkout no longer uses this: buyer charges come from quote_cart_delivery,
    which prices each item from its seller's own location. Do not reintroduce it
    on a request path driven by a form field - the caller could then choose which
    rate it was billed at.
    """
    rate = ShippingRate.query.get(shipping_rate_id)
    if not rate or not rate.is_active:
        return 0
    return rate.base_cost + (rate.cost_per_kg * max(0, weight_kg))


def slugify(value, max_length=100):
    cleaned = ''.join(ch.lower() if ch.isalnum() else '-' for ch in (value or '').strip())
    cleaned = '-'.join(part for part in cleaned.split('-') if part)
    return (cleaned or uuid.uuid4().hex[:8])[:max_length]


def exact_cache_token(value, max_length=60, fold_case=False):
    """Injective cache-key segment for a value the query compares directly.

    Two jobs, and the second is the one that is easy to get wrong.

    **Stable.** ``slugify`` ends in ``uuid4().hex[:8]`` when the cleaned value is
    empty, which is right for a product slug - a title of nothing but punctuation
    still needs a unique URL - and wrong in a cache key. The default search on /shop
    is '' and so is the default product type, and /categories/<slug> passes no search
    at all, so every one of those requests was building a key with a random segment
    in it: the busiest anonymous pages on the site never once read their own cache
    (measured as ``hits 0, misses 1`` on two identical calls) and wrote a fresh entry
    per request instead of per distinct search. That is per-request key growth - on
    Redis, memory that climbs with traffic until eviction; on FileSystemCache, a new
    file per request straight over CACHE_THRESHOLD and into the 896ms cliff.

    **Injective.** Anything that reaches SQL as a value - a LIKE pattern, a slug
    matched with ``=`` - must not be collapsed, or two different queries share one
    entry and whichever missed first decides what the other asker is shown. Wrong
    results that look entirely plausible, and nothing logs an error. ``slugify``
    collapsed 'SM A14' onto 'SM-A14', 'Phones' onto 'phones', and any two long
    searches sharing a prefix onto each other. So the readable half here is for
    debuggability only and the identity is a digest of the exact text.

    ``fold_case`` is for text that reaches an ILIKE, where the database itself does
    not distinguish case, so folding it is not a collapse - it is the same query.
    Values compared with ``=`` keep their case, because there the database does care.
    """
    text = value or ''
    if fold_case:
        text = text.lower()
    if not text.strip():
        return 'none'
    readable = ''.join(ch if ch.isalnum() else '-' for ch in text)[:max_length].strip('-')
    return f'{readable or "q"}~{hashlib.sha1(text.encode("utf-8")).hexdigest()[:12]}'


def search_cache_token(value, max_length=60):
    """Cache-key segment for search text, which reaches SQL as an ILIKE pattern.

    Case-folded because ILIKE is case-insensitive: 'Phone' and 'phone' really are one
    query, and giving them separate entries would halve the hit rate for nothing.
    Everything else about the text is preserved - '  phone  ' is a different pattern
    from 'phone' because the route does not strip it, and the database will answer it
    differently.
    """
    return exact_cache_token(value, max_length, fold_case=True)


def form_bool(name):
    return (request.form.get(name) or '').strip().lower() in {'1', 'on', 'true', 'yes'}


def form_float(name, default=0.0, minimum=None, maximum=None):
    try:
        value = float(request.form.get(name, default) or default)
    except (TypeError, ValueError):
        value = default
    if minimum is not None:
        value = max(minimum, value)
    if maximum is not None:
        value = min(maximum, value)
    return value


def form_int(name, default=0, minimum=None, maximum=None):
    try:
        value = int(request.form.get(name, default) or default)
    except (TypeError, ValueError):
        value = default
    if minimum is not None:
        value = max(minimum, value)
    if maximum is not None:
        value = min(maximum, value)
    return value


def unique_product_slug(name, current_id=None):
    base_slug = slugify(name, 180)
    slug = base_slug
    counter = 1
    while True:
        query = Product.query.filter_by(slug=slug)
        if current_id:
            query = query.filter(Product.id != current_id)
        if not query.first():
            return slug
        counter += 1
        slug = f'{base_slug[:170]}-{counter}'


def pos_unit_sale_price(product):
    return product.selling_price or 0


def product_vat_rate(product):
    if not product or not getattr(product, 'vat_applicable', False):
        return 0.0
    return max(0.0, float(getattr(product, 'vat_rate', 0) or 0))


def pos_line_pricing(product, quantity=1):
    qty = max(1, int(quantity or 1))
    list_unit = float(product.selling_price or 0)
    discount_percent = max(0.0, min(99.0, float(product.discount_percent or 0)))
    net_unit = round(list_unit * (1 - discount_percent / 100), 2)
    discount_amount = round((list_unit - net_unit) * qty, 2)
    net_before_tax = round(net_unit * qty, 2)
    tax_amount = round(net_before_tax * product_vat_rate(product) / 100, 2)
    line_total = round(net_before_tax + tax_amount, 2)
    return {
        'quantity': qty,
        'list_unit': list_unit,
        'unit_price': net_unit,
        'discount_amount': discount_amount,
        'tax_amount': tax_amount,
        'line_total': line_total,
    }


def seller_ad_plan_prices():
    return {
        'daily': max(0.0, float(Setting.get('seller_ad_daily_price', '15') or 15)),
        'weekly': max(0.0, float(Setting.get('seller_ad_weekly_price', '100') or 100)),
        'monthly': max(0.0, float(Setting.get('seller_ad_monthly_price', '400') or 400)),
    }


def unique_category_slug(name, current_id=None):
    base_slug = slugify(name, 100)
    slug = base_slug
    counter = 1
    while True:
        query = Category.query.filter_by(slug=slug)
        if current_id:
            query = query.filter(Category.id != current_id)
        if not query.first():
            return slug
        slug = f"{base_slug[:90]}-{counter}"
        counter += 1


def current_user_is_mvp():
    return current_user.is_authenticated and current_user.is_admin and current_user.admin_level == 'mvp'


