def category_market_key(category_name):
    name = (category_name or '').lower()
    if any(token in name for token in ['electronic', 'phone', 'computer', 'gadget', 'solar']):
        return 'electronics'
    if any(token in name for token in ['fashion', 'cloth', 'shoe', 'textile', 'bag']):
        return 'fashion'
    if any(token in name for token in ['home', 'kitchen', 'furniture', 'decor']):
        return 'home'
    if any(token in name for token in ['beauty', 'cosmetic', 'health']):
        return 'beauty'
    if any(token in name for token in ['food', 'supermarket', 'grocery']):
        return 'food'
    if any(token in name for token in ['hardware', 'construction', 'tool', 'auto', 'spare']):
        return 'hardware'
    if any(token in name for token in ['digital', 'book', 'software']):
        return 'digital'
    return 'other'


def market_signal_for(category_name, base_price, tick):
    hour_block = tick // 3600
    day_block = tick // 86400
    seed_fast = int(hashlib.sha256(f'{category_name}:h:{hour_block}'.encode()).hexdigest()[:8], 16)
    seed_slow = int(hashlib.sha256(f'{category_name}:d:{day_block}'.encode()).hexdigest()[:8], 16)
    fast_wave = ((seed_fast % 20) - 10) / 10.0
    slow_wave = ((seed_slow % 30) - 15) / 15.0
    volatility_seed = int(hashlib.sha256(f'{category_name}:v'.encode()).hexdigest()[:4], 16) % 100
    volatility = 2.5 + (volatility_seed / 100.0) * 5.5
    percent_change = round((fast_wave * 0.4 + slow_wave * 0.6) * volatility, 2)
    predicted_price = round(max(1, base_price * (1 + percent_change / 100)), 2)
    if percent_change > 1.0:
        direction = 'increase'
    elif percent_change < -1.0:
        direction = 'drop'
    else:
        direction = 'stagnant'
    return predicted_price, percent_change, direction


def product_market_label(name, category_name=''):
    text_value = f'{name or ""} {category_name or ""}'.lower()
    if any(token in text_value for token in ['ram', 'memory', 'ddr4', 'ddr5']):
        return 'RAM sticks'
    if any(token in text_value for token in ['ssd', 'hdd', 'nvme', 'storage', 'hard drive']):
        return 'storage devices'
    if any(token in text_value for token in ['gaming', 'gpu', 'graphics', 'playstation', 'xbox']):
        return 'gaming hardware'
    if any(token in text_value for token in ['laptop', 'desktop', 'computer', 'monitor', 'keyboard']):
        return 'computing accessories'
    return name or category_name or 'product'


def product_market_reference_match(name='', category_name=''):
    tokens = token_set(name, category_name)
    best = None
    best_score = 0
    for item in PRODUCT_MARKET_REFERENCES:
        score = len(tokens.intersection(item['tokens']))
        if score > best_score and score >= min(3, len(item['tokens'])):
            best = item
            best_score = score
    return best


def extract_ksh_prices(text_value):
    prices = []
    patterns = [
        r'KShs?\.?\s*([0-9][0-9,]*(?:\.\d+)?)',
        r'Ksh\.?\s*([0-9][0-9,]*(?:\.\d+)?)',
        r'KES\s*([0-9][0-9,]*(?:\.\d+)?)',
        r'KSh\s*([0-9][0-9,]*(?:\.\d+)?)',
        r'K\s?sh\s*([0-9][0-9,]*(?:\.\d+)?)',
    ]
    for pattern in patterns:
        for match in re.findall(pattern, text_value or '', flags=re.IGNORECASE):
            try:
                value = float(match.replace(',', ''))
                if 1000 <= value <= 1000000:
                    prices.append(value)
            except ValueError:
                pass
    usd_matches = re.findall(r'(?:USD|\$)\s*([0-9][0-9,]*(?:\.\d+)?)', text_value or '', flags=re.IGNORECASE)
    for match in usd_matches:
        try:
            value = float(match.replace(',', '')) * 130
            if 1000 <= value <= 1000000:
                prices.append(value)
        except ValueError:
            pass
    return prices


def fetch_live_reference_range(reference):
    prices = []
    checked = []
    headers = {'User-Agent': 'Mozilla/5.0 SMARKAFRICA market intelligence'}
    urls = reference.get('source_urls', [])[:6]

    def fetch_url(url):
        try:
            response = requests.get(url, timeout=6, headers=headers)
            if response.ok:
                page_prices = extract_ksh_prices(response.text)
                if page_prices:
                    return url, page_prices[:6]
        except requests.RequestException:
            pass
        return url, []

    with ThreadPoolExecutor(max_workers=6) as executor:
        futures = {executor.submit(fetch_url, url): url for url in urls}
        for future in as_completed(futures):
            url, page_prices = future.result()
            if page_prices:
                prices.extend(page_prices)
                checked.append(url)

    if not prices:
        return None
    floor = float(reference.get('kenya_low', 0)) * 0.75
    ceiling = float(reference.get('kenya_high', 0)) * 1.25
    filtered_prices = [price for price in prices if floor <= price <= ceiling]
    if filtered_prices:
        prices = filtered_prices
    low = max(min(prices), float(reference.get('kenya_low', min(prices))))
    high = max(max(prices), float(reference.get('kenya_high', max(prices))))
    return {
        'kenya_low': round(low, 2),
        'kenya_high': round(high, 2),
        'manufacturer_price': round((low + high) / 2, 2),
        'source': f"Live web scan of {len(checked)} source(s)",
        'source_url': checked[0] if checked else reference.get('source_url', ''),
    }


def clean_search_terms(*parts, max_len=180):
    value = ' '.join(str(part or '') for part in parts)
    value = re.sub(r'<[^>]+>', ' ', value)
    value = re.sub(r'[^A-Za-z0-9\s\-\+\.]', ' ', html.unescape(value))
    value = re.sub(r'\s+', ' ', value).strip()
    return value[:max_len]


def live_web_price_scan(product_name, country='Kenya', description='', category_name=''):
    query_core = clean_search_terms(product_name, category_name, description[:180])
    query = f"{query_core} price {country} KSh"
    prices = []
    source_url = ''
    source_name = 'Live web scan'
    search_urls = [
        f"https://html.duckduckgo.com/html/?q={requests.utils.quote(query)}",
        f"https://www.bing.com/search?q={requests.utils.quote(query)}",
    ]
    headers = {'User-Agent': 'Mozilla/5.0 SMARKAFRICA market intelligence'}
    blocked_domains = ['duckduckgo', 'bing.com', 'google.com', 'gstatic']

    def fetch_search(url):
        try:
            r = requests.get(url, timeout=6, headers=headers)
            return r.text if r.ok else ''
        except requests.RequestException:
            return ''

    def fetch_snippet(url):
        try:
            r = requests.get(url, timeout=5, headers=headers)
            if r.ok:
                return url, extract_ksh_prices(r.text)[:8]
        except requests.RequestException:
            pass
        return url, []

    with ThreadPoolExecutor(max_workers=4) as executor:
        search_futures = [executor.submit(fetch_search, u) for u in search_urls]
        for future in as_completed(search_futures):
            text_value = future.result()
            if not text_value:
                continue
            prices.extend(extract_ksh_prices(text_value))
            snippet_urls = []
            for snippet in re.findall(r'https?://[^\s"&<>]+', text_value):
                if any(b in snippet.lower() for b in blocked_domains):
                    continue
                snippet_urls.append(snippet.rstrip(').,'))
                if len(snippet_urls) >= 6:
                    break
            snippet_futures = [executor.submit(fetch_snippet, u) for u in snippet_urls]
            for sf in as_completed(snippet_futures):
                url, page_prices = sf.result()
                if page_prices:
                    prices.extend(page_prices)
                    source_url = source_url or url
                if len(prices) >= 12:
                    break
            hrefs = re.findall(r'href=["\'](https?://[^"\']+)["\']', text_value)
            for href in hrefs:
                if not any(b in href for b in blocked_domains):
                    source_url = source_url or href
                    break
            if prices:
                break

    filtered = [price for price in prices if 1000 <= price <= 1000000]
    if filtered:
        filtered.sort()
        low = filtered[0]
        high = filtered[-1]
        if len(filtered) >= 4:
            low = filtered[1]
            high = filtered[-2]
        return {
            'kenya_low': round(low, 2),
            'kenya_high': round(max(low, high), 2),
            'manufacturer_price': round((low + high) / 2, 2),
            'source': source_name,
            'source_url': source_url,
            'confidence': 'live_web_scan',
        }
    return None


def market_cache_key(name='', category_name=''):
    return clean_search_terms(name, category_name, max_len=220).lower()


def cached_market_range(name='', category_name=''):
    key = market_cache_key(name, category_name)
    if not key:
        return None
    row = MarketPriceCache.query.filter_by(cache_key=key).first()
    if not row:
        return None
    return {
        'kenya_low': row.kenya_low or 0.0,
        'kenya_high': row.kenya_high or 0.0,
        'manufacturer_price': row.manufacturer_price or 0.0,
        'source': row.source or 'Cached market scan',
        'source_url': row.source_url or '',
        'confidence': row.confidence or 'cached_scan',
    }


def upsert_market_price_cache(name, category_name, payload):
    key = market_cache_key(name, category_name)
    if not key or not payload:
        return None
    row = MarketPriceCache.query.filter_by(cache_key=key).first()
    if not row:
        row = MarketPriceCache(cache_key=key, label=product_market_label(name, category_name), category_name=category_name)
        db.session.add(row)
    row.kenya_low = payload.get('kenya_low', 0.0)
    row.kenya_high = payload.get('kenya_high', 0.0)
    row.manufacturer_price = payload.get('manufacturer_price', 0.0)
    row.source = payload.get('source', 'Scheduled market scan')
    row.source_url = payload.get('source_url', '')
    row.confidence = payload.get('confidence', 'scheduled_scan')
    row.payload = json.dumps(payload)
    row.refreshed_at = utcnow()
    return row


def refresh_market_price_cache(limit=30):
    refreshed = 0
    references = PRODUCT_MARKET_REFERENCES[:limit]

    def fetch_reference(ref):
        payload = fetch_live_reference_range(ref)
        return ref, payload

    with ThreadPoolExecutor(max_workers=8) as executor:
        futures = [executor.submit(fetch_reference, ref) for ref in references]
        for future in as_completed(futures):
            try:
                ref, payload = future.result()
            except Exception as exc:
                app.logger.warning('Market reference refresh skipped: %s', exc)
                continue
            if payload:
                upsert_market_price_cache(ref['label'], ref.get('category_hint', ''), payload)
                refreshed += 1

    remaining = max(0, limit - refreshed)
    products = Product.query.filter_by(is_active=True).order_by(Product.updated_at.desc()).limit(remaining).all() if remaining else []

    def fetch_product_price(product):
        category_name = product.category.name if product.category else ''
        payload = live_web_price_scan(product.name, description=product.description or '', category_name=category_name)
        return product, category_name, payload

    with ThreadPoolExecutor(max_workers=6) as executor:
        futures = [executor.submit(fetch_product_price, p) for p in products]
        for future in as_completed(futures):
            try:
                product, category_name, payload = future.result()
            except Exception as exc:
                app.logger.warning('Product market refresh skipped: %s', exc)
                continue
            if payload:
                upsert_market_price_cache(product.name, category_name, payload)
                refreshed += 1

    db.session.commit()
    return refreshed

# The comparable-price scan is the expensive half of the price check, and the price
# check runs on every pause in typing on the add-product form. Its answer depends only
# on the name tokens and the category, so an admin walking a price up and down asks
# the identical question over and over - which this holds on to. In-process on purpose:
# it must work with no Redis configured.
MARKET_COMPARABLE_TTL = float_env('MARKET_COMPARABLE_TTL', 60)
_comparable_price_cache = TTLCache(ttl_seconds=MARKET_COMPARABLE_TTL, max_entries=512,
                                   name='market-comparables')

# The add-product form calls the price check while the admin is still typing. The
# debounce and the cache above keep that cheap, but a stuck or hostile client should
# not be able to hold sync workers either, so there is a ceiling on it as well.
PRICE_CHECK_RATE_LIMIT = os.environ.get('PRICE_CHECK_RATE_LIMIT', '120 per minute')


def comparable_price_stats(name='', category_id=None, exclude_id=None, limit=12):
    """Price spread of the listings most like this one. Cached, returns plain floats.

    Two deliberate economies, because this runs while somebody is still typing:

    Only the columns needed are selected. This used to load 80 full Product rows,
    whose ``description`` Text column is the bulk of the transfer and the weakest
    match signal of the three text fields; matching now uses name and
    short_description, and ``discounted_price`` is recomputed here because it is a
    Python property (models.py) rather than a column.

    And the result is a dict of numbers, not ORM instances - same reasoning as
    NavCategory: cached ORM objects belong to the session that loaded them and are
    detached by the time the next request reads them.
    """
    tokens = token_set(name)
    key = (tuple(sorted(tokens)), category_id or 0, exclude_id or 0, limit)
    found = _comparable_price_cache.lookup(key)
    if found is not CACHE_MISS:
        return found

    query = db.session.query(
        Product.short_description, Product.name, Product.selling_price,
        Product.discount_percent, Product.updated_at, Product.created_at,
    ).filter(Product.is_active.is_(True))
    if category_id:
        query = query.filter(Product.category_id == category_id)
    if exclude_id:
        query = query.filter(Product.id != exclude_id)
    rows = query.order_by(Product.updated_at.desc()).limit(80).all()

    scored = []
    for row in rows:
        overlap = len(tokens.intersection(token_set(row.name, row.short_description)))
        if overlap or not tokens:
            price = float(row.selling_price or 0)
            if row.discount_percent and row.discount_percent > 0:
                price = round(price * (1 - row.discount_percent / 100), 2)
            if price:
                scored.append((overlap, row.updated_at or row.created_at or utcnow(), price))
    scored.sort(key=lambda item: (item[0], item[1]), reverse=True)
    prices = [price for _, _, price in scored[:limit]]

    stats = {'count': len(prices)}
    if prices:
        stats.update({'low': min(prices), 'high': max(prices),
                      'midpoint': sum(prices) / len(prices)})
    return _comparable_price_cache.set(key, stats)


def market_price_reference(name, category_id=None, price=None, buying_price=0, exclude_id=None, description=''):
    try:
        category_id = int(category_id) if category_id not in [None, ''] else None
    except (TypeError, ValueError):
        category_id = None
    try:
        exclude_id = int(exclude_id) if exclude_id not in [None, ''] else None
    except (TypeError, ValueError):
        exclude_id = None
    category = Category.query.get(category_id) if category_id else None
    known_reference = product_market_reference_match(name, category.name if category else '')
    price_value = float(price or 0)
    if known_reference:
        live_range = cached_market_range(known_reference['label'], known_reference.get('category_hint', ''))
        range_source = live_range or known_reference
        kenya_low = range_source['kenya_low']
        kenya_high = range_source['kenya_high']
        manufacturer_price = range_source['manufacturer_price']
        recommended = round((kenya_low + kenya_high) / 2, 2)
        status = 'ok'
        message = ''
        if price_value and price_value < kenya_low:
            status = 'low'
            message = 'This listing is below verified Kenya retailer ranges. Confirm variant, warranty, condition, and authenticity before publishing.'
        elif price_value and price_value > kenya_high:
            status = 'high'
            message = 'This listing is above verified Kenya retailer ranges. Confirm storage variant, warranty, import cost, and customer value before publishing.'
        return {
            'status': status,
            'message': message,
            'label': known_reference['label'],
            'kenya_low': kenya_low,
            'kenya_high': kenya_high,
            'manufacturer_price': manufacturer_price,
            'recommended_price': recommended,
            'competitor_count': 0,
            'source': range_source.get('source', known_reference['source']),
            'source_url': range_source.get('source_url', known_reference['source_url']),
            'image_url': known_reference.get('image_url', ''),
            'confidence': 'verified_reference',
        }

    stats = comparable_price_stats(name, category_id, exclude_id=exclude_id)
    comp_prices = stats['count']
    if comp_prices:
        low = stats['low']
        high = stats['high']
        midpoint = stats['midpoint']
    else:
        web_range = cached_market_range(name, category.name if category else '')
        if web_range:
            kenya_low = web_range['kenya_low']
            kenya_high = web_range['kenya_high']
            manufacturer_price = web_range['manufacturer_price']
            recommended = round((kenya_low + kenya_high) / 2, 2)
            status = 'ok'
            message = ''
            if price_value and price_value < kenya_low:
                status = 'low'
                message = 'This listing is below the live web price scan range. Confirm condition, authenticity, and source cost.'
            elif price_value and price_value > kenya_high:
                status = 'high'
                message = 'This listing is above the live web price scan range. Confirm variant and customer value.'
            return {
                'status': status,
                'message': message,
                'label': product_market_label(name, category.name if category else ''),
                'kenya_low': kenya_low,
                'kenya_high': kenya_high,
                'manufacturer_price': manufacturer_price,
                'recommended_price': recommended,
                'competitor_count': 0,
                'source': web_range['source'],
                'source_url': web_range.get('source_url', ''),
                'image_url': '',
                'confidence': web_range['confidence'],
            }
        label = product_market_label(name, category.name if category else '')
        return {
            'status': 'web_pending',
            'message': 'Scheduled web scan has not cached a market range yet. No automated range will be shown until the background scan captures one.',
            'label': label,
            'kenya_low': 0.0,
            'kenya_high': 0.0,
            'manufacturer_price': 0.0,
            'recommended_price': float(price or 0),
            'competitor_count': 0,
            'source': 'No verified source matched',
            'source_url': '',
            'image_url': '',
            'confidence': 'insufficient_data',
        }

    manufacturer_price = max(float(buying_price or 0) * 1.08, midpoint * 0.72)
    kenya_low = round(max(1, low * 0.92), 2)
    kenya_high = round(max(kenya_low, high * 1.12), 2)
    recommended = round((kenya_low + kenya_high) / 2, 2)
    status = 'ok'
    message = ''
    if price_value and price_value < kenya_low:
        status = 'low'
        message = 'This listing is far below Kenya market prices. Confirm cost, stock condition, and authenticity before publishing.'
    elif price_value and price_value > kenya_high:
        status = 'high'
        message = 'This listing is far above competitor pricing and may create abnormal profit or lower buyer trust.'

    return {
        'status': status,
        'message': message,
        'label': product_market_label(name, category.name if category else ''),
        'kenya_low': kenya_low,
        'kenya_high': kenya_high,
        'manufacturer_price': round(manufacturer_price, 2),
        'recommended_price': recommended,
        'competitor_count': comp_prices,
        'source': 'Your active SMARKAFRICA catalog comparables',
        'source_url': '',
        'image_url': '',
        'confidence': 'catalog_comparable',
    }


def build_market_intelligence_payload(selected_category='all'):
    tick = int(utcnow().timestamp())
    categories = Category.query.order_by(Category.name.asc()).all()
    rows = []
    labels = []
    current_prices = []
    predicted_prices = []
    colors = []

    for category in categories:
        if selected_category != 'all' and str(category.id) != str(selected_category):
            continue
        products = Product.query.filter_by(category_id=category.id, is_active=True).all()
        if products:
            base_price = sum((p.discounted_price or p.selling_price or 0) for p in products) / max(1, len(products))
        else:
            base_price = 1000 + (category.id * 137)
        predicted_price, percent_change, direction = market_signal_for(category.name, base_price, tick)
        key = category_market_key(category.name)
        manufacturer = Manufacturer.query.filter(
            Manufacturer.product_categories.ilike(f'%{category.name}%')
        ).order_by(Manufacturer.priority.desc(), Manufacturer.rating.desc()).first()
        source_name = manufacturer.name if manufacturer else 'World supplier index'
        source_region = manufacturer.country if manufacturer and manufacturer.country else 'Global'
        headline = f'{source_region} {category.name} manufacturer price watch'

        labels.append(category.name)
        current_prices.append(round(base_price, 2))
        predicted_prices.append(predicted_price)
        colors.append(MARKET_CATEGORY_COLORS.get(key, MARKET_CATEGORY_COLORS['other']))
        rows.append({
            'category_id': category.id,
            'category': category.name,
            'market_key': key,
            'color': MARKET_CATEGORY_COLORS.get(key, MARKET_CATEGORY_COLORS['other']),
            'current_price': round(base_price, 2),
            'predicted_price': predicted_price,
            'percent_change': percent_change,
            'direction': direction,
            'source': source_name,
            'headline': headline,
            'kenya_price': round(base_price * 1.08, 2),
            'world_price': round(base_price * 0.96, 2),
            'importer_note': f'Kenya landed estimate compared with {source_region} supplier pricing.',
            'updated_at': utcnow().strftime('%H:%M:%S'),
        })

    if not rows:
        demo_categories = ['Electronics', 'Fashion', 'Home', 'Beauty']
        for index, name in enumerate(demo_categories, start=1):
            base_price = 1500 + index * 650
            predicted_price, percent_change, direction = market_signal_for(name, base_price, tick)
            key = category_market_key(name)
            labels.append(name)
            current_prices.append(base_price)
            predicted_prices.append(predicted_price)
            colors.append(MARKET_CATEGORY_COLORS[key])
            rows.append({
                'category_id': index,
                'category': name,
                'market_key': key,
                'color': MARKET_CATEGORY_COLORS[key],
                'current_price': base_price,
                'predicted_price': predicted_price,
                'percent_change': percent_change,
                'direction': direction,
                'source': 'World supplier index',
                'headline': f'Global {name} daily price watch',
                'updated_at': utcnow().strftime('%H:%M:%S'),
            })

    return {
        'tick': tick,
        'updated_at': utcnow().strftime('%Y-%m-%d %H:%M:%S UTC'),
        'labels': labels,
        'current_prices': current_prices,
        'predicted_prices': predicted_prices,
        'colors': colors,
        'rows': rows,
    }


MARKETPLACE_NEWS_CATEGORY_FALLBACKS = [
    'Electronics', 'Fashion', 'Automobiles', 'Agriculture', 'Construction', 'Health',
    'Beauty', 'Furniture', 'Industrial Equipment', 'Real Estate', 'Services',
]


def market_news_category_rows():
    payload = build_market_intelligence_payload('all')
    rows = list(payload.get('rows', []))
    existing_names = {str(row.get('category', '')).lower() for row in rows}
    tick = int(utcnow().timestamp())
    next_id = max([int(row.get('category_id') or 0) for row in rows] or [0]) + 1
    for name in MARKETPLACE_NEWS_CATEGORY_FALLBACKS:
        if name.lower() in existing_names:
            continue
        base_price = 1800 + next_id * 425
        predicted_price, percent_change, direction = market_signal_for(name, base_price, tick)
        key = category_market_key(name)
        rows.append({
            'category_id': None,
            'category': name,
            'market_key': key,
            'current_price': round(base_price, 2),
            'predicted_price': predicted_price,
            'percent_change': percent_change,
            'direction': direction,
            'source': 'Verified marketplace source index',
            'headline': f'{name} marketplace intelligence stream',
            'kenya_price': round(base_price * 1.08, 2),
            'world_price': round(base_price * 0.96, 2),
            'importer_note': 'Category stream reserved for verified manufacturer, supplier, logistics, and policy updates.',
        })
        next_id += 1
    return rows


def market_news_recommendation(row):
    direction = row.get('direction', 'stagnant')
    category = row.get('category', 'Marketplace')
    kenya_price = row.get('kenya_price', row.get('current_price', 0))
    world_price = row.get('world_price', 0)
    if direction == 'increase':
        return f'ACTION: Stock {category} NOW at KSh {kenya_price:,.0f}. Prices climbing. Import at KSh {world_price:,.0f} before landed costs jump.'
    if direction == 'drop':
        return f'ACTION: WAIT on {category}. Prices falling toward KSh {world_price:,.0f}. Buy opportunity incoming. Set alerts.'
    return f'WATCH: {category} stable. Fair buy at KSh {kenya_price:,.0f}. Compare suppliers, negotiate bulk for better margin.'


def build_category_market_news_item(row):
    category = row.get('category', 'Marketplace')
    direction = row.get('direction', 'stagnant')
    percent = row.get('percent_change', 0)
    kenya_price = row.get('kenya_price', row.get('current_price', 0))
    world_price = row.get('world_price', 0)
    hour_seed = int(hashlib.sha256(f'{category}:{int(utcnow().timestamp()) // 3600}'.encode()).hexdigest()[:4], 16)
    variant = hour_seed % 4
    if direction == 'increase':
        titles = [
            f'{category}: prices rising {abs(percent):.1f}% - BUY NOW',
            f'HOT: {category} demand outpacing supply',
            f'{category} costs up - restock before margin squeeze',
            f'URGENT: {category} prices climbing fast',
        ]
        title = titles[variant]
    elif direction == 'drop':
        titles = [
            f'{category}: prices falling {abs(percent):.1f}% - WAIT',
            f'DEAL WINDOW: {category} getting cheaper',
            f'{category} oversupply detected - negotiate hard',
            f'{category} discounts spotted - bulk buy opportunity',
        ]
        title = titles[variant]
    else:
        titles = [
            f'{category}: stable market - compare suppliers',
            f'{category}: no pressure - negotiate calmly',
            f'{category}: flat trend - set price alerts',
            f'{category}: range-bound - good time to plan',
        ]
        title = titles[variant]
    body = (
        f"{category} | Kenya: KSh {kenya_price:,.0f} | World: KSh {world_price:,.0f} | "
        f"Movement: {percent:+.1f}% | Source: {row.get('source', 'marketplace index')} | "
        f"{market_news_recommendation(row)}"
    )
    image_payload = trend_image_payload(category, row.get('market_key', category))
    return MarketNews(
        title=title,
        body=body,
        product_name=category,
        image_url=image_payload['image_url'],
        category_id=row.get('category_id'),
        region='Real-Time Marketplace Intelligence',
        direction='watch' if direction == 'stagnant' else direction,
        generated_by='marketplace_intelligence',
    )


def disbursement_snapshot():
    incoming_types = ['sale', 'commission', 'ad_commission', 'raffle_ticket_sale', 'platform_commission_disbursement']
    outgoing_types = ['refund', 'withdrawal', 'salary', 'manufacturer_payout', 'disbursement', 'seller_payout_disbursement']
    incoming_total = db.session.query(func.sum(Transaction.amount)).filter(
        Transaction.type.in_(incoming_types),
        Transaction.amount > 0
    ).scalar() or 0.0
    outgoing_total = db.session.query(func.sum(func.abs(Transaction.amount))).filter(
        Transaction.type.in_(outgoing_types)
    ).scalar() or 0.0
    pending_withdrawals = WithdrawalRequest.query.filter_by(status='pending_review').all()
    releasable_seller_earnings = Transaction.query.filter(
        Transaction.type == 'seller_earning',
        Transaction.status == 'pending_review'
    ).count()
    pending_salaries = AdminSalary.query.filter(AdminSalary.status.in_(['pending', 'queued'])).all()
    manufacturer_reserve = round(max(0.0, incoming_total * 0.35), 2)
    available_balance = round(incoming_total - outgoing_total, 2)
    return {
        'incoming_total': incoming_total,
        'outgoing_total': outgoing_total,
        'available_balance': available_balance,
        'pending_withdrawals': pending_withdrawals,
        'releasable_seller_earnings': releasable_seller_earnings,
        'pending_salaries': pending_salaries,
        'manufacturer_reserve': manufacturer_reserve,
    }


def seller_available_balance(user_id):
    earned = db.session.query(func.coalesce(func.sum(Transaction.amount), 0)).filter(
        Transaction.user_id == user_id,
        Transaction.type == 'seller_earning',
        Transaction.status == 'released'
    ).scalar() or 0.0
    outgoing = db.session.query(func.coalesce(func.sum(WithdrawalRequest.amount), 0)).filter(
        WithdrawalRequest.user_id == user_id,
        WithdrawalRequest.status.in_(['pending_review', 'queued_for_payment', 'paid'])
    ).scalar() or 0.0
    return round(max(0.0, earned - outgoing), 2)


def release_eligible_seller_earnings():
    released = 0
    txns = Transaction.query.filter(
        Transaction.type == 'seller_earning',
        Transaction.status == 'pending_review'
    ).all()
    for txn in txns:
        order = txn.order
        if not order:
            continue
        buyer_received = (
            order.payment_status in ORDER_PAID_STATUSES and
            (
                # Rows written before statuses were normalised carry 'Delivered'.
                (order.shipping_status or '').strip().lower() == 'delivered' or
                (order.status or '').strip().lower() == 'completed' or
                order.protection_status == 'released'
            )
        )
        if not buyer_received:
            continue
        txn.status = 'released'
        txn.available_on = utcnow()
        txn.description = (txn.description or '') + '\nReleased after buyer receipt confirmation.'
        order.protection_status = 'released'
        released += 1
    return released


def seller_receiving_account(user):
    if not user:
        return ''
    method = user.seller_payout_method or 'mpesa'
    account = user.seller_payout_account or ''
    name = user.seller_payout_name or user.username
    if account:
        return f'{method.upper()} - {account} ({name})'
    return ''


def platform_commission_account():
    method = Setting.get('platform_commission_receiving_method', 'mpesa') or 'mpesa'
    account = Setting.get('platform_commission_receiving_account', '') or Setting.get('daraja_shortcode', '174379')
    name = Setting.get('platform_commission_receiving_name', 'SMARK-AFRICA Commission')
    return f'{method.upper()} - {account} ({name})'


def seller_sale_settlement_rows():
    earnings = Transaction.query.filter(
        Transaction.type == 'seller_earning'
    ).order_by(Transaction.created_at.desc()).limit(250).all()
    rows = []
    for earning in earnings:
        seller = earning.user
        commission = float(earning.commission_amount or 0)
        balance = float(earning.amount or 0)
        price_paid = round(balance + commission, 2)
        payout_account = seller_receiving_account(seller)
        disbursable = earning.status in {'released', 'completed'} and not earning.disbursed_at and bool(payout_account)
        rows.append({
            'txn': earning,
            'seller': seller,
            'price_paid': price_paid,
            'commission': commission,
            'balance': balance,
            'phone': seller.phone if seller else '',
            'payout_account': payout_account,
            'disbursable': disbursable,
        })
    return rows


def disburse_seller_sale(earning):
    if not earning or earning.type != 'seller_earning':
        return False, 'Settlement item was not found.'
    if earning.disbursed_at:
        return False, 'This seller sale has already been disbursed.'
    if earning.status not in {'released', 'completed'}:
        return False, 'Funds are not released yet. Complete delivery/protection review first.'
    seller = earning.user
    payout_account = seller_receiving_account(seller)
    if not payout_account:
        return False, 'Seller has no receiving account saved.'

    group = f'settle-{earning.id}-{uuid.uuid4().hex[:8]}'
    commission = round(float(earning.commission_amount or 0), 2)
    seller_amount = round(float(earning.amount or 0), 2)
    if commission > 0:
        db.session.add(Transaction(
            order_id=earning.order_id,
            user_id=earning.user_id,
            type='platform_commission_disbursement',
            amount=commission,
            description=f'Commission split for seller settlement transaction #{earning.id}',
            status='queued',
            commission_amount=commission,
            destination_account=platform_commission_account(),
            settlement_group=group,
            available_on=utcnow(),
        ))
        record_platform_revenue(
            'seller_commission',
            commission,
            f'Commission split for settlement transaction #{earning.id}',
            str(earning.order_id or earning.id),
            'order' if earning.order_id else 'settlement',
            earning.user_id,
        )
    db.session.add(Transaction(
        order_id=earning.order_id,
        user_id=earning.user_id,
        type='seller_payout_disbursement',
        amount=-abs(seller_amount),
        description=f'Seller payout for settlement transaction #{earning.id}',
        status='queued',
        destination_account=payout_account,
        settlement_group=group,
        available_on=utcnow(),
    ))
    earning.status = 'disbursed'
    earning.disbursed_at = utcnow()
    earning.destination_account = payout_account
    earning.settlement_group = group
    return True, f'Queued seller payout KSh {seller_amount:,.2f} and platform commission KSh {commission:,.2f}.'


def auto_disburse_released_seller_sales():
    queued = 0
    if Setting.get('auto_disbursement_cadence', 'weekly') == 'off':
        return queued
    candidates = Transaction.query.filter(
        Transaction.type == 'seller_earning',
        Transaction.status.in_(['released', 'completed']),
        Transaction.disbursed_at.is_(None)
    ).limit(100).all()
    for earning in candidates:
        ok, _ = disburse_seller_sale(earning)
        if ok:
            queued += 1
    return queued


def auto_disbursement_due():
    cadence = Setting.get('auto_disbursement_cadence', 'weekly')
    if cadence == 'off':
        return False
    last_raw = Setting.get('auto_disbursement_last_run_at', '')
    try:
        last_run = datetime.fromisoformat(last_raw) if last_raw else None
    except ValueError:
        last_run = None
    wait = timedelta(days=1 if cadence == 'daily' else 7)
    return not last_run or last_run <= utcnow() - wait


# News generation used to be guarded by a settings row holding '0' or '1'. A run
# that died mid-flight left it on '1' and the button stayed dead until someone
# hit ?refresh=1, which is why that escape hatch exists. A lease expires on its
# own, so the same crash costs one lease term instead of forever, and it is
# visible in job_locks rather than buried in the settings table.
MARKET_NEWS_LOCK = 'market_news_generation'
MARKET_NEWS_LEASE = JobLease(ttl_seconds=int_env('MARKET_NEWS_LOCK_TTL_SECONDS', 600))


def generate_market_news_if_due(force=False):
    if force and not acquire_lease(MARKET_NEWS_LOCK, MARKET_NEWS_LEASE):
        raise OperationalError('market_news', {}, 'Generation is already running')
    if force:
        MarketNews.query.filter(
            MarketNews.is_cleared == False,
            MarketNews.generated_by.in_(['marketplace_intelligence', 'product_price_signal'])
        ).update({MarketNews.is_cleared: True}, synchronize_session=False)
        db.session.commit()
    latest = MarketNews.query.order_by(MarketNews.created_at.desc()).first()
    if latest and not force and latest.created_at and latest.created_at > utcnow() - timedelta(hours=2):
        return 0

    pending_news = []
    for row in market_news_category_rows():
        category_name = row.get('category', 'Marketplace')
        existing = MarketNews.query.filter(
            MarketNews.generated_by == 'marketplace_intelligence',
            MarketNews.product_name == category_name,
            MarketNews.created_at > utcnow() - timedelta(hours=2)
        ).first()
        if existing and not force:
            continue
        pending_news.append(build_category_market_news_item(row))

    products = Product.query.filter_by(is_active=True).order_by(
        Product.is_hot_sale.desc(),
        Product.admin_priority.desc(),
        Product.updated_at.desc()
    ).limit(18).all()
    for product in products:
        existing = MarketNews.query.filter(
            MarketNews.generated_by == 'product_price_signal',
            MarketNews.product_name == product.name,
            MarketNews.created_at > utcnow() - timedelta(hours=2)
        ).first()
        if existing and not force:
            continue
        category_name = product.category.name if product.category else 'General'
        row = market_price_reference(
            product.name,
            product.category_id,
            product.discounted_price or product.selling_price,
            product.buying_price,
            exclude_id=product.id
        )
        if row.get('confidence') == 'insufficient_data':
            continue
        _, percent_change, direction = market_signal_for(product.name, row['recommended_price'], int(utcnow().timestamp()))
        label = row['label']
        store_price = product.discounted_price or product.selling_price or 0
        margin_vs_low = round(((store_price - row['kenya_low']) / max(row['kenya_low'], 1)) * 100, 1) if row['kenya_low'] else 0
        hour_seed = int(hashlib.sha256(f'{product.name}:{int(utcnow().timestamp()) // 3600}'.encode()).hexdigest()[:4], 16)
        signal_variant = hour_seed % 5
        if direction == 'increase':
            titles = [
                f"{label} prices trending UP - stock now",
                f"BUY SIGNAL: {label} costs rising",
                f"{label} supply tightening - prices climbing",
                f"ALERT: {label} prices increasing",
                f"{label} demand surge - act fast",
            ]
            actions = [
                f'Buy now at KSh {row["kenya_low"]:,.0f} before prices hit KSh {row["kenya_high"]:,.0f}.',
                f'Restock immediately. Source at KSh {row["kenya_low"]:,.0f} won\'t last. Predicted +{abs(percent_change):.1f}%.',
                f'Lock in supplier prices today. Market moving to KSh {row["kenya_high"]:,.0f}+.',
                f'Competitor prices rising. Buy window: KSh {row["kenya_low"]:,.0f}-{row["kenya_high"]:,.0f}.',
                f'Secure stock at KSh {row["kenya_low"]:,.0f} before {abs(percent_change):.1f}% jump.',
            ]
            title = titles[signal_variant]
            action = actions[signal_variant]
        elif direction == 'drop':
            titles = [
                f"{label} prices DROPPING - wait to buy",
                f"HOLD: {label} getting cheaper",
                f"{label} oversupply - prices falling",
                f"DEAL: {label} at {abs(percent_change):.1f}% discount",
                f"{label} liquidation opportunity",
            ]
            actions = [
                f'Wait 24-48h. Dropping from KSh {row["kenya_high"]:,.0f} toward KSh {row["kenya_low"]:,.0f}.',
                f'Sellers discounting stock. Target: KSh {row["kenya_low"]:,.0f}. Don\'t overpay.',
                f'Oversupply = negotiation power. Push for KSh {row["kenya_low"]:,.0f} or below.',
                f'Buy at KSh {row["kenya_low"]:,.0f}, sell at KSh {store_price:,.0f} for {margin_vs_low:.0f}% margin.',
                f'Flash deal window. Source at KSh {row["kenya_low"]:,.0f} and flip before competitors notice.',
            ]
            title = titles[signal_variant]
            action = actions[signal_variant]
        else:
            titles = [
                f"{label} stable - good entry point",
                f"{label} neutral - compare before buying",
                f"{label} steady at KSh {row['kenya_low']:,.0f}-{row['kenya_high']:,.0f}",
                f"{label} flat - watch for breakout",
                f"{label} consolidating - set alerts",
            ]
            actions = [
                f'Fair range: KSh {row["kenya_low"]:,.0f}-{row["kenya_high"]:,.0f}. Safe to buy.',
                f'Compare 3+ suppliers. Fair price: KSh {row["recommended_price"]:,.0f}.',
                f'Negotiate bulk at KSh {row["kenya_low"]:,.0f}. No price pressure.',
                f'Set alert: below KSh {row["kenya_low"]:,.0f} (buy) or above KSh {row["kenya_high"]:,.0f} (sell).',
                f'Your price KSh {store_price:,.0f} vs market KSh {row["recommended_price"]:,.0f}. Margin {"healthy" if margin_vs_low > 10 else "tight"}.',
            ]
            title = titles[signal_variant]
            action = actions[signal_variant]
        body = (
            f"{product.name} ({category_name}) | Kenya: KSh {row['kenya_low']:,.0f}-{row['kenya_high']:,.0f} | "
            f"Import: KSh {row['manufacturer_price']:,.0f} | Store: KSh {store_price:,.0f} | "
            f"Signal: {direction.upper()} ({percent_change:+.1f}%) | {action}"
        )
        pending_news.append(MarketNews(
            title=title,
            body=body,
            product_name=product.name,
            image_url=trend_image_payload(
                product.name,
                category_name,
                product.image_url or row.get('image_url', ''),
                row.get('image_candidates', [])
            )['image_url'],
            source_url=row.get('source_url', ''),
            category_id=product.category_id,
            region='Kenya vs Worldwide',
            direction=direction,
            generated_by='product_price_signal',
        ))
    try:
        if pending_news:
            db.session.bulk_save_objects(pending_news)
        db.session.commit()
    except OperationalError:
        db.session.rollback()
        raise
    finally:
        if force:
            release_lease(MARKET_NEWS_LOCK)
    return len(pending_news)


def selected_phone_value(form):
    code = (form.get('phone_country_code') or '').strip()
    number = (form.get('phone_local') or form.get('phone') or '').strip()
    if code and number:
        return f"{code}{number.lstrip('+').lstrip('0')}"
    return number


def uploaded_product_images():
    images = []
    files = request.files.getlist('product_images')
    if not files:
        files = request.files.getlist('image') + request.files.getlist('additional_images')
    for image_file in files[:10]:
        if not image_file or not image_file.filename:
            continue
        if not allowed_file(image_file.filename):
            flash('Product images must be PNG, JPG, GIF, or WebP.', 'danger')
            continue
        try:
            images.append(save_product_image(image_file))
        except ValueError as exc:
            flash(str(exc), 'danger')
    return images


def create_customer_notification(user_id, title, body, notification_type='update', product_id=None):
    if not user_id or not title or not body:
        return None
    exists = CustomerNotification.query.filter_by(
        user_id=user_id,
        product_id=product_id,
        title=title,
        body=body
    ).first()
    if exists:
        return exists
    item = CustomerNotification(
        user_id=user_id,
        product_id=product_id,
        title=title,
        body=body,
        notification_type=notification_type,
        is_read=False
    )
    db.session.add(item)
    return item


def bnpl_risk_score(user):
    if not user:
        return 0.0
    score = 35.0
    order_count = Order.query.filter_by(user_id=user.id).count()
    paid_count = Order.query.filter_by(user_id=user.id, payment_status='completed').count()
    if user.created_at and user.created_at < utcnow() - timedelta(days=90):
        score += 15
    if paid_count:
        score += min(25, paid_count * 5)
    if order_count and paid_count == order_count:
        score += 10
    if user.verification_status in ['approved', 'verified'] or user.is_verified_seller:
        score += 15
    if user.seller_status in ['frozen', 'rejected']:
        score -= 25
    return max(0.0, min(100.0, round(score, 2)))


def product_barcode_value(product):
    row = ProductBarcode.query.filter_by(product_id=product.id).first()
    if row:
        return row.barcode
    base = f"SAF{product.id:08d}"
    checksum = sum((index + 1) * int(ch) for index, ch in enumerate(str(product.id))) % 10
    barcode = f"{base}{checksum}"
    row = ProductBarcode(product_id=product.id, barcode=barcode)
    db.session.add(row)
    db.session.commit()
    return barcode


def assign_product_barcode(product, barcode='', barcode_type='internal'):
    clean_value = re.sub(r'[^A-Za-z0-9_.-]', '', (barcode or '').strip()[:80])
    if not clean_value:
        return product_barcode_value(product)
    existing = ProductBarcode.query.filter_by(barcode=clean_value).first()
    if existing and existing.product_id != product.id:
        raise ValueError('That barcode is already assigned to another product.')
    row = ProductBarcode.query.filter_by(product_id=product.id).first()
    if row:
        row.barcode = clean_value
        row.barcode_type = barcode_type
    else:
        db.session.add(ProductBarcode(product_id=product.id, barcode=clean_value, barcode_type=barcode_type))
    return clean_value


def product_by_barcode(value):
    clean_value = (value or '').strip()
    if not clean_value:
        return None
    row = ProductBarcode.query.filter_by(barcode=clean_value).first()
    if row:
        return row.product
    row = ProductBarcode.query.filter(ProductBarcode.barcode.ilike(clean_value)).first()
    if row:
        return row.product
    if clean_value.isdigit():
        row = ProductBarcode.query.filter(ProductBarcode.barcode.ilike(f'%{clean_value}')).first()
        if row:
            return row.product
    return None


def product_from_pos_choice(id_value=None, typed_value=''):
    if id_value:
        try:
            product = Product.query.get(int(id_value))
            if product:
                return product
        except (TypeError, ValueError):
            pass
    typed = (typed_value or '').strip()
    if not typed:
        return None
    product = product_by_barcode(typed)
    if product:
        return product
    if typed.isdigit():
        product = Product.query.get(int(typed))
        if product:
            return product
    return (
        Product.query.filter(Product.name.ilike(typed)).first()
        or Product.query.filter(Product.name.ilike(f'%{typed}%')).first()
    )


def normalize_scan_action(value):
    action = (value or 'add').strip().lower()
    return action if action in {'add', 'remove'} else 'add'


def pos_terminal_key(user_id=None):
    uid = user_id or (current_user.id if current_user.is_authenticated else 0)
    return f'pos_terminal_cart_{uid}'


# A till cart has to outlive a long shift but not the week. Held in the ephemeral
# store rather than the settings table: it is rewritten on every scan, and the
# settings table is read-cached, which would hand the till a cart from thirty
# seconds ago.
POS_CART_TTL_SECONDS = int_env('POS_CART_TTL_SECONDS', 12 * 3600)


def pos_terminal_cart(user_id=None):
    data = ephemeral_get_json(pos_terminal_key(user_id), [])
    if not isinstance(data, list):
        data = []
    return [line for line in data if line.get('product_id') and line.get('quantity')]


def save_pos_terminal_cart(lines, user_id=None):
    clean_lines = []
    for line in lines:
        product_id = int(line.get('product_id') or 0)
        quantity = max(1, int(line.get('quantity') or 1))
        if product_id:
            clean_lines.append({'product_id': product_id, 'quantity': quantity})
    ephemeral_set(pos_terminal_key(user_id), clean_lines,
                  ttl_seconds=POS_CART_TTL_SECONDS)


def pos_product_out_of_stock(product):
    """True when a scanned product has no stock left to sell.

    Digital goods have nothing to count, so they are always sellable. Used by every
    scan entry point to route a sold-out barcode to the registration form instead of
    the cart.
    """
    if product is None:
        return False
    if getattr(product, 'is_digital', False):
        return False
    return int(product.stock or 0) <= 0


def pos_out_of_stock_response(product, barcode):
    """Payload telling the POS screen to send this barcode to Register Product."""
    return {
        'success': False,
        'out_of_stock': True,
        'register_barcode': (barcode or getattr(product, 'pos_barcode', '') or ''),
        'product_id': product.id,
        'product_name': product.name,
        'error': f'{product.name} is out of stock. Barcode moved to Register Product.',
    }


def add_product_to_pos_terminal(product, quantity=1, user_id=None):
    lines = pos_terminal_cart(user_id)
    for line in lines:
        if int(line['product_id']) == product.id:
            line['quantity'] = max(1, int(line['quantity']) + max(1, int(quantity or 1)))
            save_pos_terminal_cart(lines, user_id)
            return lines
    lines.append({'product_id': product.id, 'quantity': max(1, int(quantity or 1))})
    save_pos_terminal_cart(lines, user_id)
    return lines


def remove_product_from_pos_terminal(product, quantity=1, user_id=None):
    lines = pos_terminal_cart(user_id)
    remove_quantity = max(1, int(quantity or 1))
    updated = []
    for line in lines:
        if int(line['product_id']) != product.id:
            updated.append(line)
            continue
        remaining = int(line.get('quantity') or 1) - remove_quantity
        if remaining > 0:
            line['quantity'] = remaining
            updated.append(line)
    save_pos_terminal_cart(updated, user_id)
    return updated


def pos_terminal_payload(user_id=None):
    rows = []
    subtotal = 0.0
    for line in pos_terminal_cart(user_id):
        product = Product.query.get(line['product_id'])
        if not product or not product.is_active:
            continue
        quantity = max(1, int(line.get('quantity') or 1))
        pricing = pos_line_pricing(product, quantity)
        unit_price = pricing['unit_price']
        line_total = pricing['line_total']
        subtotal += line_total
        rows.append({
            'product_id': product.id,
            'name': product.name,
            'barcode': product_barcode_value(product),
            'quantity': quantity,
            'list_unit': pricing['list_unit'],
            'unit_price': unit_price,
            'discount_amount': pricing['discount_amount'],
            'tax_amount': pricing['tax_amount'],
            'line_total': line_total,
            'stock': product.stock or 0,
            'low_stock': not product.is_digital and (product.stock or 0) <= 5,
        })
    return {'items': rows, 'subtotal': subtotal, 'count': sum(item['quantity'] for item in rows)}


def scanner_pairing_key(token):
    return f'pos_scanner_pair_{token}'


# One pairing covers a working day at the till.
SCANNER_PAIRING_TTL_SECONDS = int_env('SCANNER_PAIRING_TTL_SECONDS', 8 * 3600)


def local_network_base_url():
    configured = Setting.get('pos_public_base_url', '').strip()
    if configured:
        return configured.rstrip('/') + '/'
    host_url = request.host_url
    host = request.host.split(':')[0]
    if host not in ['localhost', '127.0.0.1']:
        return host_url
    try:
        lan_ip = socket.gethostbyname(socket.gethostname())
        port = request.host.split(':')[1] if ':' in request.host else '5000'
        if lan_ip and not lan_ip.startswith('127.'):
            return f'{request.scheme}://{lan_ip}:{port}/'
    except Exception:
        pass
    return host_url


def create_pos_scanner_pairing(user_id=None):
    user_id = user_id or current_user.id
    token = uuid.uuid4().hex[:16].upper()
    payload = {
        'user_id': user_id,
        'created_at': utcnow().isoformat(),
        'expires_at': (utcnow() + timedelta(seconds=SCANNER_PAIRING_TTL_SECONDS)).isoformat(),
        'terminal': f'POS-{user_id}',
    }
    # Ephemeral rather than a settings row: a pairing is a live session, and the
    # store's own expiry means an abandoned pairing is swept instead of sitting in
    # the settings table forever.
    ephemeral_set(scanner_pairing_key(token), payload,
                  ttl_seconds=SCANNER_PAIRING_TTL_SECONDS)
    scanner_url = local_network_base_url().rstrip('/') + url_for('pos_pair_scanner', token=token)
    return {'token': token, 'scanner_url': scanner_url, **payload}


def scanner_pairing_payload(token):
    clean_token = re.sub(r'[^A-Fa-f0-9]', '', (token or '').strip())[:32].upper()
    if not clean_token:
        return None
    payload = ephemeral_get_json(scanner_pairing_key(clean_token))
    if not payload:
        return None
    # The store expires the row on its own; this second check keeps the payload's
    # own deadline authoritative, so shortening the window takes effect for
    # pairings already handed out.
    try:
        expires_at = datetime.fromisoformat(payload.get('expires_at'))
    except Exception:
        return None
    if expires_at < utcnow():
        ephemeral_delete(scanner_pairing_key(clean_token))
        return None
    payload['token'] = clean_token
    return payload


def pos_role_permissions(user=None):
    user = user or current_user
    level = (getattr(user, 'admin_level', '') or '').lower()
    if level == 'mvp':
        role = 'Administrator'
        allowed = {'sell', 'inventory', 'products', 'suppliers', 'reports', 'settings'}
    elif level == 'super_admin':
        role = 'Super Admin'
        allowed = {'sell', 'inventory', 'products', 'suppliers', 'reports'}
    elif level == 'manager':
        role = 'Manager'
        allowed = {'sell', 'inventory', 'products', 'suppliers', 'reports'}
    elif level == 'inventory':
        role = 'Inventory Officer'
        allowed = {'inventory', 'products', 'suppliers', 'reports'}
    elif level == 'cashier':
        role = 'Cashier'
        allowed = {'sell'}
    else:
        role = 'Administrator' if getattr(user, 'is_admin', False) else 'User'
        allowed = {'sell', 'inventory', 'products', 'suppliers', 'reports'} if getattr(user, 'is_admin', False) else set()
    return {'role': role, 'allowed': allowed}


def pos_can(permission):
    return permission in pos_role_permissions()['allowed']


def record_stock_movement(product, movement_type, quantity, reference_type='', reference_id=None, note=''):
    before_stock = int(product.stock or 0)
    product.stock = max(0, before_stock + int(quantity))
    movement = StockMovement(
        product_id=product.id,
        movement_type=movement_type,
        quantity=int(quantity),
        before_stock=before_stock,
        after_stock=product.stock,
        reference_type=reference_type,
        reference_id=reference_id,
        note=note,
        created_by=current_user.id if current_user.is_authenticated else None,
    )
    db.session.add(movement)
    return movement


def create_bnpl_installments(plan):
    if plan.installments:
        return
    deposit_amount = plan.principal_amount * (plan.deposit_percent / 100)
    financed_amount = max(0.0, plan.principal_amount - deposit_amount)
    monthly_amount = round(financed_amount / max(1, plan.term_months), 2)
    for sequence in range(1, plan.term_months + 1):
        db.session.add(BNPLInstallment(
            plan_id=plan.id,
            sequence=sequence,
            amount_due=monthly_amount,
            due_at=utcnow() + timedelta(days=30 * sequence),
        ))


def generate_bnpl_lock_code(plan=None):
    seed = f"{getattr(plan, 'id', '')}:{uuid.uuid4().hex}".encode()
    digest = hashlib.sha256(seed).hexdigest().upper()
    return f"BNPL-{digest[:4]}-{digest[4:8]}-{digest[8:12]}"


def normalize_imei(value):
    return re.sub(r'\D', '', (value or '').strip())[:20]


def imei_checksum_valid(value):
    """Does this look like a real IMEI rather than fifteen typed digits?

    An IMEI carries a Luhn check digit, so 123456789012345 - the number somebody
    reaches for when a form insists on fifteen digits - fails arithmetic that a
    genuine handset's number passes. It proves the number is well formed, not that
    the handset exists; that is all a checksum can do, and it is still the cheapest
    filter available.
    """
    digits = normalize_imei(value)
    if len(digits) != 15 or not digits.isdigit():
        return False
    # Rejects 000000000000000 and the other all-same-digit placeholders, which
    # happen to satisfy Luhn.
    if len(set(digits)) == 1:
        return False
    total = 0
    # Doubling every second digit from the right, i.e. positions 13, 11, 9 ... of
    # the 14-digit body, with the 15th as the check digit.
    for index, char in enumerate(reversed(digits)):
        digit = int(char)
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0


def bnpl_remote_functional_code(plan):
    seed = f'{plan.id}:{plan.user_id}:{plan.product_id}:{plan.device_imei or ""}:{plan.device_lock_code or ""}'
    digest = hmac.new(app.config['SECRET_KEY'].encode(), seed.encode(), hashlib.sha256).hexdigest().upper()
    return f'SMARK-{digest[:6]}-{digest[6:12]}'


def build_bnpl_device_payload(plan):
    if not plan.device_lock_code:
        plan.device_lock_code = generate_bnpl_lock_code(plan)
    remote_code = bnpl_remote_functional_code(plan)
    payload = {
        'platform': 'SMARK-Africa BNPL',
        'plan_id': plan.id,
        'customer_id': plan.user_id,
        'product_id': plan.product_id,
        'imei': plan.device_imei or '',
        'serial': plan.device_serial or '',
        'install_method': plan.device_install_method or 'imei',
        'remote_functional_code': remote_code,
        'lock_code': plan.device_lock_code,
        'lock_status': plan.lock_status or 'unlocked',
        'allowed_when_locked': ['emergency_calls', 'sms', 'mpesa_payment', 'smark_africa_bnpl_portal'],
        'callback_url': (Setting.get('app_base_url', '') or request.host_url.rstrip('/')).rstrip() + url_for('admin_bnpl_device_callback'),
        'generated_at': utcnow().isoformat(),
    }
    plan.device_remote_payload = json.dumps(payload, indent=2)
    return payload


def update_bnpl_device_fields(plan):
    imei = normalize_imei(request.form.get('device_imei', plan.device_imei or ''))
    serial = request.form.get('device_serial', plan.device_serial or '').strip()[:80]
    method = request.form.get('device_install_method', plan.device_install_method or 'imei')
    if method not in {'imei', 'usb'}:
        method = 'imei'
    if imei:
        plan.device_imei = imei
    plan.device_serial = serial
    plan.device_install_method = method
    plan.device_status_note = request.form.get('device_status_note', plan.device_status_note or '').strip()
    if request.form.get('mark_installed') == '1':
        plan.device_install_status = 'installed'
        plan.device_installed_at = utcnow()
    elif plan.device_imei or plan.device_lock_code:
        plan.device_install_status = plan.device_install_status or 'ready'
    build_bnpl_device_payload(plan)


def update_bnpl_lock_status(plan):
    overdue = any(item.status != 'paid' and item.due_at < utcnow() for item in plan.installments)
    if overdue and plan.approval_status == 'approved':
        plan.lock_status = 'locked'
    elif all(item.status == 'paid' for item in plan.installments) and plan.installments:
        plan.lock_status = 'unlocked'
        plan.approval_status = 'completed'
    return plan.lock_status


