def ensure_customer_notifications(user, limit=8):
    # Unpaid checkouts are not orders yet, so they get no tracking or payment notices.
    orders = Order.query.filter(
        Order.user_id == user.id,
        Order.payment_status.in_(ORDER_PAID_STATUSES)
    ).order_by(Order.updated_at.desc(), Order.created_at.desc()).limit(limit).all()
    for order in orders:
        physical_items = [item for item in order.items if not item.is_digital]
        if physical_items:
            title = f'Order {order.order_number} tracking update'
            location = order.shipping_city or order.shipping_state or order.shipping_country or 'your delivery route'
            body = f'{order.shipping_status or order.status or "Processing"}: {len(physical_items)} physical item(s) are being prepared for {location}.'
            if order.tracking_number:
                body += f' Tracking number: {order.tracking_number}.'
            create_customer_notification(user.id, title, body, 'tracking')
        if order.payment_status == 'completed':
            create_customer_notification(
                user.id,
                f'Payment confirmed for {order.order_number}',
                f'Your secure platform payment was confirmed. You can follow order progress from My Orders and Track Order.',
                'payment'
            )

    follows = CategoryFollow.query.filter_by(user_id=user.id, email_updates=True).all()
    followed_ids = [follow.category_id for follow in follows]
    if followed_ids:
        since = user.last_login or (utcnow() - timedelta(days=14))
        products = Product.query.filter(
            Product.is_active == True,
            Product.category_id.in_(followed_ids),
            Product.created_at >= since
        ).order_by(Product.created_at.desc()).limit(limit).all()
        for product in products:
            create_customer_notification(
                user.id,
                f'New listing in {product.category.name if product.category else "your followed category"}',
                f'{product.name} was listed at KSh {(product.discounted_price or product.selling_price):,.2f}.',
                'new_listing',
                product.id
            )

    alerts = PriceAlert.query.filter_by(user_id=user.id, status='active').limit(limit).all()
    for alert in alerts:
        candidates = [alert.product] if alert.product else [item['product'] for item in smart_product_recommendations(alert.search_query or '', 6)]
        for product in candidates:
            if product and (product.discounted_price or product.selling_price or 0) <= alert.target_price:
                create_customer_notification(
                    user.id,
                    f'Price alert matched: {product.name[:80]}',
                    f'{product.name} is now KSh {(product.discounted_price or product.selling_price):,.2f}, within your target of KSh {alert.target_price:,.2f}.',
                    'price',
                    product.id
                )
                break
    db.session.commit()


def homepage_featured_products(limit=12):
    rows = []
    seen = set()
    # The two outerjoins below are for ORDER BY only - joining users does not
    # populate Product.seller, which is lazy - so the badge macro would still fire
    # one query per card. joinedload is many-to-one here, a LEFT JOIN that cannot
    # multiply rows, so the limit above stays exact.
    eager = (joinedload(Product.seller),)
    queries = [
        Product.query.options(*eager).filter_by(is_active=True, is_hot_sale=True).order_by(Product.hot_sale_started_at.desc(), Product.updated_at.desc()),
        Product.query.options(*eager).filter_by(is_active=True, is_featured=True).outerjoin(User, Product.seller_id == User.id).order_by(Product.admin_priority.desc(), User.seller_rating.desc(), Product.created_at.desc()),
        Product.query.options(*eager).filter_by(is_active=True).outerjoin(User, Product.seller_id == User.id).order_by(Product.admin_priority.desc(), User.seller_rating.desc(), Product.created_at.desc()),
    ]
    for query in queries:
        for product in query.limit(limit).all():
            if product.id in seen:
                continue
            seen.add(product.id)
            rows.append(product)
            if len(rows) >= limit:
                return rows
    return rows


def product_search_cache_key(search='', category_slug='', product_type='', sort='newest'):
    version = 'nocache'
    if cache:
        version = cache.get('product_search_cache_version') or 'v1'
    clean = '|'.join([
        str(version),
        # The first two reach SQL as values, so they must stay injective: search
        # becomes an ILIKE pattern, and category_slug is matched with a
        # case-sensitive '=', which is why it keeps its case where search does not.
        search_cache_token(search or '', 60),
        exact_cache_token(category_slug or 'all', 80),
        # The last two are read through the same functions the query branches on, so
        # every value producing identical SQL lands in one bucket and no value that
        # changes the SQL can share one. Collapsing them here rather than trusting
        # the raw text is what keeps ?sort=! from being a fresh entry per request,
        # and reading them from the query's own helpers is what keeps that collapse
        # from ever becoming false sharing.
        effective_product_type(product_type),
        effective_sort(sort),
    ])
    return f'product_search_ids:{clean}'


def effective_product_type(value):
    """The only two product-type values the search actually filters on.

    Anything else - '', 'DIGITAL', 'nonsense' - filters on nothing, so it is the same
    query as no filter at all and belongs in one cache bucket. Keeping this beside
    the builder, and having the builder branch on it, is what stops the cache key
    from disagreeing with the SQL: a key that lowercased its input mapped 'DIGITAL',
    which does not filter, onto the same entry as 'digital', which does.
    """
    return value if value in ('digital', 'physical') else 'any'


def effective_sort(value):
    """The ORDER BY branch a sort value selects.

    'rating' and 'popular' take the same branch, and every unrecognised value takes
    the default, so all of them are one cached result. This is what makes ?sort=!
    one cache entry instead of one per request, and it is safe only because the
    builder below branches on this same function rather than on the raw value.
    """
    if value in ('price_low', 'price_high'):
        return value
    if value in ('rating', 'popular'):
        return 'popular'
    return 'newest'


def build_product_search_query(search='', category_slug='', product_type='', sort='newest',
                               extra_terms=None):
    """Build the product search query.

    ``extra_terms`` widens the text match with related keywords and is only ever
    passed by the semantic-search path. It defaults to None, in which case the
    generated SQL is identical to what this function produced before that path
    existed - every other caller is unaffected.
    """
    query = Product.query.filter_by(is_active=True)
    current_category = None
    if category_slug:
        current_category = Category.query.filter_by(slug=category_slug).first()
        if current_category:
            query = query.filter_by(category_id=current_category.id)
    product_type = effective_product_type(product_type)
    if product_type == 'digital':
        query = query.filter_by(is_digital=True)
    elif product_type == 'physical':
        query = query.filter_by(is_digital=False)
    if search:
        clauses = []
        for term in [search] + [t for t in (extra_terms or []) if t]:
            like = f'%{term}%'
            clauses.extend([
                Product.name.ilike(like),
                Product.description.ilike(like),
                Product.short_description.ilike(like),
            ])
        query = query.filter(or_(*clauses))
    sort = effective_sort(sort)
    if sort == 'price_low':
        query = query.outerjoin(User, Product.seller_id == User.id).order_by(Product.is_hot_sale.desc(), Product.admin_priority.desc(), User.seller_rating.desc(), Product.selling_price.asc())
    elif sort == 'price_high':
        query = query.outerjoin(User, Product.seller_id == User.id).order_by(Product.is_hot_sale.desc(), Product.admin_priority.desc(), User.seller_rating.desc(), Product.selling_price.desc())
    elif sort == 'popular':
        query = query.outerjoin(User, Product.seller_id == User.id).order_by(Product.is_hot_sale.desc(), Product.admin_priority.desc(), User.seller_rating.desc(), Product.sales_count.desc())
    else:
        query = query.outerjoin(User, Product.seller_id == User.id).order_by(Product.is_hot_sale.desc(), Product.admin_priority.desc(), User.seller_rating.desc(), Product.created_at.desc())
    return query, current_category


def invalidate_product_cache():
    """Invalidate product search caches without clearing unrelated global caches."""
    if cache:
        cache.set('product_search_cache_version', uuid.uuid4().hex, timeout=86400)
        cache.delete('hot_sale_pop_product_id')


# How many reviews one page of a listing shows. Reviews only ever accumulate, and
# nobody reads the four hundredth one, so the page shows a page of them.
REVIEWS_PER_PAGE = int_env('REVIEWS_PER_PAGE', 10)

# Order history and a seller's catalogue both grow for as long as an account is
# used, so neither can be rendered whole. Bulk digital upload makes the second one
# urgent: one afternoon of uploading is a few thousand listings.
ORDERS_PER_PAGE = int_env('ORDERS_PER_PAGE', 20)
SELLER_PRODUCTS_PER_PAGE = int_env('SELLER_PRODUCTS_PER_PAGE', 25)

# Every product page view used to be a write and a commit on the product row, so
# the more popular a listing got the more its viewers serialised behind each other
# on the same lock. Now the deltas are held per worker and written together.
_product_view_buffer = CounterBuffer(
    flush_after=int_env('VIEW_COUNT_FLUSH_AFTER', 50),
    flush_seconds=float_env('VIEW_COUNT_FLUSH_SECONDS', 30),
    name='product-views')


def flush_product_views(pending=None):
    """Write buffered view counts. Returns the number of products updated.

    One UPDATE per product, and the increment happens in the database rather than
    in Python, so two workers flushing the same product at the same time add up
    instead of overwriting each other. coalesce because rows predating the column
    have NULL there, and NULL + 1 is NULL.
    """
    pending = _product_view_buffer.drain() if pending is None else pending
    if not pending:
        return 0
    try:
        for product_id, delta in pending.items():
            db.session.query(Product).filter(Product.id == product_id).update(
                {Product.views_count: func.coalesce(Product.views_count, 0) + delta},
                synchronize_session=False)
        db.session.commit()
        return len(pending)
    except SQLAlchemyError:
        # A view count is not worth failing a page render over, and not worth
        # replaying either - dropping this batch is the whole point of the trade.
        db.session.rollback()
        logger.warning('Could not flush %d buffered product view counts', len(pending))
        return 0


def record_product_view(product):
    """Count one view of ``product`` without writing on every request."""
    due = _product_view_buffer.add(product.id)
    if due:
        flush_product_views(due)


# The category nav appears on the home page, the shop and every filter bar, so
# this is the single most-executed query on the platform - every visitor runs it
# and every visitor gets the same answer. Cached in-process, which makes the
# repeat a dict lookup instead of a round trip.
NAV_CATEGORY_TTL = float_env('NAV_CATEGORY_CACHE_SECONDS', 120)
_nav_category_cache = TTLCache(ttl_seconds=NAV_CATEGORY_TTL, max_entries=4,
                               name='nav-categories')


class NavCategory:
    """The three fields templates actually read off a nav category.

    Deliberately not a Category. ORM instances belong to the session that loaded
    them, so caching them across requests hands the next request detached objects
    that raise the moment a template touches an unloaded attribute. Plain values
    have no session to be detached from.
    """

    __slots__ = ('id', 'name', 'slug')

    def __init__(self, id, name, slug):
        self.id = id
        self.name = name
        self.slug = slug


def nav_categories(active_only=True):
    """The category list for nav bars and filter dropdowns, cached.

    Staleness here is a category appearing in the menu up to NAV_CATEGORY_TTL
    seconds late, which is worth trading for not asking the database the same
    question on every page view. Admin edits invalidate it immediately anyway.
    """
    key = 'active' if active_only else 'all'
    found = _nav_category_cache.lookup(key)
    if found is not CACHE_MISS:
        return found
    query = db.session.query(Category.id, Category.name, Category.slug)
    if active_only:
        query = query.filter(Category.is_active.is_(True))
    rows = [NavCategory(row[0], row[1], row[2])
            for row in query.order_by(Category.name.asc()).all()]
    return _nav_category_cache.set(key, rows)


def invalidate_nav_categories():
    _nav_category_cache.clear()


# ---------- Semantic search ----------
# A search for "bluetooth jammer" should find the ESP32 board somebody listed,
# because that is what the person actually wants. Nothing here is surfaced as a
# feature: there is no "AI results" heading, no badge, no second results block.
# Expanded matches are appended to the ordinary result list and the page renders
# exactly as it always did, which is the whole requirement.
#
# It only runs when the plain search found almost nothing. That is both where it
# helps and what keeps it affordable: a query that already works is never
# touched, so the expensive path is reached by the queries that currently return
# an empty page, not by the traffic.

# Expansion is attempted when the ordinary search returns this many results or
# fewer. Above it, the searcher already has something to look at.
SEMANTIC_SEARCH_MIN_RESULTS = int_env('SEMANTIC_SEARCH_MIN_RESULTS', 3)

# Seed concepts, overridable by the `search_concept_map` Setting (a JSON object)
# so an admin can teach it a term without a deploy. Keys are matched against the
# whole normalised query and as substrings of it, so "cheap bluetooth jammer"
# hits the same entry as "bluetooth jammer".
DEFAULT_SEARCH_CONCEPTS = {
    'bluetooth jammer': ['esp32', 'nrf24', 'deauther'],
    'wifi jammer': ['esp32', 'deauther', 'nodemcu'],
    'signal blocker': ['esp32', 'nrf24'],
    'gps tracker': ['sim800', 'neo-6m', 'gps module'],
    'microcontroller': ['esp32', 'arduino', 'nodemcu', 'raspberry pi'],
    'power bank': ['powerbank', 'battery pack'],
    'flash disk': ['flash drive', 'usb drive', 'thumb drive'],
    'laptop charger': ['power adapter', 'ac adapter'],
    'phone case': ['back cover', 'phone cover'],
    'earphones': ['earbuds', 'headphones', 'airpods'],
    'nursing notes': ['nursing exam', 'nursing revision', 'kmtc'],
    'past papers': ['revision papers', 'exam papers', 'past exams'],
    'assignment help': ['assignment', 'coursework', 'essay'],
}

# Terms already expanded, and the ones that came back empty. Caching the misses
# matters more than caching the hits: without it every repeat of an unanswerable
# query pays the full cost again.
_search_expansion_cache = TTLCache(
    ttl_seconds=float_env('SEMANTIC_SEARCH_TTL', 900), max_entries=512,
    name='search-expansion')

# The AI layer is off by default, deliberately. It is a network call on the
# search path, and the standing instruction for this platform is that a million
# users must not be able to make it slow - so it does not get switched on until
# its latency has actually been watched. With it off, the concept map above still
# answers the cases it knows, instantly and for free.
SEMANTIC_SEARCH_AI = bool_env('SEMANTIC_SEARCH_AI', False)
SEMANTIC_SEARCH_AI_TIMEOUT = float_env('SEMANTIC_SEARCH_AI_TIMEOUT', 2.5)
SEMANTIC_SEARCH_AI_PER_MINUTE = int_env('SEMANTIC_SEARCH_AI_PER_MINUTE', 30)

# Per-worker spend guard and failure breaker. A crawler walking thousands of
# nonsense queries would otherwise be thousands of API calls and thousands of
# occupied worker-seconds, and each one of those is a request some real customer
# is queued behind.
_search_ai_window = {'minute': -1, 'count': 0, 'blocked_until': None}


def normalise_search_text(text):
    """Lowercased, whitespace-collapsed query text used as a concept-map key."""
    return ' '.join((text or '').lower().split())


def search_concept_map():
    """The concept map, with any admin override merged over the seeds."""
    merged = dict(DEFAULT_SEARCH_CONCEPTS)
    raw = Setting.get('search_concept_map', '') or ''
    if raw.strip():
        try:
            override = json.loads(raw)
            if isinstance(override, dict):
                for key, values in override.items():
                    if isinstance(values, str):
                        values = [values]
                    if isinstance(values, (list, tuple)):
                        cleaned = [str(v).strip() for v in values if str(v).strip()]
                        if cleaned:
                            merged[normalise_search_text(key)] = cleaned
        except (ValueError, TypeError):
            # A malformed override must not take search down with it; the seeds
            # are still a working map.
            app.logger.warning('search_concept_map is not valid JSON; using seeds')
    return merged


def concept_expansion(text):
    """Related terms from the concept map, longest key first."""
    normalised = normalise_search_text(text)
    if not normalised:
        return []
    found = []
    # Longest key first so "wifi jammer" wins over a shorter key that also
    # happens to appear inside the same query.
    for key in sorted(search_concept_map(), key=len, reverse=True):
        if key and (key == normalised or key in normalised):
            for term in search_concept_map()[key]:
                if term.lower() not in normalised and term not in found:
                    found.append(term)
            if found:
                break
    return found[:6]


def ai_search_budget_available():
    """Whether this worker may spend another AI call this minute."""
    now = datetime.utcnow()
    blocked = _search_ai_window.get('blocked_until')
    if blocked and now < blocked:
        return False
    minute = now.hour * 60 + now.minute
    if _search_ai_window['minute'] != minute:
        _search_ai_window['minute'] = minute
        _search_ai_window['count'] = 0
    if _search_ai_window['count'] >= max(0, SEMANTIC_SEARCH_AI_PER_MINUTE):
        return False
    _search_ai_window['count'] += 1
    return True


def ai_expansion(text):
    """Related search keywords from the model, or [] for any reason at all.

    Reuses the existing OPENAI_API_KEY / openai_api_key lookup - this adds no new
    credential. Every failure path returns [], because the caller's fallback is
    the search results the site would have shown anyway.
    """
    if not SEMANTIC_SEARCH_AI:
        return []
    api_key = os.environ.get('OPENAI_API_KEY') or Setting.get('openai_api_key', '')
    if not api_key or not ai_search_budget_available():
        return []
    try:
        response = requests.post(
            'https://api.openai.com/v1/responses',
            headers={'Authorization': f'Bearer {api_key}',
                     'Content-Type': 'application/json'},
            json={
                'model': Setting.get('openai_search_model', 'gpt-4.1-mini'),
                'input': (
                    'A shopper searched an online marketplace for '
                    f'"{text}" and nothing matched. Reply with a JSON array of up '
                    'to 5 short product keywords that listings for what they want '
                    'would realistically be titled - component names, model '
                    'numbers or common alternative names. JSON array only.'
                ),
                'max_output_tokens': 120,
            },
            timeout=SEMANTIC_SEARCH_AI_TIMEOUT)
        if not response.ok:
            return []
        payload = response.json()
        raw = payload.get('output_text', '')
        if not raw:
            chunks = []
            for item in payload.get('output', []):
                for content in item.get('content', []):
                    if content.get('text'):
                        chunks.append(content['text'])
            raw = '\n'.join(chunks)
        start, end = raw.find('['), raw.rfind(']')
        if start == -1 or end <= start:
            return []
        terms = json.loads(raw[start:end + 1])
        cleaned = []
        for term in terms if isinstance(terms, list) else []:
            term = str(term).strip()[:40]
            if term and term.lower() not in normalise_search_text(text):
                cleaned.append(term)
        return cleaned[:5]
    except Exception:
        # Includes the timeout. Back off for a minute rather than letting every
        # thin search queue behind the same unhealthy endpoint.
        _search_ai_window['blocked_until'] = datetime.utcnow() + timedelta(seconds=60)
        return []


def expanded_search_terms(text):
    """Extra terms to widen a search that found nothing useful, or []."""
    normalised = normalise_search_text(text)
    # Single characters and pasted essays are both noise, and the second would be
    # a wasteful prompt.
    if len(normalised) < 3 or len(normalised) > 80:
        return []
    cached = _search_expansion_cache.lookup(normalised)
    if cached is not CACHE_MISS:
        return cached
    terms = concept_expansion(normalised) or ai_expansion(normalised)
    _search_expansion_cache.set(normalised, terms)
    return terms


_product_ids_cache = TTLCache(
    ttl_seconds=int_env('PRODUCT_SEARCH_IDS_TTL', 300),
    max_entries=int_env('PRODUCT_SEARCH_IDS_MAX', 2048),
    name='product-search-ids')

# Shared by the product and service searches: both are anonymous-reachable, both have
# one hot key per popular query, and both had a cold key costing one query per
# concurrent caller. The wait is bounded and falls through to computing anyway, so the
# worst case is the behaviour that was here before it. See SingleFlight in scale.py.
_search_flight = SingleFlight(stripes=int_env('SEARCH_FLIGHT_STRIPES', 64),
                              timeout=float_env('SEARCH_FLIGHT_WAIT', 2.5),
                              name='search-flight')


def search_ids_cache_target():
    """Where per-search id lists belong: 'shared', 'local' or 'off'.

    This is the one key space in this file that grows with traffic - one entry per
    distinct search, filter and sort combination - so it is the one that must never
    sit on FileSystemCache, which is the default backend whenever REDIS_URL is unset
    and no Redis stays a supported configuration. cachelib prunes that backend by
    listing the directory and opening every entry once the count passes
    CACHE_THRESHOLD, and because the prune only trims back down to the threshold
    rather than below it, every later set pays the scan again: measured on this
    machine at 896ms per set against 15ms below the threshold, a 59x cliff that
    never heals. One such write is one gunicorn worker thread blocked on disk, so
    under concurrent search traffic the instance stalls on its own cache.

    Raising CACHE_THRESHOLD is not the fix and is deliberately not done here: it
    delays the cliff by making each scan bigger. Keeping the growing key space off
    that backend is. The bounded in-process TTLCache used instead is the same choice
    already made for the services twin of this function, ``_service_ids_cache``.

    'off' is preserved exactly as it was, so a NullCache configured to keep query
    counts honest in the smoke checks is not quietly handed a cache instead. An
    unrecognised backend is treated as shared, which is the behaviour that was here
    before - only the filesystem backend has the cliff worth routing around.
    """
    if not cache:
        return 'off'
    backend = type(getattr(cache, 'cache', None)).__name__
    if backend == 'NullCache':
        return 'off'
    return 'local' if backend == 'FileSystemCache' else 'shared'


def cached_product_search_ids(search='', category_slug='', product_type='', sort='newest'):
    """Ids for a search, computed once per distinct query rather than per request.

    Wrapped in a single-flight so a *cold* key costs one query across every caller
    asking for it at that moment, not one query each. Measured before the wrapper:
    24 identical simultaneous callers ran 24 queries. A warm key already cost zero,
    so the wrapper changes nothing about the common case - it only closes the window
    around an expiry and around a deploy, which is when every worker's cache is empty
    under whatever traffic is already arriving. See tools/concurrency_smoke.py.
    """
    key = product_search_cache_key(search, category_slug, product_type, sort)
    target = search_ids_cache_target()

    def read():
        if target == 'local':
            cached_ids = _product_ids_cache.lookup(key)
            return CACHE_MISS if cached_ids is CACHE_MISS else unpack_ids(cached_ids)
        if target == 'shared':
            cached_ids = cache.get(key)
            # The shared backend has no miss sentinel of its own, so None has to
            # stand in for absent. An id list is never legitimately None - the empty
            # search returns [] - so nothing is lost by that.
            return CACHE_MISS if cached_ids is None else cached_ids
        return CACHE_MISS

    found = read()
    if found is not CACHE_MISS:
        return found
    if target == 'off':
        return _compute_product_search_ids(key, target, search, category_slug,
                                           product_type, sort)
    return _search_flight.run(
        key, read,
        lambda: _compute_product_search_ids(key, target, search, category_slug,
                                            product_type, sort))


def _compute_product_search_ids(key, target, search, category_slug, product_type, sort):
    query, _ = build_product_search_query(search, category_slug, product_type, sort)
    ids = [row[0] for row in query.with_entities(Product.id).limit(1000).all()]
    # A search that found almost nothing gets widened. The extra ids are appended,
    # never interleaved, so genuine matches still lead the page - and the widened
    # list is what gets cached, so the expansion is computed once per query rather
    # than once per search. Running under the single-flight also means concurrent
    # askers for one thin search make one expansion attempt between them rather than
    # one each, which matters most when SEMANTIC_SEARCH_AI is on and the per-minute
    # budget is small.
    if search and len(ids) <= SEMANTIC_SEARCH_MIN_RESULTS:
        try:
            extra = expanded_search_terms(search)
            if extra:
                wider, _ = build_product_search_query(
                    search, category_slug, product_type, sort, extra_terms=extra)
                seen = set(ids)
                for row in wider.with_entities(Product.id).limit(1000).all():
                    if row[0] not in seen:
                        seen.add(row[0])
                        ids.append(row[0])
        except Exception:
            # Widening is a bonus. If it breaks, the searcher still gets exactly
            # the results this function returned before it existed.
            app.logger.warning('search expansion failed for %r', search[:60])
    if target == 'local':
        # Per worker rather than shared, so each warms its own copy and the database
        # sees at most one miss per worker per distinct search per TTL - bounded, and
        # far cheaper than the alternative on this backend. Global invalidation still
        # works untouched: ``key`` contains product_search_cache_version, which stays
        # on the shared cache, so bumping it changes the key every worker computes.
        # The one thing it does not follow is the product_search_cache_seconds
        # Setting, since a TTLCache fixes its TTL at construction; PRODUCT_SEARCH_IDS_TTL
        # carries the same 300s default.
        #
        # Packed because this cache is resident for the life of the worker and its
        # size is the entry cap times the per-entry cost: 2048 entries of up to 1000
        # ids each is 70MB as lists and 16MB packed, against WORKER_MEMORY_MB=200.
        # See pack_ids in scale.py - short substrings each match a large slice of the
        # catalogue and are distinct keys, so the worst case is drivable, not just
        # theoretical.
        _product_ids_cache.set(key, pack_ids(ids))
    elif target == 'shared':
        cache.set(key, ids, timeout=int(Setting.get('product_search_cache_seconds', '300') or 300))
    return ids


def paginate_cached_ids(model, ids, page=1, per_page=12, options=None):
    """Page through an already-cached list of primary keys.

    One IN query for the page instead of a COUNT plus an OFFSET scan, and the
    ordering of ``ids`` is preserved rather than re-derived - the cached list is
    what decided the order, so re-sorting here would quietly disagree with it.

    Generic in ``model`` because services need exactly this and a second copy of
    the same class would drift from the product one on the first edit to either.
    ``options`` is that genericity's price: what a card reads off each row differs
    per model, so the caller passes the eager loads instead of this knowing them.

    ``page`` arrives straight off the query string on both the shop and the services
    page, so it is parsed defensively: a scanner appending ?page=2' or a stale link
    carrying ?page=abc gets the first page rather than a 500 on a public URL.
    """
    try:
        page = max(1, int(page or 1))
    except (TypeError, ValueError):
        page = 1
    try:
        per_page = max(1, min(60, int(per_page or 12)))
    except (TypeError, ValueError):
        per_page = 12
    total = len(ids)
    start = (page - 1) * per_page
    page_ids = ids[start:start + per_page]
    items = []
    if page_ids:
        query = model.query
        if options:
            query = query.options(*options)
        row_map = {row.id: row for row in query.filter(model.id.in_(page_ids)).all()}
        items = [row_map[pid] for pid in page_ids if pid in row_map]

    class CachedPagination:
        def __init__(self):
            self.page = page
            self.per_page = per_page
            self.total = total
            self.items = items
            self.pages = (total + per_page - 1) // per_page
            self.has_prev = page > 1
            self.has_next = page < self.pages
            self.prev_num = page - 1
            self.next_num = page + 1

        def iter_pages(self, left_edge=2, left_current=2, right_current=4,
                       right_edge=2):
            """Page numbers to render, with ``None`` marking each gap.

            Signature and semantics are taken from flask_sqlalchemy's Pagination,
            because being a drop-in for that is this class's whole purpose. The
            first version accepted no arguments at all, which meant any template
            written against the real object - services.html passes all four -
            raised TypeError inside the render as soon as a second page existed.
            A pagination shim that only works on page one is worse than none.
            """
            pages_end = self.pages + 1
            if pages_end == 1:
                return
            left_end = min(1 + left_edge, pages_end)
            yield from range(1, left_end)
            if left_end == pages_end:
                return
            mid_start = max(left_end, self.page - left_current)
            mid_end = min(self.page + right_current + 1, pages_end)
            if mid_start - left_end > 0:
                yield None
            yield from range(mid_start, mid_end)
            if mid_end == pages_end:
                return
            right_start = max(mid_end, pages_end - right_edge)
            if right_start - mid_end > 0:
                yield None
            yield from range(right_start, pages_end)

    return CachedPagination()


def paginate_cached_product_ids(ids, page=1, per_page=12):
    # seller is eager-loaded because the badge macro reads product.seller on every
    # card and Product.seller is lazy, so the one IN query the paginator runs would
    # otherwise be followed by one query per card - on /shop and on every category
    # page, for anonymous visitors, which is the traffic there is most of.
    return paginate_cached_ids(Product, ids, page=page, per_page=per_page,
                               options=(joinedload(Product.seller),))


def seller_identity_match_query(model, legal_name, country, phone, bank_card_last4):
    legal_name = (legal_name or '').strip()
    country = (country or '').strip()
    phone = normalize_mpesa_phone(phone or '')
    bank_card_last4 = (bank_card_last4 or '').strip()
    filters = []
    if legal_name and country:
        filters.append(and_(func.lower(model.legal_name) == legal_name.lower(), func.lower(model.country) == country.lower()))
    if phone:
        filters.append(model.phone == phone)
    if bank_card_last4:
        filters.append(model.bank_card_last4 == bank_card_last4)
    return or_(*filters) if filters else None


def matching_seller_blacklist(legal_name, country, phone, bank_card_last4):
    match_filter = seller_identity_match_query(SellerBlacklist, legal_name, country, phone, bank_card_last4)
    if match_filter is None:
        return None
    return SellerBlacklist.query.filter(match_filter, SellerBlacklist.status != 'appeal_approved').first()


def backup_seller_verification(verification):
    backup = SellerVerificationBackup(
        verification_id=verification.id,
        user_id=verification.user_id,
        legal_name=verification.legal_name,
        country=verification.country,
        phone=verification.phone,
        bank_card_last4=verification.bank_card_last4,
        document_type=verification.document_type,
        document_path=verification.document_path,
        selfie_path=verification.selfie_path,
        status=verification.status,
        notes=verification.notes,
    )
    db.session.add(backup)
    return backup


def kyc_system_only_enabled():
    return Setting.get('kyc_system_only_enabled', '0') == '1'


def seller_critical_mismatch_key(user_id):
    return f'seller_critical_mismatch_count_{user_id}'


def increment_seller_critical_mismatch(user, reason='Manual KYC mismatch'):
    # Atomic: this counter blacklists a seller at three, so a lost increment is a
    # fraud signal thrown away.
    count = Setting.bump_counter(seller_critical_mismatch_key(user.id), commit=False)
    if count >= 3:
        db.session.add(SellerBlacklist(
            legal_name=f'{user.first_name or ""} {user.last_name or ""}'.strip() or user.username,
            country=user.country,
            phone=normalize_mpesa_phone(user.phone),
            bank_card_last4=user.bank_card_last4,
            reason=f'{reason}. Critical mismatch count reached {count}.',
            status='active'
        ))
        user.seller_status = 'rejected'
        user.verification_status = 'blacklisted'
        user.is_verified_seller = False
        if user.email:
            send_email(
                user.email,
                'SMARK-Africa seller verification blocked',
                '<p>Your seller application has failed critical verification checks three times. The seller option is blocked unless an appeal is approved by the MVP.</p>'
            )
    return count


def product_search_score(product, query):
    text = ' '.join([
        product.name or '',
        product.short_description or '',
        product.description or '',
        product.category.name if product.category else '',
        product.product_condition or '',
    ]).lower()
    terms = [term for term in slugify(query, 500).split('-') if len(term) > 2]
    score = sum(4 for term in terms if term in text)
    q = (query or '').lower()
    price = product.discounted_price or product.selling_price or 0
    if any(word in q for word in ['cheap', 'budget', 'under', 'student']) and price:
        score += max(0, 5 - int(price / 20000))
    if any(word in q for word in ['battery', 'gaming', 'software', 'engineering', 'laptop', 'monitor']) and any(word in text for word in ['battery', 'gaming', 'software', 'laptop', 'monitor', 'computer']):
        score += 5
    if any(word in q for word in ['rain', 'water', 'weather']) and any(word in text for word in ['water', 'rain', 'boot', 'rubber', 'weather']):
        score += 5
    if product.average_rating:
        score += product.average_rating
    score += min(product.stock or 0, 10) / 10
    return score


def smart_product_recommendations(query, limit=6):
    products = Product.query.filter_by(is_active=True).all()
    scored = sorted(
        [(product_search_score(product, query), product) for product in products],
        key=lambda item: item[0],
        reverse=True
    )
    recommendations = []
    for score, product in scored[:limit]:
        if score <= 0 and query:
            continue
        recommendations.append({
            'product': product,
            'score': round(score, 1),
            'reason': smart_recommendation_reason(product, query),
        })
    return recommendations


def allowed_digital_file(filename):
    return (
        '.' in filename and
        filename.rsplit('.', 1)[1].lower() in ALLOWED_DIGITAL_EXTENSIONS
    )


SPEC_PATTERNS = {
    'Display': r'(\d+(?:\.\d+)?\s?(?:inch|inches|"))|(?:AMOLED|OLED|LCD|IPS|QLED|UHD|4K)',
    'Processor': r'(Snapdragon\s?\w+|MediaTek\s?\w+|Intel\s?[A-Za-z0-9\- ]+|Core\s?i[3579][A-Za-z0-9\- ]*|Ryzen\s?[A-Za-z0-9\- ]+|Apple\s?M\d)',
    'RAM': r'(\d+\s?GB\s?RAM|\d+\s?GB\s?memory)',
    'Storage': r'(\d+\s?(?:GB|TB)\s?(?:storage|SSD|HDD|ROM|NVMe)?)',
    'Battery': r'(\d{3,5}\s?mAh|battery\s?\d{3,5}\s?mAh)',
    'Camera': r'(\d+\s?MP|camera)',
    'Refresh Rate': r'(\d+\s?Hz)',
    'Resolution': r'(4K|8K|1080p|1440p|\d{3,4}\s?x\s?\d{3,4})',
    'Connectivity': r'(5G|4G|Wi-?Fi\s?6|Bluetooth\s?\d(?:\.\d)?)',
    'Weight': r'(\d+(?:\.\d+)?\s?(?:kg|g))',
    'Warranty': r'(\d+\s?(?:year|month)s?\s?warranty)',
}


def extract_specs_from_text(text_value):
    specs = {}
    text_value = re.sub(r'\s+', ' ', html.unescape(str(text_value or '')))
    for label, pattern in SPEC_PATTERNS.items():
        matches = re.findall(pattern, text_value, flags=re.IGNORECASE)
        cleaned = []
        for match in matches:
            if isinstance(match, tuple):
                match = next((part for part in match if part), '')
            value = str(match).strip()
            if value and value.lower() not in [item.lower() for item in cleaned]:
                cleaned.append(value)
        if cleaned:
            specs[label] = ', '.join(cleaned[:4])
    return specs


def web_spec_lookup(product_name):
    query = f'{product_name} specifications'
    sources = []
    combined_text = ''
    headers = {'User-Agent': 'Mozilla/5.0 SMARKAFRICA product comparison'}
    search_urls = [
        f'https://html.duckduckgo.com/html/?q={requests.utils.quote(query)}',
        f'https://r.jina.ai/http://r.jina.ai/http://www.google.com/search?q={requests.utils.quote(query)}',
    ]
    for search_url in search_urls:
        try:
            response = requests.get(search_url, timeout=8, headers=headers)
            if response.status_code >= 400:
                continue
            page_text = re.sub(r'<[^>]+>', ' ', response.text)
            page_text = re.sub(r'\s+', ' ', html.unescape(page_text))
            combined_text += ' ' + page_text[:5000]
            for url in re.findall(r'https?://[^\s"&<>]+', response.text):
                if len(sources) >= 3:
                    break
                if not any(blocked in url.lower() for blocked in ['duckduckgo', 'google', 'gstatic']):
                    sources.append(url.rstrip(').,'))
            if combined_text:
                break
        except Exception as exc:
            app.logger.info('Web spec lookup failed for %s: %s', product_name, exc)
    return extract_specs_from_text(combined_text), sources[:3]


def product_compare_payload(product, include_web=True):
    store_text = ' '.join([
        product.name or '',
        product.short_description or '',
        product.description or '',
        product.category.name if product.category else '',
    ])
    merged = extract_specs_from_text(store_text)
    sources = []
    if include_web:
        web_specs, sources = web_spec_lookup(product.name)
        merged.update({key: value for key, value in web_specs.items() if value})
    market_reference = market_price_reference(
        product.name,
        product.category_id,
        product.discounted_price or product.selling_price,
        product.buying_price,
        exclude_id=product.id,
        description=product.description
    ) if include_web else {}
    return {
        'id': product.id,
        'name': product.name,
        'category': product.category.name if product.category else 'General',
        'price': product.discounted_price or product.selling_price,
        'in_stock': bool(product.is_digital or (product.stock or 0) > 0),
        'stock': 'Digital' if product.is_digital else str(product.stock or 0),
        'rating': product.average_rating,
        'specs': merged,
        'sources': sources,
        'market': market_reference,
        'url': url_for('product_page', slug=product.slug),
    }


def build_product_comparison(recommendations):
    comparison = []
    for item in recommendations[:3]:
        product = item['product']
        comparison.append({
            'name': product.name,
            'price': product.discounted_price or product.selling_price or 0,
            'rating': product.average_rating,
            'stock': product.stock,
            'category': product.category.name if product.category else 'General',
            'best_for': item['reason'],
            'risk': 'Low stock' if not product.is_digital and (product.stock or 0) <= 5 else 'Stable availability',
        })
    return comparison


def smart_recommendation_reason(product, query):
    reasons = []
    q = (query or '').lower()
    if product.average_rating:
        reasons.append(f'{product.average_rating:.1f}/5 average rating')
    if product.stock and product.stock > 0:
        reasons.append(f'{product.stock} in stock')
    if product.discount_percent:
        reasons.append(f'{product.discount_percent:.0f}% price drop')
    if product.category:
        reasons.append(f'fits {product.category.name}')
    if 'student' in q or 'budget' in q or 'under' in q:
        reasons.append('balanced for budget-sensitive buying')
    if not reasons:
        reasons.append('closest match from product details and pricing')
    return ', '.join(reasons[:3])


def pricing_suggestions():
    suggestions = []
    for product in Product.query.filter_by(is_active=True).order_by(Product.updated_at.desc()).limit(80).all():
        market = build_market_intelligence_payload(str(product.category_id or 'all'))['rows']
        signal = market[0] if market else None
        current = product.discounted_price or product.selling_price or 0
        suggested = current
        reason = []
        if signal and signal['direction'] == 'increase':
            suggested = current * 1.03
            reason.append('market signal rising')
        elif signal and signal['direction'] == 'drop':
            suggested = current * 0.98
            reason.append('market signal softening')
        if product.stock is not None and product.stock <= 5 and not product.is_digital:
            suggested *= 1.02
            reason.append('low stock')
        if product.average_rating and product.average_rating < 3:
            suggested *= 0.97
            reason.append('rating pressure')
        if abs(suggested - current) >= 1:
            suggestions.append({
                'product': product,
                'current': round(current, 2),
                'suggested': round(suggested, 2),
                'reason': ', '.join(reason) or 'demand and margin balancing',
            })
    return suggestions[:20]


def stock_warnings():
    return Product.query.filter(
        Product.is_active == True,
        Product.is_digital == False,
        Product.stock <= 5
    ).order_by(Product.stock.asc()).limit(30).all()


def generate_product_description(name, category_id=None, condition='new', is_digital=False, image_url=''):
    api_key = os.environ.get('OPENAI_API_KEY') or Setting.get('openai_api_key', '')
    if api_key:
        try:
            category = Category.query.get(category_id) if category_id else None
            prompt = (
                "Write a complete ecommerce product description for SMARKAFRICA. "
                "Include key features, variant/compatibility checks, warranty/condition notes, buyer guidance, and what is included. "
                "Return concise HTML using paragraphs and bullet points only. "
                f"Product: {name}. Category: {category.name if category else 'General'}. "
                f"Condition: {condition}. Type: {'digital' if is_digital else 'physical'}. Image URL: {image_url or 'none'}."
            )
            response = requests.post(
                'https://api.openai.com/v1/responses',
                headers={'Authorization': f'Bearer {api_key}', 'Content-Type': 'application/json'},
                json={
                    'model': Setting.get('openai_description_model', 'gpt-4.1-mini'),
                    'input': prompt,
                    'max_output_tokens': 700,
                },
                timeout=20
            )
            if response.ok:
                data = response.json()
                text = data.get('output_text', '')
                if not text:
                    chunks = []
                    for item in data.get('output', []):
                        for content in item.get('content', []):
                            if content.get('text'):
                                chunks.append(content['text'])
                    text = '\n'.join(chunks)
                if text.strip():
                    return text.strip()
        except Exception:
            pass
    category = Category.query.get(category_id) if category_id else None
    label = product_market_label(name, category.name if category else '')
    reference = product_market_reference_match(name, category.name if category else '')
    category_name = category.name if category else 'General'
    lines = [
        f"<p><strong>{name}</strong> is a {condition.replace('_', ' ')} {category_name.lower()} product selected for buyers who need reliable value, clear specifications, and transparent pricing.</p>",
        "<ul>",
        f"<li><strong>Product type:</strong> {'Digital delivery item' if is_digital else 'Physical product'}.</li>",
        f"<li><strong>Category fit:</strong> {category_name} / {label}.</li>",
        "<li><strong>Key checks:</strong> confirm model/variant, warranty, included accessories, condition, compatibility, and country/import status before purchase.</li>",
        "<li><strong>Buyer guidance:</strong> compare price, stock availability, ratings, delivery option, and after-sale support before checkout.</li>",
    ]
    if reference:
        lines.append(f"<li><strong>Market watch:</strong> Kenya range currently tracked around KSh {reference['kenya_low']:,.0f} - KSh {reference['kenya_high']:,.0f}; verify live price before publishing.</li>")
    if image_url:
        lines.append("<li><strong>Image note:</strong> ensure the product image matches the exact model, color, and bundle being sold.</li>")
    lines.append("</ul>")
    return '\n'.join(lines)


def send_stock_warning_emails(force=False):
    warnings = stock_warnings()
    if not warnings:
        return 0
    last_sent = Setting.get('stock_warning_last_sent_at', '')
    today = utcnow().strftime('%Y-%m-%d')
    if last_sent == today and not force:
        return 0
    admins = User.query.filter_by(is_admin=True, is_active=True).all()
    rows = ''.join(f"<li>{p.name}: {p.stock} left</li>" for p in warnings)
    sent = 0
    for admin in admins:
        if send_email(admin.email, 'SMARKAFRICA low stock warning', f"<h3>Products about to run out of stock</h3><ul>{rows}</ul>"):
            sent += 1
    Setting.set('stock_warning_last_sent_at', today)
    return sent


def business_intelligence_answer(question):
    now = utcnow()
    week_start = now - timedelta(days=7)
    month_start = now - timedelta(days=30)
    week_orders = Order.query.filter(Order.created_at >= week_start).count()
    month_orders = Order.query.filter(Order.created_at >= month_start).count()
    week_sales = db.session.query(func.sum(Order.amount_paid)).filter(Order.created_at >= week_start).scalar() or 0
    month_sales = db.session.query(func.sum(Order.amount_paid)).filter(Order.created_at >= month_start).scalar() or 0
    low_rated = Product.query.join(Review).group_by(Product.id).having(func.avg(Review.rating) < 3.5).limit(5).all()
    low_stock = stock_warnings()
    market_rows = build_market_intelligence_payload('all')['rows']
    rising = [row['category'] for row in market_rows if row['direction'] == 'increase']
    falling = [row['category'] for row in market_rows if row['direction'] == 'drop']
    q = (question or '').lower()
    if 'drop' in q or 'sales' in q:
        answer = f"Sales this week are KSh {week_sales:,.2f} across {week_orders} orders. Last 30 days are KSh {month_sales:,.2f} across {month_orders} orders."
        if low_rated:
            answer += " Possible pressure: low ratings on " + ', '.join(p.name[:35] for p in low_rated) + "."
        if low_stock:
            answer += " Stock risk: " + ', '.join(p.name[:35] for p in low_stock[:5]) + "."
        if rising:
            answer += " Rising market costs may affect " + ', '.join(rising[:5]) + "."
        return answer
    if 'price' in q or 'increase' in q:
        return f"Price intelligence shows rising categories: {', '.join(rising) or 'none'}; falling categories: {', '.join(falling) or 'none'}. Kenya estimates include landed-cost pressure against worldwide manufacturer signals."
    return f"Business snapshot: KSh {week_sales:,.2f} sales this week, {week_orders} weekly orders, {len(low_stock)} low-stock warnings, and {len(rising)} categories with upward price signals."


def bi_period_snapshot(days, period_type):
    start = utcnow() - timedelta(days=days)
    orders = Order.query.filter(Order.created_at >= start).all()
    sales_total = sum(order.amount_paid or 0 for order in orders)
    orders_count = len(orders)
    slow_products = Product.query.filter(
        Product.is_active == True,
        Product.sales_count <= 0,
        Product.created_at <= utcnow() - timedelta(days=min(days, 7))
    ).order_by(Product.views_count.desc(), Product.created_at.asc()).limit(8).all()
    aov = sales_total / orders_count if orders_count else 0
    recommendation = (
        f"{period_type.title()} sales are KSh {sales_total:,.2f}. "
        f"Average order value is KSh {aov:,.2f}. "
        f"Refresh offers for {len(slow_products)} slow-moving product(s), then compare with live market signals before discounting."
    )
    return {
        'period_type': period_type,
        'sales_total': sales_total,
        'orders_count': orders_count,
        'average_order_value': aov,
        'slow_products': slow_products,
        'recommendation': recommendation,
    }


def record_business_checkins():
    snapshots = [bi_period_snapshot(1, 'daily'), bi_period_snapshot(7, 'weekly'), bi_period_snapshot(30, 'monthly')]
    for snapshot in snapshots:
        day_start = utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        exists = BusinessCheckIn.query.filter(
            BusinessCheckIn.period_type == snapshot['period_type'],
            BusinessCheckIn.created_at >= day_start,
            BusinessCheckIn.created_at < day_start + timedelta(days=1)
        ).first()
        if exists:
            exists.sales_total = snapshot['sales_total']
            exists.orders_count = snapshot['orders_count']
            exists.average_order_value = snapshot['average_order_value']
            exists.slow_products_count = len(snapshot['slow_products'])
            exists.recommendation = snapshot['recommendation']
        else:
            db.session.add(BusinessCheckIn(
                period_type=snapshot['period_type'],
                sales_total=snapshot['sales_total'],
                orders_count=snapshot['orders_count'],
                average_order_value=snapshot['average_order_value'],
                slow_products_count=len(snapshot['slow_products']),
                recommendation=snapshot['recommendation']
            ))
    db.session.commit()
    return snapshots


