PRICE_ALERT_BATCH = int_env('PRICE_ALERT_BATCH', 500)
PRICE_ALERT_SEARCH_BUDGET = int_env('PRICE_ALERT_SEARCH_BUDGET', 200)
CATEGORY_DIGEST_BATCH = int_env('CATEGORY_DIGEST_BATCH', 500)


def notify_price_alerts():
    """Queue a price-drop email for every alert whose target has been met.

    Paginated by id, with the product and user joined in up front. The previous
    shape loaded every active alert at once, lazy-loaded two relationships per
    alert, and then - for any alert with only a search term - ran the
    recommendation engine once per alert, even when a thousand people were
    watching the same phrase. That is not a slow job at a million users, it is a
    job that never returns.

    Search-term alerts now share a per-run cache keyed by the phrase, and the
    number of distinct phrases scored in one run is capped, so the worst case is
    bounded however large the alert table gets.
    """
    queued = 0
    search_cache = {}
    last_id = 0

    while True:
        alerts = (PriceAlert.query
                  .options(joinedload(PriceAlert.product), joinedload(PriceAlert.user))
                  .filter(PriceAlert.status == 'active', PriceAlert.id > last_id)
                  .order_by(PriceAlert.id.asc())
                  .limit(PRICE_ALERT_BATCH)
                  .all())
        if not alerts:
            break
        last_id = alerts[-1].id

        matched = []
        for alert in alerts:
            recipient = getattr(alert.user, 'email', None)
            if not recipient:
                continue
            if alert.product:
                candidates = [alert.product]
            else:
                phrase = (alert.search_query or '').strip().lower()
                if not phrase:
                    continue
                if phrase not in search_cache:
                    if len(search_cache) >= PRICE_ALERT_SEARCH_BUDGET:
                        continue
                    search_cache[phrase] = [
                        item['product']
                        for item in smart_product_recommendations(alert.search_query or '', 10)
                    ]
                candidates = search_cache[phrase]
            for product in candidates:
                if not product:
                    continue
                price = product.discounted_price or product.selling_price or 0
                if price <= alert.target_price:
                    matched.append((alert, recipient, product.name, price))
                    break

        for alert, recipient, name, price in matched:
            body = (f"<p>{name} is now KSh {price:,.2f}, which is within your alert "
                    f"target of KSh {alert.target_price:,.2f}.</p>")
            # Queued in the same transaction as the status change, so the alert is
            # never marked notified without the email being recorded, and never
            # emails twice because the first attempt half-committed.
            enqueue_email(recipient, 'SMARKAFRICA price alert', body, commit=False)
            alert.last_notified_at = utcnow()
            alert.status = 'notified'
            queued += 1
        db.session.commit()

    return queued


def send_category_follow_updates():
    """Queue one digest email per category follower. Returns how many were queued.

    One pass per category, not one per follower. The old shape cost four queries
    for every follower - the follow row, the user, the category, then the product
    list - so a hundred thousand followers meant four hundred thousand queries.
    A category's digest reads the same for everyone following it, so the body is
    built once and the audience is walked in id-ordered batches, which keeps
    memory flat and makes committing between batches safe.
    """
    category_ids = [
        row[0]
        for row in db.session.query(CategoryFollow.category_id)
        .filter(CategoryFollow.email_updates.is_(True))
        .distinct()
        .all()
    ]
    if not category_ids:
        return 0

    queued = 0
    for category_id in category_ids:
        category = db.session.get(Category, category_id)
        if not category:
            continue
        products = (Product.query
                    .filter_by(category_id=category_id, is_active=True)
                    .order_by(Product.created_at.desc())
                    .limit(5)
                    .all())
        news = (MarketNews.query
                .filter_by(category_id=category_id, is_cleared=False)
                .order_by(MarketNews.created_at.desc())
                .first())
        lines = ''.join(
            f"<li>{p.name} - KSh {(p.discounted_price or p.selling_price or 0):,.2f}</li>"
            for p in products
        )
        news_line = f"<p><strong>Price intelligence:</strong> {news.body}</p>" if news else ''
        subject = f'SMARKAFRICA {category.name} update'
        body = f"""
        <h3>{category.name} update</h3>
        {news_line}
        <p>New or relevant products:</p>
        <ul>{lines or '<li>No new products yet.</li>'}</ul>
        """

        last_follow_id = 0
        while True:
            rows = (db.session.query(CategoryFollow.id, User.email)
                    .join(User, User.id == CategoryFollow.user_id)
                    .filter(CategoryFollow.category_id == category_id,
                            CategoryFollow.email_updates.is_(True),
                            CategoryFollow.id > last_follow_id,
                            User.email.isnot(None),
                            User.email != '')
                    .order_by(CategoryFollow.id.asc())
                    .limit(CATEGORY_DIGEST_BATCH)
                    .all())
            if not rows:
                break
            last_follow_id = rows[-1][0]
            queued += enqueue_many('email', [email for _, email in rows],
                                   subject=subject, body=body)

    return queued


def commission_for_product(product):
    sale_price = product.selling_price or 0
    if sale_price < 200:
        return 10.0
    percent = product.commission_percent or 15.0
    return max(10.0, min(15.0, percent))


def user_can_sell(user):
    return bool(user and (user.is_admin or user.seller_status == 'verified' or user.is_verified_seller))


def seller_storefront(user):
    """The verified storefront a seller trades under, if any."""
    if not user or not getattr(user, 'is_authenticated', False):
        return None
    return BusinessStorefront.query.filter(
        BusinessStorefront.owner_id == user.id,
        BusinessStorefront.status.in_(['approved', 'active', 'verified'])
    ).order_by(BusinessStorefront.created_at.desc()).first()


def user_has_storefront(user):
    return seller_storefront(user) is not None


def apply_product_location(product, storefront=None, label=None, lat=None, lng=None):
    """Give a product a map pin so its card can show where the item is.

    An explicit pin from the listing form wins; otherwise the seller's verified
    storefront address supplies one. Resolving it here - not in a later batch
    job - is what makes the icon appear the moment the product is listed.
    """
    label = (label or '').strip()
    county = None

    if storefront is not None:
        if not label:
            label = (storefront.physical_address or storefront.landmark
                     or storefront.business_name or '').strip()
        if lat is None or lng is None:
            geocode_storefront(storefront)
            lat, lng = storefront.location_lat, storefront.location_lng
        county = storefront.location_county

    point = None
    if lat is not None and lng is not None:
        try:
            candidate = GeoPoint(float(lat), float(lng))
            point = candidate if candidate.is_valid() else None
        except (TypeError, ValueError):
            point = None

    if point is None and label:
        # No usable coordinates yet, so resolve the written address instead.
        try:
            point, resolved_county, _resolved_label = resolve_destination(
                country='Kenya', address=label)
            county = county or resolved_county
        except Exception:
            app.logger.exception('Product location geocode failed')

    display = (label or county or '').strip()
    # Never wipe a pin we already have: an edit that supplies nothing new
    # should leave the existing location alone.
    if display:
        product.location_label = display[:200]
    if county:
        product.location_county = county[:100]
    if point is not None:
        product.location_lat = point.lat
        product.location_lng = point.lng
    return product


DEFAULT_PUBLIC_BASE_URL = 'https://www.smark-africa.com'
DIDIT_WORKFLOW_ID_DEFAULT = '9dcb8c91-e2f1-41aa-a20b-59de798c80e8'
DIDIT_STATUS_MAP = {
    'Not Started': 'awaiting_user',
    'In Progress': 'in_progress',
    'Awaiting User': 'awaiting_user',
    'In Review': 'manual_review',
    'Approved': 'approved',
    'Declined': 'rejected',
    'Resubmitted': 'manual_review',
    'Abandoned': 'abandoned',
    'Expired': 'expired',
    'Kyc Expired': 'expired',
}


def didit_workflow_id():
    return (Setting.get('didit_workflow_id', DIDIT_WORKFLOW_ID_DEFAULT) or DIDIT_WORKFLOW_ID_DEFAULT).strip()


def didit_api_key():
    return (os.environ.get('DIDIT_API_KEY') or '').strip()


def didit_webhook_secret():
    return (os.environ.get('DIDIT_WEBHOOK_SECRET') or '').strip()


def selected_kyc_provider():
    configured = (os.environ.get('KYC_PROVIDER') or Setting.get('kyc_provider', 'didit') or 'didit').strip().lower()
    return configured if configured in {'inbuilt', 'didit', 'external'} else 'didit'


def didit_enabled():
    return selected_kyc_provider() == 'didit'


def didit_config_status():
    missing = []
    if not didit_workflow_id():
        missing.append('DIDIT workflow ID')
    if not didit_api_key():
        missing.append('DIDIT_API_KEY')
    if not didit_webhook_secret():
        missing.append('DIDIT_WEBHOOK_SECRET')
    return {
        'ready': not missing,
        'missing': missing,
        'workflow_id': didit_workflow_id(),
        'webhook_url': f"{public_base_url()}/api/kyc/didit/webhook" if public_base_url() else '',
    }


def didit_document_fingerprint(session_id):
    return hashlib.sha256(f'didit:{session_id}'.encode('utf-8')).hexdigest()


def didit_callback_url():
    return f"{public_base_url()}{url_for('seller_apply')}"


def didit_contact_phone(phone):
    normalized = normalize_mpesa_phone(phone)
    return f'+{normalized}' if normalized else ''


def wants_json_response():
    return (
        request.is_json or
        request.headers.get('X-Requested-With') == 'XMLHttpRequest' or
        request.accept_mimetypes.best == 'application/json'
    )


def didit_canonical_payload(value):
    if isinstance(value, dict):
        return {key: didit_canonical_payload(value[key]) for key in sorted(value)}
    if isinstance(value, list):
        return [didit_canonical_payload(item) for item in value]
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def didit_signature_is_valid(payload):
    secret = didit_webhook_secret()
    signature = request.headers.get('X-Signature-V2', '')
    timestamp = request.headers.get('X-Timestamp', '')
    if not secret or not signature or not timestamp:
        return False
    try:
        event_time = datetime.fromtimestamp(int(timestamp), tz=timezone.utc)
    except (TypeError, ValueError, OSError):
        return False
    if abs((utcnow().replace(tzinfo=timezone.utc) - event_time).total_seconds()) > 300:
        return False
    canonical = json.dumps(didit_canonical_payload(payload), ensure_ascii=False, separators=(',', ':'))
    expected = hmac.new(secret.encode('utf-8'), canonical.encode('utf-8'), hashlib.sha256).hexdigest()
    return hmac.compare_digest(signature, expected)


def didit_decision_scores(payload):
    decision = payload.get('decision') or payload.get('verification') or {}

    def best_score(keys):
        scores = []
        for key in keys:
            value = decision.get(key) or payload.get(key) or []
            if isinstance(value, dict):
                value = [value]
            for item in value:
                if isinstance(item, dict):
                    score = item.get('score') or item.get('confidence') or item.get('value')
                    try:
                        scores.append(float(score))
                    except (TypeError, ValueError):
                        pass
        return max(scores) if scores else 0.0

    return best_score(['face_matches', 'face_match']), best_score(['liveness_checks', 'liveness'])


def upsert_didit_verification(user, session_id, status='awaiting_user', notes='Hosted seller verification session created.'):
    fingerprint = didit_document_fingerprint(session_id)
    kyc = KYCIdentityVerification.query.filter_by(provider='didit', provider_reference=session_id).first()
    if not kyc:
        kyc = KYCIdentityVerification(
            user_id=user.id,
            provider='didit',
            provider_reference=session_id,
            document_type='didit_hosted',
            document_fingerprint=fingerprint,
        )
        db.session.add(kyc)
    kyc.user_id = user.id
    kyc.status = status
    kyc.notes = notes
    kyc.captcha_passed = True

    verification = SellerVerification.query.filter_by(document_fingerprint=fingerprint).first()
    if not verification:
        verification = SellerVerification(
            user_id=user.id,
            document_type='didit_hosted',
            document_fingerprint=fingerprint,
        )
        db.session.add(verification)
    verification.status = status
    verification.automated_score = 0
    verification.notes = notes
    return kyc, verification


def create_didit_session_for_user(user):
    api_key = didit_api_key()
    if not api_key:
        raise RuntimeError('DIDIT_API_KEY is not configured on the server.')
    payload = {
        'workflow_id': didit_workflow_id(),
        'vendor_data': str(user.id),
        'callback': didit_callback_url(),
        'callback_method': 'both',
        'metadata': {
            'user_id': user.id,
            'source': 'seller_verification',
        },
        'language': 'en',
    }
    contact_details = {}
    if user.email:
        contact_details['email'] = user.email
        contact_details['send_notification_emails'] = True
        contact_details['email_lang'] = 'en'
    phone = didit_contact_phone(user.phone)
    if phone:
        contact_details['phone'] = phone
    if contact_details:
        payload['contact_details'] = contact_details

    response = requests.post(
        'https://verification.didit.me/v3/session/',
        headers={'x-api-key': api_key, 'Content-Type': 'application/json', 'Accept': 'application/json'},
        json=payload,
        timeout=(5, 15),
    )
    response.raise_for_status()
    data = response.json()
    session_id = data.get('session_id') or data.get('id')
    verification_url = data.get('url') or data.get('verification_url')
    if not session_id or not verification_url:
        raise RuntimeError('Didit did not return a verification session URL.')
    upsert_didit_verification(user, session_id)
    user.verification_status = 'awaiting_user'
    user.seller_status = 'pending'
    user.is_verified_seller = False
    db.session.commit()
    return {'url': verification_url, 'session_id': session_id}


def apply_didit_status(payload):
    session_id = str(payload.get('session_id') or payload.get('id') or payload.get('reference_id') or '').strip()
    vendor_data = str(payload.get('vendor_data') or '').strip()
    didit_status = payload.get('status') or payload.get('verification_status') or ''
    local_status = DIDIT_STATUS_MAP.get(didit_status, 'manual_review')
    user = User.query.get(int(vendor_data)) if vendor_data.isdigit() else None
    kyc = KYCIdentityVerification.query.filter_by(provider='didit', provider_reference=session_id).first() if session_id else None
    if not user and kyc:
        user = kyc.user
    if not user or not session_id:
        logger.warning('Didit webhook could not match user/session: %s', payload)
        return False

    notes = f'Verification status: {didit_status or "Unknown"}.'
    face_score, liveness_score = didit_decision_scores(payload)
    kyc, verification = upsert_didit_verification(user, session_id, local_status, notes)
    kyc.face_match_score = face_score
    kyc.liveness_score = liveness_score
    kyc.reviewed_at = utcnow() if local_status in {'approved', 'rejected', 'expired'} else None
    verification.automated_score = max(face_score, liveness_score)
    verification.reviewed_at = kyc.reviewed_at

    user.verification_status = local_status
    user.verification_notes = notes
    if local_status == 'approved':
        user.seller_status = 'verified'
        user.is_verified_seller = True
        user.verified_seller_at = utcnow()
    elif local_status == 'rejected':
        user.seller_status = 'rejected'
        user.is_verified_seller = False
    else:
        user.seller_status = 'pending'
        user.is_verified_seller = False
    db.session.commit()
    return True


