def auto_verify_seller_payload(legal_name, country, phone, document_filename, selfie_filename, bank_card_last4):
    score = 0.0
    notes = []
    if legal_name and len(legal_name.split()) >= 2:
        score += 25
    else:
        notes.append('Legal name should include first and last name.')
    if country:
        score += 15
    if phone and len(normalize_mpesa_phone(phone)) >= 10:
        score += 20
    else:
        notes.append('Phone number is incomplete.')
    if document_filename and document_filename.lower().rsplit('.', 1)[-1] in {'jpg', 'jpeg', 'png', 'pdf'}:
        score += 20
    else:
        notes.append('Upload a readable ID or passport.')
    if selfie_filename and selfie_filename.lower().rsplit('.', 1)[-1] in {'jpg', 'jpeg', 'png'}:
        score += 10
    else:
        notes.append('Upload a clear face photo.')
    if bank_card_last4 and len(bank_card_last4) == 4 and bank_card_last4.isdigit():
        score += 10
    else:
        notes.append('Attach a valid bank card last four digits.')
    if legal_name and country and phone and document_filename and selfie_filename:
        fingerprint = hashlib.sha256('|'.join([
            legal_name.strip().lower(),
            country.strip().lower(),
            normalize_mpesa_phone(phone),
            document_filename.strip().lower(),
            selfie_filename.strip().lower(),
        ]).encode('utf-8')).hexdigest()[:12]
        notes.append(f'KYC fingerprint: {fingerprint}.')
    status = 'approved' if score >= 80 else 'manual_review'
    return status, score, ' '.join(notes) or 'Automated checks passed.'


def verify_kyc_faces(document_path, selfie_path):
    """Compare face in document photo with selfie using OpenCV histogram correlation."""
    try:
        import cv2
        import numpy as np

        face_cascade = cv2.CascadeClassifier(
            cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
        )

        def extract_face_region(img_path):
            img = cv2.imread(img_path)
            if img is None:
                return None
            gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
            faces = face_cascade.detectMultiScale(gray, 1.1, 5, minSize=(60, 60))
            if len(faces) == 0:
                faces = face_cascade.detectMultiScale(gray, 1.05, 3, minSize=(30, 30))
            if len(faces) == 0:
                return None
            x, y, w, h = max(faces, key=lambda f: f[2] * f[3])
            face_roi = img[y:y+h, x:x+w]
            face_roi = cv2.resize(face_roi, (128, 128))
            return face_roi

        doc_face = extract_face_region(document_path)
        selfie_face = extract_face_region(selfie_path)

        if doc_face is None or selfie_face is None:
            missing = []
            if doc_face is None:
                missing.append('document')
            if selfie_face is None:
                missing.append('selfie')
            return {
                'success': False,
                'face_match_score': 0,
                'verified': False,
                'error': f'No face detected in: {", ".join(missing)}',
            }

        doc_hist = cv2.calcHist([doc_face], [0, 1, 2], None, [32, 32, 32], [0, 256, 0, 256, 0, 256])
        cv2.normalize(doc_hist, doc_hist)
        selfie_hist = cv2.calcHist([selfie_face], [0, 1, 2], None, [32, 32, 32], [0, 256, 0, 256, 0, 256])
        cv2.normalize(selfie_hist, selfie_hist)

        correlation = cv2.compareHist(doc_hist, selfie_hist, cv2.HISTCMP_CORREL)
        face_match_score = round(max(0, correlation) * 100, 2)
        verified = face_match_score >= 45

        return {
            'success': True,
            'face_match_score': face_match_score,
            'verified': verified,
            'distance': round(1 - correlation, 4),
            'threshold': 0.45,
            'model': 'opencv-histogram',
        }
    except Exception as e:
        logger.error(f'Face verification failed: {e}')
        return {
            'success': False,
            'face_match_score': 0,
            'verified': False,
            'error': str(e),
        }


def verify_document_quality(document_path):
    """Check document image quality and detect if it contains a face."""
    try:
        import cv2
        from PIL import Image

        img = Image.open(document_path)
        width, height = img.size

        quality_score = 0
        issues = []

        if width >= 640 and height >= 480:
            quality_score += 30
        elif width >= 320 and height >= 240:
            quality_score += 15
            issues.append('Low resolution document')
        else:
            issues.append('Very low resolution - document may be unreadable')

        aspect = max(width, height) / max(min(width, height), 1)
        if 1.2 <= aspect <= 2.0:
            quality_score += 20
        else:
            issues.append('Unusual aspect ratio for an ID document')

        try:
            cv_img = cv2.imread(document_path)
            gray = cv2.cvtColor(cv_img, cv2.COLOR_BGR2GRAY)
            face_cascade = cv2.CascadeClassifier(
                cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'
            )
            faces = face_cascade.detectMultiScale(gray, 1.1, 5, minSize=(30, 30))
            if len(faces) > 0:
                quality_score += 50
            else:
                quality_score += 10
                issues.append('No clear face detected in document')
        except Exception:
            quality_score += 10
            issues.append('Could not analyze faces in document')

        return {
            'quality_score': min(quality_score, 100),
            'issues': issues,
            'resolution': f'{width}x{height}',
        }
    except Exception as e:
        logger.error(f'Document quality check failed: {e}')
        return {
            'quality_score': 0,
            'issues': [str(e)],
            'resolution': 'unknown',
        }


def _get_cached_settings():
    """Get settings with caching to avoid DB hit on every request."""
    cache_key = 'global_settings_dict'
    if cache:
        cached = cache.get(cache_key)
        if cached is not None:
            return cached
    from models import Setting
    s = {}
    for row in Setting.query.all():
        s[row.key] = row.value
    if cache:
        cache.set(cache_key, s, timeout=60)
    return s


def _get_cached_platform_ads():
    """Get platform ads with caching.

    Only the ids are cached. Caching the ORM objects themselves meant that once
    the loading session closed they came back detached, and base.html - which
    every page extends - lazy-loads ad.product, so the whole site raised
    DetachedInstanceError until the entry expired. Re-reading by id is an
    indexed lookup, and the expensive part (the scan and the launched-together
    grouping) is still cached.
    """
    cache_key = 'platform_ads_ids'
    cached_ids = cache.get(cache_key) if cache else None
    if cached_ids is not None:
        return _load_platform_ads(cached_ids)
    try:
        active_ads = AdCampaign.query.filter(
            AdCampaign.status == 'active',
            AdCampaign.placement.in_(['smarkafrica', 'platform'])
        ).order_by(AdCampaign.created_at.desc()).limit(8).all()
        if active_ads:
            platform_ad = active_ads[0]
            launched_together = [
                ad for ad in active_ads
                if active_ads[0].created_at and ad.created_at and
                abs((active_ads[0].created_at - ad.created_at).total_seconds()) <= 5
            ]
            platform_ads = launched_together if len(launched_together) > 1 else [platform_ad]
            ids = [ad.id for ad in platform_ads]
        else:
            ids = []
    except Exception:
        ids = []
    if cache:
        cache.set(cache_key, ids, timeout=60)
    return _load_platform_ads(ids)


def _load_platform_ads(ids):
    """Re-read cached ad ids as session-bound objects, product eagerly loaded."""
    if not ids:
        return (None, [])
    try:
        ads = AdCampaign.query.options(joinedload(AdCampaign.product)).filter(
            AdCampaign.id.in_(ids)).all()
    except Exception:
        return (None, [])
    order = {ad_id: position for position, ad_id in enumerate(ids)}
    ads.sort(key=lambda ad: order.get(ad.id, len(order)))
    return (ads[0], ads) if ads else (None, [])


def _get_cached_hot_sale():
    """Get hot sale product with caching.

    Caches the id rather than the instance, for the same reason as
    _get_cached_platform_ads: a cached ORM object outlives its session.
    """
    cache_key = 'hot_sale_pop_product_id'
    cached_id = cache.get(cache_key) if cache else None
    if cached_id is not None:
        return None if cached_id == 'NONE' else db.session.get(Product, cached_id)
    try:
        hot_sale_pop = Product.query.filter_by(is_active=True, is_hot_sale=True).order_by(
            Product.hot_sale_started_at.desc(),
            Product.updated_at.desc()
        ).first()
    except Exception:
        hot_sale_pop = None
    if cache:
        cache.set(cache_key, hot_sale_pop.id if hot_sale_pop else 'NONE', timeout=60)
    return hot_sale_pop


def unread_notification_count(user=None):
    """Unread notification total for the navbar badge.

    Counted rather than loaded: the badge only needs the number, and the
    ix_customer_notifications_user_read_created index covers this exactly.
    """
    user = user or current_user
    if not user or not getattr(user, 'is_authenticated', False):
        return 0
    try:
        return CustomerNotification.query.filter_by(user_id=user.id, is_read=False).count()
    except Exception:
        # A badge is never worth failing a page render over.
        return 0


def seller_nav_state(user=None):
    """What the seller/storefront nav links should say for this user.

    Verified sellers should not keep seeing a "Become a Seller" prompt, so the
    label and target both follow how far through the funnel the user actually is.
    """
    user = user or current_user
    state = {'can_sell': False, 'has_storefront': False, 'storefront_pending': False}
    if not user or not getattr(user, 'is_authenticated', False):
        return state
    try:
        state['can_sell'] = user_can_sell(user)
        state['has_storefront'] = user_has_storefront(user)
        if state['can_sell'] and not state['has_storefront']:
            state['storefront_pending'] = BusinessStorefront.query.filter_by(
                owner_id=user.id).first() is not None
    except Exception:
        return state
    return state


# Paths that are not search results: authenticated views, payment callbacks and
# actions. One list, read by both robots.txt and the per-page noindex tag, because
# the two must not be allowed to drift - a path crawlers are asked to skip but
# whose page still invites indexing is the ambiguity that produces "crawled,
# currently not indexed" rather than a clean exclusion.
NON_PUBLIC_PREFIXES = (
    '/admin/', '/seller/', '/api/', '/pos/',
    '/cart', '/checkout', '/orders', '/order/', '/notifications',
    '/login', '/logout', '/register', '/healthz', '/test-email',
    '/mpesa/', '/flutterwave/', '/track/', '/coins/', '/affiliate/',
    '/bnpl/', '/shopping-card', '/my-rewards-card', '/support/',
    '/feedback', '/raffle/', '/compare', '/smart-shopping',
    '/shop/image-search', '/storefront/apply', '/services/create',
    # A billing document addressed by a bearer token, and one client's linking
    # thread. Neither is secret-by-obscurity alone, but neither belongs in an
    # index either: a crawler that reaches one publishes somebody's invoice.
    '/invoice/', '/services/requests/',
)


def page_is_noindex():
    """Whether this page should ask search engines not to index it.

    robots.txt asks crawlers not to fetch these paths, which is a request about
    crawling rather than about indexing: a path that is linked from elsewhere can
    still be indexed from the link alone while robots.txt keeps the crawler from
    seeing the page well enough to describe it. The meta tag is what actually
    settles it, so both are worth having.
    """
    if not has_request_context():
        return False
    path = request.path or '/'
    return any(path == prefix.rstrip('/') or path.startswith(prefix)
               for prefix in NON_PUBLIC_PREFIXES)


def canonical_url():
    """The one URL this page should be indexed under, or '' outside a request.

    Search engines treat every distinct URL that returns the same content as a
    separate page competing with itself, and there are more of those than anyone
    writes down: the apex and www forms of the host, http and https, and every
    variant carrying a tracking parameter a link was shared with. Declaring one
    preferred URL per page is what collapses them, and its absence is precisely
    what "duplicate without user-selected canonical" reports.

    Two deliberate choices. The host comes from APP_BASE_URL or PUBLIC_URL when
    either is set - existing variables, not new ones - so the operator picks the
    preferred form once; without them it falls back to the host the request
    arrived on, which is honest but leaves apex and www each canonicalising to
    themselves. And the query string is dropped except for ``page``, because
    pagination genuinely is a different page while a utm_ tag is the same one.
    """
    if not has_request_context():
        return ''
    try:
        configured = (os.environ.get('APP_BASE_URL') or os.environ.get('PUBLIC_URL') or '').strip()
        if configured:
            base = configured.rstrip('/')
            if '://' not in base:
                base = f'https://{base}'
        else:
            # Local development keeps whatever scheme it is actually using; a real
            # host is https, since that is what the certificate and every existing
            # inbound link already assume.
            host = request.host
            is_local = host.split(':')[0] in ('localhost', '127.0.0.1', '0.0.0.0')
            base = f"{request.scheme if is_local else 'https'}://{host}"
        url = f'{base}{request.path}'
        page = request.args.get('page', type=int)
        if page and page > 1:
            url = f'{url}?page={page}'
        return url
    except Exception:
        return ''


@app.context_processor
def inject_globals():
    """Inject settings and utility vars into all templates"""
    try:
        s = _get_cached_settings()
        is_admin_page = (request.endpoint or '').startswith('admin')
        platform_ad, platform_ads = (None, []) if is_admin_page else _get_cached_platform_ads()
        hot_sale_pop = None if is_admin_page else _get_cached_hot_sale()
        auth_user = getattr(g, 'auth_user', {
            'is_authenticated': False,
            'is_admin': False,
            'admin_level': '',
            'username': '',
            'service_duty_on': False,
        })
        return dict(
            settings=s,
            auth_user=auth_user,
            now=datetime.utcnow(),
            platform_ad=platform_ad,
            platform_ads=platform_ads,
            hot_sale_pop=hot_sale_pop,
            seller_signup_enabled=s.get('seller_signup_enabled', '0') == '1',
            unread_notifications=unread_notification_count(),
            seller_nav=seller_nav_state(),
            canonical=canonical_url(),
            noindex=page_is_noindex(),
            country_phone_codes=COUNTRY_PHONE_CODES
        )
    except Exception:
        return dict(settings={}, auth_user={'is_authenticated': False, 'is_admin': False, 'admin_level': '', 'username': '', 'service_duty_on': False}, now=datetime.utcnow(), platform_ad=None, platform_ads=[],
                    hot_sale_pop=None, seller_signup_enabled=False, unread_notifications=0,
                    seller_nav={'can_sell': False, 'has_storefront': False, 'storefront_pending': False},
                    canonical=canonical_url(),
                    noindex=page_is_noindex(),
                    country_phone_codes=COUNTRY_PHONE_CODES)
