@app.route('/delivery/quote/<int:product_id>')
def delivery_quote_api(product_id):
    """Re-price one product's delivery for wherever the shopper actually is.

    Accepts precise coordinates from the browser, or a county/city when that is
    all we have. Deliberately returns the fee and nothing else: the distance,
    weight, zone and flat-fee arithmetic behind it is not shopper-facing.
    """
    product = Product.query.get_or_404(product_id)
    county = (request.args.get('county') or '').strip()
    city = (request.args.get('city') or '').strip()
    country = (request.args.get('country') or ('Kenya' if county or city else '')).strip()

    lat = request.args.get('lat', type=float)
    lng = request.args.get('lng', type=float)
    point = GeoPoint(lat, lng) if (lat is not None and lng is not None) else None
    if point is not None and not point.is_valid():
        point = None

    if point is not None:
        # Turn the fix into a place name so the session, and later checkout, has
        # something to work with rather than bare coordinates.
        located = cached_reverse(cache, point)
        resolved_county = (getattr(located, 'county', '') or '').strip()
        resolved_country = (getattr(located, 'country', '') or '').strip() or 'Kenya'
        session['delivery_location'] = {
            'country': resolved_country, 'county': resolved_county,
            'city': (getattr(located, 'label', '') or '').strip(), 'address': '',
        }
        session.modified = True
        quote = quote_product_delivery(
            product, user=current_user, country=resolved_country,
            county=resolved_county, city='', address='', lat=point.lat, lng=point.lng)
    elif county or city or country:
        session['delivery_location'] = {
            'country': country or 'Kenya', 'county': county, 'city': city, 'address': '',
        }
        session.modified = True
        quote = quote_product_delivery(
            product, user=current_user,
            country=country or 'Kenya', county=county, city=city, address='')
    else:
        quote = quote_product_delivery(product, user=current_user)

    return jsonify({
        'success': True,
        'total_amount': quote['total_amount'],
        'display': 'Free delivery' if quote['total_amount'] <= 0 else f"KSh {quote['total_amount']:,.2f}",
        'free_delivery': bool(quote.get('free_delivery')),
    })


@app.route('/product/<slug>')
def product_page(slug):
    product = Product.query.filter_by(slug=slug, is_active=True).first_or_404()
    record_product_view(product)

    # Paginated and eager-loaded. Reviews only ever accumulate, and the template
    # prints review.author.username, so the old unbounded load cost one query per
    # review on top of the load itself - a listing with 500 reviews ran 501
    # queries to render a page anyone can request.
    reviews_page = request.args.get('reviews_page', 1, type=int)
    review_pagination = (Review.query
                         .options(joinedload(Review.author))
                         .filter_by(product_id=product.id, is_visible=True)
                         .order_by(Review.created_at.desc())
                         .paginate(page=max(1, reviews_page), per_page=REVIEWS_PER_PAGE,
                                   error_out=False))
    reviews = review_pagination.items
    has_reviewed = False
    is_following_category = False
    is_following_storefront = False
    storefront = BusinessStorefront.query.filter_by(
        owner_id=product.seller_id, status='approved').first() if product.seller_id else None
    if current_user.is_authenticated:
        has_reviewed = Review.query.filter_by(user_id=current_user.id, product_id=product.id).first() is not None
        if product.category_id:
            is_following_category = CategoryFollow.query.filter_by(user_id=current_user.id, category_id=product.category_id).first() is not None
        if storefront:
            is_following_storefront = StorefrontFollow.query.filter_by(
                user_id=current_user.id, storefront_id=storefront.id).first() is not None
    related = Product.query.filter(
        Product.category_id == product.category_id,
        Product.id != product.id,
        Product.is_active == True
    ).limit(4).all()
    gallery_images = []
    if product.image_url:
        gallery_images.append(product.image_url)
    if product.additional_images:
        try:
            gallery_images.extend(json.loads(product.additional_images))
        except Exception:
            pass

    bnpl_policy = BNPLProductPolicy.query.filter_by(product_id=product.id, is_enabled=True).first()

    # The seller's no-delivery list stays invisible unless it actually affects
    # this shopper, so nobody is shown restrictions that do not apply to them.
    buyer_country = getattr(current_user, 'country', None) if current_user.is_authenticated else None
    delivery_blocked = product_delivery_blocked(product, buyer_country)

    # Delivery is priced from where this item actually sits to where the shopper
    # is, so the figure on the page is the one they will be charged.
    delivery_location = buyer_delivery_location(current_user)
    delivery_quote = None
    if not delivery_blocked:
        delivery_quote = quote_product_delivery(product, user=current_user)

    return render_template('product.html',
                           product=product,
                           reviews=reviews,
                           review_pagination=review_pagination,
                           related=related,
                           has_reviewed=has_reviewed,
                           is_following_category=is_following_category,
                           is_following_storefront=is_following_storefront,
                           storefront=storefront,
                           delivery_blocked=delivery_blocked,
                           buyer_country=buyer_country,
                           delivery_quote=delivery_quote,
                           delivery_location=delivery_location,
                           gallery_images=gallery_images,
                           media_kind=product_media_kind(product),
                           # A cloud-stored file has no preview to offer, so the
                           # page must not render a control that would 404.
                           preview_available=bool(product.is_digital and product.file_path
                                                  and not is_cloudinary_reference(product.file_path)),
                           is_music_product=is_music_category(product.category),
                           bnpl_policy=bnpl_policy)


@app.route('/api/product/<int:pid>/preview')
def preview_digital(pid):
    """Serve a limited preview of digital products."""
    product = Product.query.get_or_404(pid)
    if not product.is_digital or not product.file_path:
        abort(404)

    # No preview for a cloud-stored file. The preview works by reading the first
    # slice of the bytes, and the only ways to get those bytes here would be to
    # fetch the whole asset into the request path or to hand the buyer a signed URL
    # - and a signed URL to a paid file is the entire file, not a preview of it.
    # A missing preview costs a listing some appeal; the alternative gives it away.
    if is_cloudinary_reference(product.file_path):
        abort(404)

    filepath = os.path.join(app.config['UPLOAD_FOLDER'], 'digital',
                            os.path.basename(product.file_path))
    if not os.path.exists(filepath):
        abort(404)

    media_kind = product_media_kind(product)
    if media_kind in ['audio', 'video']:
        with open(filepath, 'rb') as f:
            preview_data = f.read(512 * 1024)
        response = make_response(preview_data)
        response.headers['Content-Type'] = mimetypes.guess_type(filepath)[0] or 'application/octet-stream'
        response.headers['Content-Disposition'] = f'inline; filename=preview_{secure_filename(product.slug)}.{product_file_extension(product)}'
        response.headers['X-Preview-Seconds'] = '5'
        return response

    with open(filepath, 'rb') as f:
        preview_data = f.read(51200)

    response = make_response(preview_data)
    response.headers['Content-Type'] = mimetypes.guess_type(filepath)[0] or 'application/octet-stream'
    response.headers['Content-Disposition'] = f'inline; filename=preview_{secure_filename(product.slug)}.{product_file_extension(product)}'
    return response


