@app.route('/cart')
@login_required
def cart():
    # joinedload because the loop below reads item.product on every line, and the
    # template reads more of it again - one query for the cart instead of one per
    # line. Carts are small, but this is the page shoppers refresh most.
    items = (Cart.query.options(joinedload(Cart.product))
             .filter_by(user_id=current_user.id).all())
    total = 0
    for item in items:
        if item.product:
            item.effective_price = item.product.discounted_price or item.product.selling_price
            item.subtotal = item.effective_price * item.quantity
            total += item.subtotal
    return render_template('cart.html', cart_items=items, total=total)


@app.route('/cart/add/<int:product_id>', methods=['POST'])
@app.route('/api/cart/add', methods=['POST'])
@login_required
@limiter.limit("30 per minute")
def add_to_cart(product_id=None):
    wants_json = request.is_json or request.path.startswith('/api/')
    data = request.get_json(silent=True) or request.form
    product_id = product_id or data.get('product_id') or request.args.get('product_id', type=int)

    # Validate quantity
    try:
        quantity = int(data.get('quantity', 1))
        if quantity < 1 or quantity > 99:
            raise ValueError('Invalid quantity')
    except (ValueError, TypeError):
        if not wants_json:
            flash('Invalid quantity.', 'danger')
            return redirect(url_for('shop'))
        return jsonify({'success': False, 'error': 'Invalid quantity'}), 400

    product = Product.query.get(product_id)
    if not product or not product.is_active:
        if not wants_json:
            flash('Product not found.', 'danger')
            return redirect(url_for('shop'))
        return jsonify({'success': False, 'error': 'Product not found'})

    if not product.is_digital and product.stock < quantity:
        if not wants_json:
            flash('Insufficient stock.', 'danger')
            return redirect(url_for('product_page', slug=product.slug))
        return jsonify({'success': False, 'error': 'Insufficient stock'})

    existing = Cart.query.filter_by(user_id=current_user.id, product_id=product_id).first()
    if existing:
        existing.quantity += quantity
    else:
        cart_item = Cart(user_id=current_user.id, product_id=product_id, quantity=quantity)
        db.session.add(cart_item)

    db.session.commit()
    if not wants_json:
        flash(f'{product.name} added to cart.', 'success')
        return redirect(url_for('cart'))
    return jsonify({'success': True, 'cart_count': Cart.query.filter_by(user_id=current_user.id).count()})


@app.route('/cart/update/<int:item_id>', methods=['POST'])
@app.route('/api/cart/update', methods=['POST'])
@login_required
def update_cart(item_id=None):
    wants_json = request.is_json or request.path.startswith('/api/')
    data = request.get_json(silent=True) or request.form
    item_id = item_id or data.get('item_id') or request.args.get('item_id', type=int)
    quantity = int(data.get('quantity', 1))

    item = Cart.query.filter_by(id=item_id, user_id=current_user.id).first()
    if item:
        item.quantity = max(1, min(quantity, 99))
        db.session.commit()

    if not wants_json:
        flash('Cart updated.', 'success')
        return redirect(url_for('cart'))
    return jsonify({'success': True})


@app.route('/cart/clear', methods=['POST'])
@login_required
def clear_cart():
    """Empty the cart in one go - the way out after a payment that did not complete."""
    removed = Cart.query.filter_by(user_id=current_user.id).delete(synchronize_session=False)
    db.session.commit()
    flash('Cart cleared.' if removed else 'Your cart was already empty.', 'success')
    return redirect(url_for('cart'))


def cart_totals_payload(user_id):
    """Recomputed cart figures, so a removal can repaint the page without a reload."""
    items = Cart.query.filter_by(user_id=user_id).all()
    subtotal = sum((item.product.discounted_price or 0) * item.quantity
                   for item in items if item.product)
    return {
        'cart_count': len(items),
        'cart_quantity': sum(item.quantity for item in items),
        'subtotal': round(subtotal, 2),
        'subtotal_display': f'KSh {subtotal:,.2f}',
        'is_empty': not items,
    }


@app.route('/cart/remove/<int:item_id>', methods=['POST'])
@app.route('/api/cart/remove/<int:item_id>', methods=['POST'])
@login_required
def remove_cart_item(item_id):
    # The cart page removes items over fetch() and repaints in place, so the
    # buyer never lands on a separate "item removed" screen. The redirect below
    # is only the no-JavaScript fallback.
    wants_json = (request.is_json
                  or request.path.startswith('/api/')
                  or request.headers.get('X-Requested-With') == 'XMLHttpRequest')
    item = Cart.query.filter_by(id=item_id, user_id=current_user.id).first()
    if item:
        db.session.delete(item)
        db.session.commit()
    if not wants_json:
        return redirect(url_for('cart'))
    payload = {'success': True, 'removed': bool(item)}
    payload.update(cart_totals_payload(current_user.id))
    return jsonify(payload)


# ========================================================================
# CHECKOUT & PAYMENT ROUTES
# ========================================================================

# A checkout only becomes an order once the money lands. Until then the buyer keeps
# their cart, stock stays on the shelf, and nothing appears under My Orders.
# 'paid' is here only for rows written by the older card path.
ORDER_PAID_STATUSES = ('completed', 'paid')


def order_is_paid(order):
    return bool(order) and (order.payment_status or '') in ORDER_PAID_STATUSES


def forget_order_checkout_ids(order):
    """Clear the M-Pesa checkout id for an order we no longer wait on.

    Also clears any legacy settings-row bookmarks left by versions that stored
    the mapping there, so an upgraded deployment stops carrying them.
    """
    if not order:
        return
    legacy_keys = [f'mpesa_order_checkout_{order.id}']
    legacy_checkout_id = Setting.get(f'mpesa_order_checkout_{order.id}', '')
    if legacy_checkout_id:
        legacy_keys.append(f'mpesa_checkout_order_{legacy_checkout_id}')
    Setting.query.filter(Setting.key.in_(legacy_keys)).delete(synchronize_session=False)
    for key in legacy_keys:
        Setting.invalidate_cache(key)
    order.mpesa_checkout_request_id = None


def remember_order_checkout_id(order, checkout_request_id):
    """Record the in-flight Daraja checkout id against the order.

    A column rather than a separate row because the callback has to be able to
    find this order, and Safaricom's callback can arrive before a write in its own
    transaction would have landed. Writing it on the order means it commits with
    the order state it belongs to, and the callback lookup is one indexed query.
    """
    if not order or not checkout_request_id:
        return
    order.mpesa_checkout_request_id = str(checkout_request_id)[:120]


def order_checkout_id(order):
    """The checkout id for an order, falling back to the legacy settings row.

    The fallback covers orders that were already in flight when the column was
    introduced; it costs one cached read and can be removed once no pending order
    predates the upgrade.
    """
    if not order:
        return ''
    if order.mpesa_checkout_request_id:
        return order.mpesa_checkout_request_id
    return Setting.get(f'mpesa_order_checkout_{order.id}', '')


def order_for_checkout_id(checkout_request_id):
    """Resolve a Daraja checkout id back to its order."""
    if not checkout_request_id:
        return None
    order = Order.query.filter_by(
        mpesa_checkout_request_id=str(checkout_request_id)).first()
    if order:
        return order
    legacy_order_id = Setting.get(f'mpesa_checkout_order_{checkout_request_id}', '')
    if legacy_order_id:
        try:
            return Order.query.get(int(legacy_order_id))
        except (TypeError, ValueError):
            return None
    return None


def abandon_unpaid_order(order, reason=''):
    """
    Payment failed, so this checkout stops counting as an order: it drops out of My
    Orders and the buyer returns to a cart that still holds everything they picked.
    Stock and seller earnings were never taken, so there is nothing to hand back.
    """
    if not order or order_is_paid(order):
        return False
    order.payment_status = 'failed'
    order.status = 'abandoned'
    if reason:
        order.notes = f'{order.notes or ""}\n{reason}'.strip()
    forget_order_checkout_ids(order)
    db.session.commit()
    return True


def notify_seller_listing_live(product, storefront=None):
    """Confirm to a seller that their new listing went up, and say what is next.

    Both channels on purpose: the in-app note is what they see next time they
    open the hub, the email is what reaches them when they have closed the tab.

    "What is next" has three answers, not two - live, waiting on an admin, or
    waiting on the seller's own ownership proof - and getting the third one wrong
    is what leaves a second-hand phone parked indefinitely.
    """
    seller = product.seller if product.seller_id else None
    if not seller:
        return False

    status = product.review_status or 'approved'
    where = product.location_display or (storefront.business_name if storefront else '') or 'your storefront address'
    # Three outcomes, not two. A listing waiting on ownership evidence is waiting on
    # the seller, and telling them an admin will handle it is how a phone sits parked
    # forever - they have no reason to open the evidence step if they think the queue
    # is somebody else's.
    if status == 'approved':
        next_step = 'It is live in the shop now.'
        status_label = 'Live in the shop'
    elif status in ('pending_evidence', 'auto_rejected'):
        next_step = ('Before shoppers can see it, open the listing and add proof you own '
                     'the handset - the IMEI and two photos. It takes a minute and the '
                     'check is instant.')
        status_label = 'Waiting for your ownership proof'
    else:
        next_step = 'An admin still needs to approve it before shoppers can see it in the shop.'
        status_label = 'Awaiting admin review'
    body = f'"{product.name}" is listed and pinned to {where}. {next_step}'

    note = create_customer_notification(
        seller.id,
        f'Listing published: {product.name}'[:180],
        body,
        'seller_listing',
        product_id=product.id,
    )
    # A returned row that already has an id is a duplicate the helper found, so
    # a double submit does not send a second email.
    already_sent = note is not None and note.id is not None
    try:
        db.session.commit()
    except SQLAlchemyError:
        db.session.rollback()
        app.logger.exception('Seller listing notification failed for product %s', product.id)
        return False
    if already_sent:
        return False

    if not seller.email:
        return False

    # Point the seller at the step that is actually theirs. A parked listing has no
    # public page yet, so linking the shop URL sends them to a dead end at the one
    # moment they are motivated to act.
    try:
        if status in ('pending_evidence', 'auto_rejected'):
            link = url_for('seller_phone_ownership', product_id=product.id, _external=True)
            link_text = 'Add your ownership proof'
        else:
            link = url_for('product_page', slug=product.slug, _external=True)
            link_text = 'View your listing'
    except Exception:
        link = ''
        link_text = ''

    price = float(product.selling_price or 0)
    html = f"""
    <h2>Your product is listed ✅</h2>
    <p>Hi {seller.username},</p>
    <p><strong>{product.name}</strong> has been added to your SMARKAFRICA storefront.</p>
    <table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse">
        <tr><td>Price</td><td>KES {price:,.0f}</td></tr>
        <tr><td>Stock</td><td>{product.stock if not product.is_digital else 'Digital - unlimited'}</td></tr>
        <tr><td>Item location</td><td>{where}</td></tr>
        <tr><td>Status</td><td>{status_label}</td></tr>
    </table>
    {f'<p><a href="{link}">{link_text}</a></p>' if link else ''}
    <p>{next_step}</p>
    <p>We will email you again the moment it sells.</p>
    <br><p>SMARKAFRICA Team</p>
    """
    try:
        send_email(seller.email, f'"{product.name}" is now listed on SMARKAFRICA', html)
    except Exception:
        app.logger.exception('Seller listing email failed for product %s', product.id)
    return True


def notify_sellers_of_sale(order):
    """Tell each seller with a line on this order that their item sold.

    Grouped per seller so someone with three lines on one order gets one email,
    not three. Idempotent: a payment callback and a status poll both land here.
    """
    if not order:
        return 0

    by_seller = {}
    for item in order.items:
        product = item.product
        if not product or not product.seller_id or product.admin_priority:
            continue
        by_seller.setdefault(product.seller_id, []).append((product, item))

    notified = 0
    pending = []
    for seller_id, lines in by_seller.items():
        seller = db.session.get(User, seller_id)
        if not seller:
            continue

        names = ', '.join(product.name for product, _ in lines)
        gross = sum((item.price or 0) * item.quantity for _, item in lines)
        net = 0.0
        for product, item in lines:
            line_total = (item.price or 0) * item.quantity
            net += line_total - round(line_total * commission_for_product(product) / 100, 2)

        note = create_customer_notification(
            seller_id,
            f'Sold: {names}'[:180],
            f'Order {order.order_number} was paid. Pack the item for pickup - '
            f'KES {net:,.0f} is held under buyer/seller protection and releases after delivery.',
            'seller_sale',
            product_id=lines[0][0].id,
        )
        if note is not None and note.id is not None:
            continue  # already announced on an earlier callback

        notified += 1
        if not seller.email:
            continue
        pending.append((seller, lines, names, gross, net))

    # Persist the in-app notes before the network calls, so a slow or failing
    # mail provider cannot cost the seller the record of the sale.
    try:
        db.session.commit()
    except SQLAlchemyError:
        db.session.rollback()
        app.logger.exception('Seller sale notification failed for order %s', order.id)
        return 0

    for seller, lines, names, gross, net in pending:
        rows = ''.join(
            f'<tr><td>{product.name}</td><td>{item.quantity}</td>'
            f'<td>KES {(item.price or 0) * item.quantity:,.0f}</td></tr>'
            for product, item in lines
        )
        ship_to = ', '.join(part for part in [order.shipping_city, order.shipping_state,
                                              order.shipping_country] if part) or 'See order detail'
        html = f"""
        <h2>You made a sale 🎉</h2>
        <p>Hi {seller.username},</p>
        <p>Order <strong>{order.order_number}</strong> has been paid for.</p>
        <table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;width:100%">
            <tr style="background:#1a1a2e;color:white"><th>Item</th><th>Qty</th><th>Total</th></tr>
            {rows}
            <tr><td colspan="2"><strong>Gross</strong></td><td><strong>KES {gross:,.0f}</strong></td></tr>
            <tr><td colspan="2"><strong>Your earning after commission</strong></td>
                <td><strong>KES {net:,.0f}</strong></td></tr>
        </table>
        <p>Deliver to: {ship_to}</p>
        <p>Please pack the item now so the assigned carrier can collect it. Your earning is held
           under buyer/seller protection and is released once the buyer receives the order.</p>
        <br><p>SMARKAFRICA Team</p>
        """
        try:
            send_email(seller.email, f'Sold: {names[:80]} - order {order.order_number}', html)
        except Exception:
            app.logger.exception('Seller sale email failed for order %s', order.id)

    return notified


def finalize_paid_order(order):
    """
    Everything that has to wait for confirmed money: stock comes down, the sale is
    recorded under buyer/seller protection, and the paid lines leave the cart.
    Idempotent, because a callback and a status poll can both reach the same order.
    """
    if Transaction.query.filter_by(order_id=order.id, type='sale', status='held').first():
        return False

    for item in order.items:
        product = item.product
        if not product:
            continue
        if not product.is_digital:
            product.stock = max(0, (product.stock or 0) - item.quantity)
        product.sales_count = (product.sales_count or 0) + item.quantity

        commission_percent = commission_for_product(product)
        line_total = (item.price or 0) * item.quantity
        commission_amount = round(line_total * commission_percent / 100, 2)
        seller_amount = round(line_total - commission_amount, 2)
        db.session.add(Transaction(
            order_id=order.id,
            user_id=order.user_id if product.admin_priority else product.seller_id,
            type='sale',
            amount=line_total,
            description=f'Sale held under buyer/seller protection for {product.name}',
            status='held',
            commission_amount=commission_amount,
            tax_amount=0.0,
            available_on=utcnow() + timedelta(days=7)
        ))
        if product.seller_id and not product.admin_priority:
            db.session.add(Transaction(
                order_id=order.id,
                user_id=product.seller_id,
                type='seller_earning',
                amount=seller_amount,
                description=f'Net seller earning after {commission_percent:.0f}% SMARKAFRICA commission',
                status='pending_review',
                commission_amount=commission_amount,
                tax_amount=0.0,
                available_on=utcnow() + timedelta(days=7)
            ))

    paid_product_ids = [item.product_id for item in order.items if item.product_id]
    if paid_product_ids:
        Cart.query.filter(Cart.user_id == order.user_id,
                          Cart.product_id.in_(paid_product_ids)).delete(synchronize_session=False)

    # Now the money is real, the introducer gets their coins. Guarded against a
    # double credit inside the helper, since this function is reachable twice.
    record_promo_redemption(order)
    return True


@app.route('/checkout', methods=['GET', 'POST'])
@login_required
def checkout():
    # Every line's product is read repeatedly from here on - stock, weight, seller,
    # delivery - so it is loaded once with the cart rather than per access.
    cart_items = (Cart.query.options(joinedload(Cart.product))
                  .filter_by(user_id=current_user.id).all())
    if not cart_items:
        flash('Your cart is empty.', 'warning')
        return redirect(url_for('cart'))

    if request.method == 'POST':
        phone = selected_phone_value(request.form)
        shipping_address = request.form.get('shipping_address', '')
        shipping_country = request.form.get('shipping_country', '')
        shipping_city = request.form.get('shipping_city', '')
        shipping_state = request.form.get('shipping_state', '')
        delivery_method = request.form.get('delivery_method', 'doorstep')
        pickup_station = request.form.get('pickup_station', '').strip()

        if not phone:
            flash('Phone number is required for M-Pesa payment.', 'danger')
            return redirect(url_for('checkout'))

        if not country_is_supported_for_sales(shipping_country):
            flash(LAUNCH_SOON_MESSAGE, 'info')
            return redirect(url_for('checkout'))

        # Catch a delivery address in a country the seller refuses, even when it
        # differs from the country on the buyer's profile.
        blocked = [item.product.name for item in cart_items
                   if item.product and product_delivery_blocked(item.product, shipping_country)]
        if blocked:
            names = ', '.join(f'"{name}"' for name in blocked[:3])
            more = f' and {len(blocked) - 3} more' if len(blocked) > 3 else ''
            flash(f'The seller of {names}{more} does not deliver to {shipping_country}. '
                  'Remove those items or choose a different delivery country.', 'danger')
            return redirect(url_for('checkout'))

        # Calculate totals
        subtotal = 0
        has_physical = False
        total_weight = 0
        billable_weight = 0

        for item in cart_items:
            p = item.product
            if p:
                price = p.discounted_price or p.selling_price
                subtotal += price * item.quantity
                if not p.is_digital:
                    has_physical = True
                    line_weight = (p.weight_kg or 0) * item.quantity
                    total_weight += line_weight
                    # A free-delivery item must not drag the flat-rate fallback up.
                    if not product_ships_free(p):
                        billable_weight += line_weight

        # Priced per item from each seller's own location, matching the quote the
        # product page showed. Items the seller delivers free contribute zero.
        # This engine is the only pricing path: the old rate-card fallback was
        # driven by a form field, so a crafted post could pick its own charge.
        shipping_cost = 0
        if has_physical and (shipping_country or shipping_state or shipping_city):
            shipping_cost = quote_cart_delivery(
                cart_items, user=current_user, country=shipping_country,
                county=shipping_state, city=shipping_city,
                address=shipping_address, persist=True,
            )['total_amount']

        total = subtotal + shipping_cost

        # A referral code takes its cut of the goods only, and is re-checked
        # here against the real cart: the preview on the page is a convenience,
        # not the authority, so a stale or hand-edited form cannot buy a
        # discount the shopper does not qualify for.
        promo_state = evaluate_promo_code(request.form.get('promo_code'), current_user, subtotal)
        if promo_state['error']:
            flash(promo_state['error'], 'warning')
        promo = promo_state['promo']
        discount_amount = promo_state['discount']
        total = max(0.0, round(total - discount_amount, 2))

        # Create order
        order = Order(
            user_id=current_user.id,
            order_number=generate_order_number(),
            amount_paid=total,
            shipping_cost=shipping_cost,
            discount_amount=discount_amount,
            promo_code_id=promo.id if promo else None,
            shipping_address=shipping_address,
            shipping_country=shipping_country,
            shipping_city=shipping_city,
            shipping_state=shipping_state,
            delivery_method=delivery_method,
            pickup_station=pickup_station if delivery_method == 'pickup_station' else '',
            estimated_minutes_to_destination=45 if delivery_method == 'doorstep' else 0,
            mpesa_phone=phone,
            payment_method='mpesa',
            protection_status='held',
            status='pending',
            payment_status='pending',
            shipping_status='processing' if has_physical else 'digital delivery'
        )
        db.session.add(order)
        db.session.flush()
        if has_physical:
            db.session.add(TrackingUpdate(
                order_id=order.id,
                status='Order placed',
                location='SMARKAFRICA checkout',
                description='Your order was received and is waiting for payment confirmation.'
            ))

        # Create order items. Stock, seller earnings, and the cart itself are left
        # alone until payment is confirmed - see finalize_paid_order().
        for item in cart_items:
            p = item.product
            if p:
                oi = OrderItem(
                    order_id=order.id,
                    product_id=p.id,
                    product_name=p.name,
                    price=p.discounted_price or p.selling_price,
                    quantity=item.quantity,
                    is_digital=p.is_digital
                )
                db.session.add(oi)

        db.session.commit()

        # Initiate STK Push
        result = stk_push(phone, total, order.order_number)

        if result.get('success'):
            checkout_request_id = result.get('checkout_request_id')
            if checkout_request_id:
                remember_order_checkout_id(order, checkout_request_id)
                db.session.commit()
            session['polling_order_id'] = order.id
            return render_template('checkout.html', polling=True, order=order)
        else:
            response = result.get('response') or {}
            detail = response.get('errorMessage') or response.get('ResponseDescription') or response.get('responseDescription') or response.get('raw_response') or ''
            message = result.get("error", "Unknown error")
            if detail and detail not in message:
                message = f'{message}: {detail}'
            abandon_unpaid_order(order, f'STK initiation failed: {message}')
            flash(f'Payment initiation failed: {message}. Your cart is untouched - '
                  'try checking out again or clear it below.', 'warning')
            return redirect(url_for('cart'))

    # Calculate totals for display
    subtotal = 0
    total_weight = 0
    billable_weight = 0
    for item in cart_items:
        if item.product:
            price = item.product.discounted_price or item.product.selling_price
            item.subtotal = price * item.quantity
            subtotal += item.subtotal
            if not item.product.is_digital:
                line_weight = (item.product.weight_kg or 0) * item.quantity
                total_weight += line_weight
                # The flat-rate fallback bills off this figure, so a free-delivery
                # item must not add to it. Matches the POST branch above.
                if not product_ships_free(item.product):
                    billable_weight += line_weight

    # Preview delivery against wherever we think the buyer is, so the page can
    # show a real per-item breakdown. The template adds shipping to `total`
    # itself, so `total` stays pre-shipping.
    delivery_preview = quote_cart_delivery(cart_items, user=current_user)
    total = subtotal  # before shipping

    # Let the shopper try a code before committing. Nothing is written here -
    # the POST re-runs the same check against the cart it actually charges.
    promo_state = evaluate_promo_code(request.args.get('promo_code'), current_user, subtotal)
    total = max(0.0, round(total - promo_state['discount'], 2))

    return render_template('checkout.html', cart_items=cart_items, subtotal=subtotal,
                           total=total, weight_kg=billable_weight, shipping_required=total_weight > 0,
                           delivery_preview=delivery_preview,
                           promo=promo_state,
                           address_book=checkout_address_book(),
                           launch_soon_message=LAUNCH_SOON_MESSAGE,
                           show_country_launch_popup=Setting.get('show_country_launch_popup', '1') == '1')


@app.route('/api/check-payment/<int:order_id>')
@login_required
def check_payment(order_id):
    order = Order.query.get_or_404(order_id)
    if order.user_id != current_user.id:
        return jsonify({'error': 'Unauthorized'}), 403

    if order_is_paid(order):
        return jsonify({
            'payment_status': 'completed',
            'mpesa_receipt': order.mpesa_receipt
        })
    elif order.payment_status == 'failed':
        return jsonify({'payment_status': 'failed', 'cart_url': url_for('cart')})

    checkout_request_id = order_checkout_id(order)
    if checkout_request_id:
        status_data = check_payment_status(checkout_request_id)
        if status_data:
            result_code = status_data.get('ResultCode')
            if str(result_code) == '0':
                order.payment_status = 'completed'
                order.status = 'completed'
                if any(not item.is_digital for item in order.items):
                    order.shipping_status = 'processing'
                    if not TrackingUpdate.query.filter_by(order_id=order.id, status='Payment confirmed').first():
                        db.session.add(TrackingUpdate(
                            order_id=order.id,
                            status='Payment confirmed',
                            location='SMARKAFRICA payment desk',
                            description='Payment was confirmed. Your item is moving to seller packing and carrier assignment.'
                        ))
                order.mpesa_receipt = status_data.get('MpesaReceiptNumber') or order.mpesa_receipt
                finalize_paid_order(order)

                # Record transaction
                txn = Transaction(
                    order_id=order.id,
                    user_id=current_user.id,
                    type='sale',
                    amount=order.amount_paid,
                    description=f'Sale - Order {order.order_number}',
                    mpesa_receipt=order.mpesa_receipt or checkout_request_id,
                    status='completed'
                )
                db.session.add(txn)
                create_customer_notification(
                    current_user.id,
                    f'Payment confirmed for {order.order_number}',
                    'Payment was received. Your order tracking timeline has moved to packing and carrier assignment.',
                    'payment'
                )
                order_loyalty_points(order)
                db.session.commit()

                send_order_confirmation(order)
                notify_sellers_of_sale(order)

                return jsonify({
                    'payment_status': 'completed',
                    'mpesa_receipt': order.mpesa_receipt or checkout_request_id
                })
            elif result_code and str(result_code) != '1032':  # 1032 = user cancelled
                abandon_unpaid_order(
                    order,
                    f'M-Pesa payment failed: {status_data.get("ResultDesc", result_code)}')
                return jsonify({'payment_status': 'failed', 'cart_url': url_for('cart')})

    return jsonify({'payment_status': 'pending'})


@app.route('/mpesa/callback', methods=['POST'])
@csrf.exempt  # M-Pesa callbacks can't include CSRF tokens
@limiter.limit("100 per hour")  # Rate limit callbacks
def mpesa_callback():
    """
    Daraja API callback endpoint for STK Push results
    SECURITY: Signature verification added
    """
    try:
        # Verify callback signature if provided
        signature = request.headers.get('X-Safaricom-Signature')
        if signature:
            mpesa_secret = setting_value('daraja_callback_secret', app.config.get('DARAJA_PASSKEY', ''))
            if mpesa_secret and not verify_mpesa_signature(request.data, signature, mpesa_secret):
                logger.warning(f'Invalid M-Pesa callback signature from IP: {request.remote_addr}')
                log_admin_action('mpesa_callback_invalid_signature', None, None,
                               {'ip': request.remote_addr, 'signature': signature[:20]})
                return jsonify({'ResultCode': 1, 'ResultDesc': 'Invalid signature'}), 401

        data = request.get_json(silent=True)
        if not data:
            body = request.data.decode('utf-8')
            data = json.loads(body) if body else {}

        stk_callback = data.get('Body', {}).get('stkCallback', {}) or data.get('stkCallback', {})
        checkout_id = stk_callback.get('CheckoutRequestID', '')
        merchant_id = stk_callback.get('MerchantRequestID', '')
        result_code = int(stk_callback.get('ResultCode', 1))
        result_desc = stk_callback.get('ResultDesc', '')
        order = None

        if checkout_id:
            order = order_for_checkout_id(checkout_id)

        if result_code == 0:
            metadata = stk_callback.get('CallbackMetadata', {}).get('Item', [])
            receipt = ''
            amount = 0
            phone = ''

            for item in metadata:
                name = item.get('Name')
                if name == 'MpesaReceiptNumber':
                    receipt = item.get('Value', '')
                elif name == 'Amount':
                    amount = item.get('Value', 0)
                elif name == 'PhoneNumber':
                    phone = str(item.get('Value', ''))

            if not order and receipt:
                # Fallback for a callback whose CheckoutRequestID we cannot match
                # (an order created by an older build, or a replayed callback).
                #
                # Guessing is worse than not guessing: crediting the wrong order
                # both hands one customer someone else's goods and leaves the real
                # payer unpaid. So match on phone and amount within a short window
                # and only accept an unambiguous single hit - anything else is left
                # for reconciliation, where a human can see the receipt.
                phone = normalize_mpesa_phone(phone)
                window_start = datetime.utcnow() - timedelta(hours=6)
                candidate_query = Order.query.filter(
                    Order.payment_status == 'pending',
                    Order.created_at >= window_start,
                )
                if phone:
                    candidate_query = candidate_query.filter(Order.mpesa_phone.isnot(None))
                candidates = [
                    candidate
                    for candidate in candidate_query.order_by(Order.created_at.desc()).limit(50).all()
                    if abs((candidate.amount_paid or 0) - float(amount or 0)) < 1
                    and (not phone or normalize_mpesa_phone(candidate.mpesa_phone) == phone)
                ]
                if len(candidates) == 1:
                    order = candidates[0]
                    app.logger.info(
                        'M-Pesa receipt %s matched order %s by phone and amount (no checkout id)',
                        receipt, order.order_number,
                    )
                elif len(candidates) > 1:
                    app.logger.error(
                        'M-Pesa receipt %s matches %s pending orders (%s) for phone %s amount %s; '
                        'left unmatched for reconciliation rather than credited to a guess.',
                        receipt, len(candidates),
                        ', '.join(c.order_number for c in candidates[:5]), phone, amount,
                    )
                else:
                    app.logger.error(
                        'M-Pesa receipt %s (phone %s, amount %s) matched no pending order; '
                        'needs reconciliation.',
                        receipt, phone, amount,
                    )

            if order and receipt:
                order.payment_status = 'completed'
                order.status = 'completed'
                order.mpesa_receipt = receipt
                if any(not item.is_digital for item in order.items):
                    order.shipping_status = 'processing'
                    if not TrackingUpdate.query.filter_by(order_id=order.id, status='Payment confirmed').first():
                        db.session.add(TrackingUpdate(
                            order_id=order.id,
                            status='Payment confirmed',
                            location='SMARKAFRICA payment desk',
                            description='Payment was confirmed. Your item is moving to seller packing and carrier assignment.'
                        ))

                finalize_paid_order(order)

                existing_txn = Transaction.query.filter_by(order_id=order.id, mpesa_receipt=receipt).first()
                if not existing_txn:
                    txn = Transaction(
                        order_id=order.id,
                        user_id=order.user_id,
                        type='sale',
                        amount=order.amount_paid,
                        description=f'Sale - Order {order.order_number}',
                        mpesa_receipt=receipt,
                        status='completed'
                    )
                    db.session.add(txn)
                create_customer_notification(
                    order.user_id,
                    f'Payment confirmed for {order.order_number}',
                    'Payment was received. Your order tracking timeline has moved to packing and carrier assignment.',
                    'payment'
                )
                order_loyalty_points(order)

                db.session.commit()
                send_order_confirmation(order)
                notify_sellers_of_sale(order)

                for item in order.items:
                    if item.product:
                        apply_auto_discount(item.product)
                db.session.commit()
        elif order:
            abandon_unpaid_order(order, f'M-Pesa payment failed: {result_desc or merchant_id}')

        # Also check POS sale payments
        pos_setting = Setting.query.filter_by(key=f'pos_stk_{checkout_id}').first()
        if pos_setting:
            pos_sale = PointOfSaleSale.query.get(int(pos_setting.value))
            if pos_sale and pos_sale.payment_status != 'paid':
                if result_code == 0:
                    pos_sale.payment_status = 'paid'
                    mpesa_receipt = receipt if result_code == 0 else ''
                    pos_sale.notes = (pos_sale.notes or '') + f'\nM-Pesa confirmed: {mpesa_receipt}'
                    db.session.delete(pos_setting)
                    db.session.commit()
                else:
                    pos_sale.payment_status = 'failed'
                    pos_sale.notes = (pos_sale.notes or '') + f'\nM-Pesa failed: {result_desc}'
                    db.session.delete(pos_setting)
                    db.session.commit()

        ad_setting = Setting.query.filter_by(key=f'ad_stk_{checkout_id}').first()
        if ad_setting:
            ad = AdCampaign.query.get(int(ad_setting.value))
            if ad and ad.status == 'pending_payment':
                if result_code == 0:
                    ad.status = 'pending_approval'
                    record_platform_revenue(
                        'seller_ad',
                        float(amount or ad.total_charged or 0),
                        f'Paid ad campaign #{ad.id}',
                        str(ad.id),
                        'ad_campaign',
                        ad.seller_id
                    )
                    db.session.delete(ad_setting)
                    db.session.commit()
                else:
                    ad.status = 'payment_failed'
                    db.session.delete(ad_setting)
                    db.session.commit()

        # Invoices. One indexed lookup on InvoicePayment.checkout_request_id rather
        # than a Setting row per push like the two blocks above, so this stays the
        # same cost whether the platform has issued ten invoices or ten million.
        if settle_invoice_stk(checkout_id, result_code, receipt, amount, result_desc):
            db.session.commit()

        return jsonify({'ResultCode': 0, 'ResultDesc': 'Success'})
    except Exception as e:
        print(f"M-Pesa callback error: {e}")
        return jsonify({'ResultCode': 1, 'ResultDesc': str(e)})


@app.route('/admin/pos/charge-card', methods=['POST'])
@login_required
@admin_required
def admin_pos_charge_card():
    """Process bank card payment at POS via Flutterwave."""
    data = request.get_json(silent=True) or {}
    amount = float(data.get('amount', 0) or 0)
    email = data.get('email', '').strip()
    phone = data.get('phone', '').strip()
    card_number = data.get('card_number', '').strip()
    cvv = data.get('cvv', '').strip()
    expiry_month = data.get('expiry_month', '').strip()
    expiry_year = data.get('expiry_year', '').strip()
    sale_id = data.get('sale_id')

    if not all([amount, card_number, cvv, expiry_month, expiry_year]):
        return jsonify({'success': False, 'error': 'All card details are required'}), 400

    tx_ref = f'POS-{sale_id or "CHARGE"}-{int(utcnow().timestamp())}'

    result = initiate_flutterwave_charge(
        amount=amount,
        email=email,
        phone=phone,
        card_number=card_number,
        cvv=cvv,
        expiry_month=expiry_month,
        expiry_year=expiry_year,
        tx_ref=tx_ref,
    )

    if result.get('success'):
        # Store reference for verification
        if sale_id:
            Setting.query.filter_by(key=f'flw_pos_{tx_ref}').delete()
            db.session.add(Setting(key=f'flw_pos_{tx_ref}', value=str(sale_id)))
            db.session.commit()

        return jsonify({
            'success': True,
            'requires_validation': result.get('requires_validation', False),
            'auth_mode': result.get('auth_mode'),
            'data': result.get('data', {}),
            'tx_ref': tx_ref,
        })

    return jsonify({'success': False, 'error': result.get('error', 'Card charge failed')}), 400


@app.route('/flutterwave/callback', methods=['GET', 'POST'])
@csrf.exempt
def flutterwave_callback():
    """Flutterwave payment callback."""
    if request.method == 'GET':
        tx_ref = request.args.get('tx_ref', '')
        transaction_id = request.args.get('transaction_id', '')
        status = request.args.get('status', '')
    else:
        data = request.get_json(silent=True) or {}
        tx_ref = data.get('tx_ref', '') or data.get('data', {}).get('tx_ref', '')
        transaction_id = str(data.get('id', '') or data.get('data', {}).get('id', ''))
        status = data.get('status', '') or data.get('data', {}).get('status', '')

    if status == 'successful' and transaction_id:
        verification = verify_flutterwave_transaction(transaction_id)
        if verification.get('success'):
            # Check if this is a POS payment
            pos_ref = Setting.query.filter_by(key=f'flw_pos_{tx_ref}').first()
            if pos_ref:
                sale = PointOfSaleSale.query.get(int(pos_ref.value))
                if sale and sale.payment_status != 'paid':
                    sale.payment_status = 'paid'
                    sale.notes = (sale.notes or '') + f'\nCard payment confirmed: {verification.get("flw_ref", "")}'
                    db.session.delete(pos_ref)
                    db.session.commit()
                    flash('Card payment confirmed!', 'success')
                    return redirect(url_for('admin_pos_sale', sale_id=sale.id))

            # Check if this is an online order payment
            order_ref = Setting.query.filter_by(key=f'flw_order_{tx_ref}').first()
            if order_ref:
                order = Order.query.get(int(order_ref.value))
                if order and not order_is_paid(order):
                    # 'completed' is the status every other query filters on.
                    order.payment_status = 'completed'
                    order.status = 'processing'
                    finalize_paid_order(order)
                    db.session.delete(order_ref)
                    db.session.commit()
                    notify_sellers_of_sale(order)

    flash('Payment processed.', 'info')
    return redirect(url_for('admin_pos'))


