@app.route('/orders')
@login_required
def orders():
    # Only orders where the money actually arrived. A failed or still-pending
    # checkout is not an order yet - the buyer's cart is where they pick it up again.
    #
    # Paginated and eager-loaded together, because the template prints
    # item.product.name for every line of every order: unpaginated that was one
    # query for the orders, one per order for its items, and one per item for its
    # product. A regular with 200 orders was running roughly 800 queries to open
    # this page, and the number only ever grew.
    page = request.args.get('page', 1, type=int)
    pagination = (Order.query
                  .options(joinedload(Order.items).joinedload(OrderItem.product))
                  .filter(Order.user_id == current_user.id,
                          Order.payment_status.in_(ORDER_PAID_STATUSES))
                  .order_by(Order.created_at.desc())
                  .paginate(page=max(1, page), per_page=ORDERS_PER_PAGE, error_out=False))
    return render_template('orders.html', orders=pagination.items, pagination=pagination)


@app.route('/order/<int:order_id>')
@login_required
def order_detail(order_id):
    order = Order.query.get_or_404(order_id)
    if order.user_id != current_user.id and not current_user.is_admin:
        abort(403)
    # Admins still need to inspect unpaid attempts; buyers get sent back to the cart.
    if not order_is_paid(order) and not current_user.is_admin:
        flash('That checkout was not paid for, so it is not in your orders. '
              'Your cart still has the items - check out again or clear it.', 'info')
        return redirect(url_for('cart'))
    return render_template('order_detail.html', order=order)


@app.route('/order/<int:order_id>/retry-payment', methods=['POST'])
@login_required
def retry_payment(order_id):
    order = Order.query.get_or_404(order_id)
    if order.user_id != current_user.id:
        abort(403)
    if order_is_paid(order):
        flash('This order is already paid.', 'info')
        return redirect(url_for('order_detail', order_id=order.id))
    # A failed checkout was already handed back to the cart, so retrying means
    # checking out again from there rather than reviving the abandoned attempt.
    if order.payment_status == 'failed':
        flash('That payment did not go through. Your cart still has the items - '
              'check out again or clear the cart.', 'info')
        return redirect(url_for('cart'))

    phone = request.form.get('phone', '').strip() or order.mpesa_phone or current_user.phone
    if not phone:
        flash('Add an M-Pesa phone number before retrying payment.', 'danger')
        return redirect(url_for('cart'))

    result = stk_push(phone, order.amount_paid, order.order_number)
    if result.get('success'):
        checkout_request_id = result.get('checkout_request_id')
        if checkout_request_id:
            remember_order_checkout_id(order, checkout_request_id)
        order.mpesa_phone = phone
        order.payment_status = 'pending'
        db.session.commit()
        create_customer_notification(
            current_user.id,
            f'Order {order.order_number} created',
            'Your order is in checkout. Tracking will update as payment, packing, carrier handoff, and delivery progress.',
            'order'
        )
        db.session.commit()
        session['polling_order_id'] = order.id
        return render_template('checkout.html', polling=True, order=order)

    response = result.get('response') or {}
    detail = response.get('errorMessage') or response.get('ResponseDescription') or response.get('responseDescription') or response.get('raw_response') or ''
    message = result.get('error', 'Unknown error')
    if detail and detail not in message:
        message = f'{message}: {detail}'
    abandon_unpaid_order(order, f'STK retry failed: {message}')
    flash(f'Payment retry failed: {message}. Your cart still has the items.', 'warning')
    return redirect(url_for('cart'))


@app.route('/track/<int:order_id>')
@login_required
def track_order(order_id):
    order = Order.query.get_or_404(order_id)
    if order.user_id != current_user.id and not current_user.is_admin:
        abort(403)
    eta_minutes = order.estimated_minutes_to_destination
    assignment = active_assignment_for_order(order.id)
    if assignment and assignment.eta_minutes is not None:
        # A live driver fix beats any stored guess.
        eta_minutes = int(assignment.eta_minutes)
    elif order.shipping_status and order.shipping_status.lower() in ['out for delivery', 'in transit'] and eta_minutes is None:
        eta_minutes = 12 if order.shipping_status.lower() == 'out for delivery' else 45

    origin_point, origin_label = shipping_origin_point()
    return render_template('track_order.html',
                           order=order,
                           tracking_updates=order.tracking_updates,
                           eta_minutes=eta_minutes,
                           assignment=assignment,
                           origin_lat=origin_point.lat,
                           origin_lng=origin_point.lng,
                           origin_label=origin_label,
                           map_style_url=map_style_url())


@app.route('/api/download/<int:order_id>/<int:product_id>')
@login_required
@limiter.limit("10 per hour")  # Rate limit downloads
def download_digital(order_id, product_id):
    """
    Serve digital product files after purchase verification
    SECURITY: Path sanitization to prevent directory traversal
    """
    order = Order.query.get_or_404(order_id)
    if order.user_id != current_user.id:
        log_admin_action('unauthorized_download_attempt', 'order', order_id,
                        {'user_id': current_user.id, 'product_id': product_id})
        abort(403)

    if order.payment_status != 'completed':
        flash('Payment not completed.', 'danger')
        return redirect(url_for('orders'))

    product = Product.query.get_or_404(product_id)
    if not product.is_digital or not product.file_path:
        abort(404)

    if not any(item.product_id == product.id and item.is_digital for item in order.items):
        log_admin_action('unauthorized_download_attempt', 'product', product_id,
                        {'user_id': current_user.id, 'order_id': order_id})
        abort(403)

    # Cloud-stored files are handed over as a signed URL that expires in minutes,
    # minted here and nowhere else - which is to say only after all four checks
    # above have passed. Note the ordering: the gate is unchanged and still runs in
    # full, and only the delivery of an already-authorised file moved.
    reference = parse_cloudinary_reference(product.file_path)
    if reference:
        download_name = f'{secure_filename(product.slug) or "download"}'
        extension = product_file_extension(product)
        if extension:
            download_name = f'{download_name}.{extension}'
        signed = signed_private_download_url(product.file_path,
                                             download_name=download_name)
        if not signed:
            logger.error('Digital product %s is stored in Cloudinary but could not '
                         'be signed for delivery', product_id)
            abort(503)
        log_admin_action('digital_download', 'product', product_id,
                        {'user_id': current_user.id, 'order_id': order_id,
                         'filename': download_name, 'storage': 'cloudinary'})
        return redirect(signed)

    # Sanitize file path to prevent directory traversal
    filename = sanitize_filepath(os.path.basename(product.file_path), ALLOWED_DIGITAL_EXTENSIONS)
    if not filename:
        logger.error(f'Invalid filename for product {product_id}: {product.file_path}')
        abort(404)

    # Safely construct folder path
    base_folder = app.config['UPLOAD_FOLDER']
    folder = safe_path_join(base_folder, 'digital')
    if not folder:
        logger.error(f'Invalid folder path for digital downloads')
        abort(500)

    # Verify file exists within safe path
    file_path = safe_path_join(folder, filename)
    if not file_path or not os.path.isfile(file_path):
        logger.error(f'File not found or invalid path: {filename}')
        abort(404)

    log_admin_action('digital_download', 'product', product_id,
                    {'user_id': current_user.id, 'order_id': order_id, 'filename': filename})

    return send_from_directory(folder, filename, as_attachment=True,
                               mimetype=mimetypes.guess_type(filename)[0] or 'application/octet-stream')


