@app.route('/api/shipping-cost', methods=['POST'])
def api_shipping_cost():
    """Calculate shipping cost for checkout."""
    data = request.get_json() or {}
    weight = float(data.get('weight_kg', 0) or 0)
    country = data.get('country')
    state = data.get('state')
    city = data.get('city')
    if not country_is_supported_for_sales(country):
        return jsonify({'shipping_cost': 0, 'available': False, 'message': LAUNCH_SOON_MESSAGE})

    # A signed-in shopper gets their real cart priced line by line, from each
    # seller's location, so this matches what checkout() will charge. Anonymous
    # callers fall back to a single weight-based quote.
    if current_user.is_authenticated:
        cart_items = Cart.query.filter_by(user_id=current_user.id).all()
        if cart_items:
            cart_quote = quote_cart_delivery(
                cart_items, user=current_user, country=country, county=state,
                city=city, address=data.get('address'),
            )
            # Only what the summary renders. The zone, flat fee, per-km rate,
            # distance and weight behind the figure stay server-side.
            return jsonify({
                'shipping_cost': cart_quote['total_amount'],
                'available': True,
                'free_delivery': cart_quote['free_delivery'],
                'lines': [
                    {
                        'product_name': line['product_name'],
                        'origin_label': line['origin_label'],
                        'amount': line['amount'],
                        'free_delivery': line['free_delivery'],
                        'is_digital': line['is_digital'],
                    }
                    for line in cart_quote['lines']
                ],
            })

    quote = quote_shipping(
        country=country,
        county=state,
        city=city,
        address=data.get('address'),
        lat=data.get('lat'),
        lng=data.get('lng'),
        weight_kg=weight,
        order_value=float(data.get('order_value', 0) or 0),
        user_id=current_user.id if current_user.is_authenticated else None,
        persist=False,
    )
    return jsonify({
        'shipping_cost': quote['total_amount'],
        'available': True,
        'free_delivery': bool(quote.get('free_delivery')),
    })


