@app.route('/api/geo/search')
@limiter.limit('60 per minute')
def api_geo_search():
    """Address autocomplete backed by the configured geocoder."""
    query = (request.args.get('q') or '').strip()
    country = (request.args.get('country') or 'Kenya').strip()
    if len(query) < 2:
        return jsonify({'results': []})
    hit = cached_geocode(cache, query, country)
    if not hit.found:
        return jsonify({'results': []})
    return jsonify({'results': [{
        'label': hit.label,
        'lat': hit.point.lat,
        'lng': hit.point.lng,
        'county': hit.county,
        'country': hit.country,
        'confidence': hit.confidence,
        'provider': hit.provider,
    }]})


@app.route('/support', methods=['GET', 'POST'])
@limiter.limit("10 per hour", methods=['POST'])
def support():
    """Support center with AI chatbot and voice features"""
    if request.method == 'POST':
        subject = request.form.get('subject', '').strip()
        body = request.form.get('body', '').strip()
        severity = request.form.get('severity', 'normal')
        channel = request.form.get('channel', 'web')

        if not subject or not body:
            flash('Describe the support issue so the team can help quickly.', 'danger')
            return redirect(url_for('support'))

        due_hours = 24 if severity in ['normal', 'high'] else 48
        if severity == 'urgent':
            due_hours = 12
        if channel == 'whatsapp' or severity == 'urgent':
            severity = 'urgent'
            channel = 'whatsapp'

        ticket = SupportTicket(
            user_id=current_user.id if current_user.is_authenticated else None,
            channel=channel,
            subject=subject,
            body=body,
            severity=severity,
            response_due_at=utcnow() + timedelta(hours=4),
            resolution_due_at=utcnow() + timedelta(hours=due_hours),
        )
        db.session.add(ticket)
        db.session.commit()

        log_admin_action('support_ticket_created', 'ticket', ticket.id, {
            'severity': severity,
            'channel': channel,
            'user_id': current_user.id if current_user.is_authenticated else None
        })

        if channel == 'whatsapp':
            whatsapp_url = support_whatsapp_url(
                f'Urgent SMARKAFRICA support ticket #{ticket.id}: {subject}')
            flash(f'Urgent ticket created. WhatsApp support is ready at {support_whatsapp_number()}',
                  'warning')
            return redirect(whatsapp_url)

        flash('Support ticket created. The team will track it against the response SLA.', 'success')
        return redirect(url_for('support'))

    tickets = []
    if current_user.is_authenticated:
        tickets = SupportTicket.query.filter_by(user_id=current_user.id).order_by(
            SupportTicket.created_at.desc()
        ).limit(10).all()

    # Use enhanced template with voice features
    try:
        return render_template('support_enhanced.html', tickets=tickets)
    except:
        # Fallback to original template if enhanced doesn't exist yet
        return render_template('support.html', tickets=tickets)


def support_ai_reply(message):
    text_value = (message or '').lower()
    # Services first: the keyword fallback runs when the chatbot import fails, and
    # a services question answered with "I can help with orders and payments" is
    # the one failure a client would read as the feature not existing.
    try:
        services = service_chatbot_reply(message)
    except Exception as exc:
        logger.warning(f'service chatbot fallback failed: {exc}')
        services = None
    if services:
        reply = services.get('reply', '')
        if services.get('follow_up'):
            reply = f"{reply}\n\n{services['follow_up']}"
        return reply
    if any(word in text_value for word in ['refund', 'wrong item', 'return', 'reversal']):
        return f'For refunds, keep your order number and M-Pesa receipt ready. I can help create an urgent ticket and route it to WhatsApp support at {support_whatsapp_number()}.'
    if any(word in text_value for word in ['security', 'hack', 'account', 'password', 'fraud', 'suspicious']):
        return f'For platform security, change your password, avoid sharing OTPs, and escalate immediately through WhatsApp support at {support_whatsapp_number()}. I can also create a tracked ticket.'
    if any(word in text_value for word in ['payment', 'stk', 'mpesa', 'm-pesa']):
        return 'For M-Pesa/STK issues, confirm the number is Safaricom, use 07XXXXXXXX or 2547XXXXXXXX, and retry once. If money was deducted, share the receipt through support.'
    if any(word in text_value for word in ['delivery', 'shipping', 'track', 'carrier']):
        return 'For delivery, open My Orders or Track Order to see the latest timeline. If the parcel is late, create a high-priority support ticket with your order number.'
    if any(word in text_value for word in ['bnpl', 'pay later', 'installment', 'instalment', 'lock']):
        return 'For BNPL, check your deposit, due date, and installment status. Overdue financed devices may enter calls/SMS-only mode until payment clears.'
    return f'I can help with orders, payments, refunds, delivery, BNPL, account security, services, and seller/storefront questions. For urgent refunds or security, use WhatsApp support at {support_whatsapp_number()}.'


@app.route('/api/support/chatbot', methods=['POST'])
@limiter.limit("30 per minute")
def support_chatbot():
    """Enhanced AI chatbot with NLP and product recommendations"""
    data = request.get_json(silent=True) or {}
    message = data.get('message', '').strip()

    if not message:
        return jsonify({
            'reply': 'Tell me what happened and include an order number if you have one.',
            'urgent': False
        })

    # Services are answered here rather than inside ChatbotAI because the answer
    # needs the duty cache, the catalogue and Setting - and because a services
    # question must never fall through to product search, which "I need laundry"
    # otherwise matches on the word "need".
    payload = {}
    try:
        services = service_chatbot_reply(message,
                                         current_user if current_user.is_authenticated else None)
    except Exception as exc:
        logger.warning(f'service chatbot turn failed: {exc}')
        services = None

    if services:
        reply = services.get('reply', '')
        payload = {key: value for key, value in services.items() if key != 'reply'}
    else:
        # Use enhanced chatbot
        try:
            from chatbot_ai import create_chatbot_instance
            chatbot = create_chatbot_instance(app)
            user = current_user if current_user.is_authenticated else None
            reply = chatbot.get_response(message, user)
        except Exception as e:
            logger.error(f"Chatbot error: {e}")
            reply = support_ai_reply(message)  # Fallback to old method

    # Check if message is urgent
    urgent = any(word in message.lower() for word in [
        'urgent', 'refund', 'security', 'fraud', 'hacked', 'deducted',
        'stolen', 'emergency', 'help', 'scam'
    ])

    # reply / urgent / whatsapp_url keep their existing names and meaning. The
    # services keys (options, providers, action, follow_up) are additive, so a
    # cached copy of the old support page keeps working through the deploy.
    response = {
        'reply': reply,
        'urgent': urgent,
        'whatsapp_url': support_whatsapp_url(),
        'timestamp': datetime.utcnow().isoformat()
    }
    response.update(payload)
    return jsonify(response)


STOREFRONT_REVIEW_STATUSES = ['pending_review', 'more_details', 'approved', 'suspended', 'rejected']


def geocode_storefront(storefront):
    """Fill in the storefront's map pin from its written address.

    Idempotent and cheap: the geocoder is cached, and a storefront that already
    has coordinates is left alone.
    """
    if storefront.location_lat is not None and storefront.location_lng is not None:
        return storefront
    address = ', '.join([p for p in [storefront.physical_address, storefront.landmark] if p])
    try:
        point, county, _label = resolve_destination(
            country='Kenya', address=address or None, city=storefront.landmark or None)
    except Exception:
        app.logger.exception('Storefront geocode failed for %s', storefront.id)
        return storefront
    if point:
        storefront.location_lat = point.lat
        storefront.location_lng = point.lng
    if county:
        storefront.location_county = county
    return storefront


def notify_admins_of_storefront(storefront):
    """Push a new application at every admin, not just whoever opens a console.

    Applications used to sit in a table nobody had a reason to open, which is
    why they never reached review.
    """
    address = storefront.physical_address or 'no address given'
    for admin in User.query.filter(User.is_admin.is_(True)).all():
        create_customer_notification(
            admin.id,
            'Storefront awaiting approval',
            f'{storefront.business_name} ({address}) applied for a storefront. '
            f'Open the storefront queue to approve or reject it.',
            'storefront'
        )


def review_storefront(storefront, status, notes=None):
    """Apply an approval decision and tell the owner what happened.

    Shared by the dedicated queue and the MVP architecture console so the two
    can never drift on what approval actually does.
    """
    status = (status or storefront.status or 'pending_review').strip()
    if status not in STOREFRONT_REVIEW_STATUSES:
        status = storefront.status or 'pending_review'
    storefront.status = status
    if notes is not None:
        storefront.verification_notes = (notes or '').strip()
    if status == 'approved':
        if not storefront.approved_at:
            storefront.approved_at = utcnow()
        geocode_storefront(storefront)
    if storefront.owner:
        create_customer_notification(
            storefront.owner.id,
            f'Storefront review: {status.replace("_", " ").title()}',
            storefront.verification_notes or f'Your storefront application for {storefront.business_name} was updated.',
            'storefront'
        )
        if status == 'approved':
            create_customer_notification(
                storefront.owner.id,
                'You can now list products',
                f'{storefront.business_name} is verified. Open "List a product" to publish your first item.',
                'storefront'
            )
        if storefront.owner.email:
            send_email(
                storefront.owner.email,
                'SMARK-Africa storefront application update',
                f'<p>Your storefront application for <strong>{html.escape(storefront.business_name)}</strong> '
                f'is now <strong>{html.escape(status)}</strong>.</p>'
                f'<p>{html.escape(storefront.verification_notes or "")}</p>'
                + ('<p>You can now list products from your seller dashboard.</p>' if status == 'approved' else '')
            )
    return storefront


def storefront_manage_view(storefront):
    """Listing page for an approved storefront.

    Replaces the application form: the owner describes what the shop deals in
    and works from their live product list instead of re-submitting details.
    """
    if request.method == 'POST':
        # Two forms post here: the shop details and the deal announcement.
        if request.form.get('action') == 'announce':
            message = (request.form.get('announcement', '') or '').strip()
            if not message:
                flash('Write the deal or clearance you want followers to hear about.', 'danger')
            elif storefront_follower_count(storefront) == 0:
                flash('No one follows your shop yet, so there is nobody to notify.', 'info')
            else:
                reached = notify_storefront_followers(
                    storefront,
                    f'{storefront.business_name}: new deal',
                    message[:2000],
                )
                db.session.commit()
                flash(f'Announcement sent to {reached} follower{"" if reached == 1 else "s"}.', 'success')
            return redirect(url_for('storefront_apply'))

        storefront.about = (request.form.get('about', '') or '').strip()[:4000]
        storefront.specialties = (request.form.get('specialties', '') or '').strip()[:500]

        contact_phone = normalize_mpesa_phone(request.form.get('contact_phone', storefront.contact_phone or ''))
        contact_email = normalize_email(request.form.get('contact_email', storefront.contact_email or ''))
        if contact_phone:
            storefront.contact_phone = contact_phone
        if contact_email:
            storefront.contact_email = contact_email

        address = (request.form.get('physical_address', '') or '').strip()
        landmark = (request.form.get('landmark', '') or '').strip()
        # Re-pin only when the address actually moved; geocoding is a network call.
        address_changed = address and address != (storefront.physical_address or '')
        if address:
            storefront.physical_address = address
        if landmark:
            storefront.landmark = landmark
        if address_changed:
            geocode_storefront(storefront)

        db.session.commit()
        flash('Shop details updated.', 'success')
        return redirect(url_for('storefront_apply'))

    products = Product.query.filter_by(seller_id=storefront.owner_id).order_by(
        Product.created_at.desc()).limit(12).all()
    stats = {
        'total': Product.query.filter_by(seller_id=storefront.owner_id).count(),
        'live': Product.query.filter_by(
            seller_id=storefront.owner_id, is_active=True, review_status='approved').count(),
        'pending_review': Product.query.filter(
            Product.seller_id == storefront.owner_id,
            Product.review_status != 'approved').count(),
    }
    categories = nav_categories()
    return render_template('storefront_manage.html', storefront=storefront,
                           products=products, stats=stats, categories=categories,
                           follower_count=storefront_follower_count(storefront))


@app.route('/storefront/apply', methods=['GET', 'POST'])
@login_required
def storefront_apply():
    if not user_can_sell(current_user):
        flash('Complete seller verification first. Storefronts are for verified businesses that want wider product visibility.', 'warning')
        return redirect(url_for('seller_apply'))

    # An approved storefront has already cleared review, so this page stops
    # being an application form and becomes the shop's own listing page.
    approved = seller_storefront(current_user)
    if approved:
        return storefront_manage_view(approved)

    if request.method == 'POST':
        business_name = request.form.get('business_name', '').strip()
        category_id = request.form.get('category_id', type=int)
        category = Category.query.get(category_id) if category_id else None
        physical_address = request.form.get('physical_address', '').strip()
        landmark = request.form.get('landmark', '').strip()
        contact_phone = normalize_mpesa_phone(request.form.get('contact_phone', current_user.phone or ''))
        contact_email = normalize_email(request.form.get('contact_email', current_user.email or ''))
        if not business_name or not category or not physical_address or not landmark or not contact_phone or not contact_email:
            flash('Business name, exact address, landmark, contact details, and category are required for storefront review.', 'danger')
            return redirect(url_for('storefront_apply'))
        base_slug = re.sub(r'[^a-z0-9]+', '-', business_name.lower()).strip('-')[:160] or f'business-{current_user.id}'
        slug = base_slug
        counter = 1
        while BusinessStorefront.query.filter_by(slug=slug).first():
            counter += 1
            slug = f'{base_slug}-{counter}'
        storefront = BusinessStorefront(
            owner_id=current_user.id,
            business_name=business_name,
            slug=slug,
            categories=category.name,
            category_id=category.id,
            physical_address=physical_address,
            landmark=landmark,
            contact_phone=contact_phone,
            contact_email=contact_email,
            commission_percent=10.0,
            status='pending_review',
        )
        # Pin it now so the queue can show reviewers where the shop actually is.
        geocode_storefront(storefront)
        db.session.add(storefront)
        db.session.flush()
        notify_admins_of_storefront(storefront)
        db.session.commit()
        flash('Storefront application submitted. Our review team has been notified.', 'success')
        return redirect(url_for('storefront_apply'))
    storefronts = BusinessStorefront.query.filter_by(owner_id=current_user.id).order_by(BusinessStorefront.created_at.desc()).all()
    categories = nav_categories()
    return render_template('storefront_apply.html', storefronts=storefronts, categories=categories)


@app.route('/bnpl/apply/<int:product_id>', methods=['GET', 'POST'])
@login_required
def bnpl_apply(product_id):
    product = Product.query.get_or_404(product_id)
    policy = BNPLProductPolicy.query.filter_by(product_id=product.id, is_enabled=True).first()
    if not policy:
        flash('BNPL is not enabled for this product yet.', 'warning')
        return redirect(url_for('product_page', slug=product.slug))
    if request.method == 'POST':
        deposit = request.form.get('deposit_percent', type=float) or policy.min_deposit_percent
        term_months = request.form.get('term_months', type=int) or policy.max_term_months
        deposit = max(policy.min_deposit_percent, min(20.0, deposit))
        term_months = max(1, min(policy.max_term_months, term_months))
        principal = product.discounted_price or product.selling_price or 0
        risk = bnpl_risk_score(current_user)
        status = 'approved' if risk >= 75 else 'manual_review'
        plan = BNPLPlan(
            user_id=current_user.id,
            product_id=product.id,
            principal_amount=principal,
            deposit_percent=deposit,
            term_months=term_months,
            risk_score=risk,
            approval_status=status,
            device_lock_code=request.form.get('device_lock_code', '').strip() or generate_bnpl_lock_code(),
            device_imei=normalize_imei(request.form.get('device_imei', '')),
            device_serial=request.form.get('device_serial', '').strip()[:80],
            device_install_method=request.form.get('device_install_method', 'imei') if request.form.get('device_install_method') in {'imei', 'usb'} else 'imei',
            next_due_at=utcnow() + timedelta(days=30),
            approved_at=utcnow() if status == 'approved' else None,
        )
        db.session.add(plan)
        db.session.flush()
        update_bnpl_device_fields(plan)
        create_bnpl_installments(plan)
        db.session.commit()
        flash(f'BNPL application submitted. Risk score {risk}; status {status}.', 'success')
        return redirect(url_for('orders'))
    return render_template('bnpl_apply.html', product=product, policy=policy, risk_score=bnpl_risk_score(current_user))


def handle_bnpl_admin_action():
    action = request.form.get('action', '')
    if action == 'bnpl_lock':
        plan = BNPLPlan.query.get_or_404(request.form.get('plan_id', type=int))
        plan.device_lock_code = request.form.get('device_lock_code', plan.device_lock_code or '').strip() or generate_bnpl_lock_code(plan)
        plan.lock_status = request.form.get('lock_status', plan.lock_status or 'unlocked')
        update_bnpl_device_fields(plan)
        if plan.lock_status == 'unlocked':
            plan.last_reminder_at = utcnow()
        flash('BNPL device lock status updated.', 'success')
        return True
    if action == 'bnpl_generate_code':
        plan = BNPLPlan.query.get_or_404(request.form.get('plan_id', type=int))
        plan.device_lock_code = generate_bnpl_lock_code(plan)
        update_bnpl_device_fields(plan)
        flash('BNPL device lock code generated.', 'success')
        return True
    if action == 'create_bnpl':
        user = User.query.get_or_404(request.form.get('user_id', type=int))
        product = Product.query.get_or_404(request.form.get('product_id', type=int))
        principal = request.form.get('principal_amount', type=float) or (product.discounted_price or product.selling_price or 0)
        deposit = request.form.get('deposit_percent', type=float) or 15.0
        term_months = request.form.get('term_months', type=int) or 3
        risk = bnpl_risk_score(user)
        status = 'approved' if risk >= 75 and 10 <= deposit <= 20 and term_months <= 6 else 'manual_review'
        plan = BNPLPlan(
            user_id=user.id,
            product_id=product.id,
            principal_amount=principal,
            deposit_percent=max(10, min(20, deposit)),
            term_months=max(1, min(6, term_months)),
            risk_score=risk,
            approval_status=status,
            device_lock_code=request.form.get('device_lock_code', '').strip() or generate_bnpl_lock_code(),
            device_imei=normalize_imei(request.form.get('device_imei', '')),
            device_serial=request.form.get('device_serial', '').strip()[:80],
            device_install_method=request.form.get('device_install_method', 'imei') if request.form.get('device_install_method') in {'imei', 'usb'} else 'imei',
            next_due_at=utcnow() + timedelta(days=30),
            approved_at=utcnow() if status == 'approved' else None,
        )
        db.session.add(plan)
        db.session.flush()
        update_bnpl_device_fields(plan)
        create_bnpl_installments(plan)
        flash(f'BNPL plan created with risk score {risk} and status {status}.', 'success')
        return True
    if action == 'bnpl_policy':
        product = Product.query.get_or_404(request.form.get('product_id', type=int))
        policy = BNPLProductPolicy.query.filter_by(product_id=product.id).first()
        if not policy:
            policy = BNPLProductPolicy(product_id=product.id)
            db.session.add(policy)
        policy.is_enabled = request.form.get('is_enabled') == '1'
        policy.min_deposit_percent = max(10, min(20, request.form.get('min_deposit_percent', type=float) or 15))
        policy.max_term_months = max(1, min(6, request.form.get('max_term_months', type=int) or 3))
        policy.partner_name = request.form.get('partner_name', '').strip()
        policy.notes = request.form.get('notes', '').strip()
        policy.approved_by = current_user.id
        flash(f'BNPL policy updated for {product.name}.', 'success')
        return True
    if action == 'bnpl_payment':
        installment = BNPLInstallment.query.get_or_404(request.form.get('installment_id', type=int))
        paid = request.form.get('amount_paid', type=float) or installment.amount_due
        installment.amount_paid = min(installment.amount_due, installment.amount_paid + paid)
        if installment.amount_paid >= installment.amount_due:
            installment.status = 'paid'
            installment.paid_at = utcnow()
        update_bnpl_lock_status(installment.plan)
        flash('BNPL installment payment recorded.', 'success')
        return True
    return False


@app.route('/admin/bnpl', methods=['GET', 'POST'])
@login_required
@mvp_required
def admin_bnpl():
    if request.method == 'POST':
        if handle_bnpl_admin_action():
            db.session.commit()
        return redirect(url_for('admin_bnpl'))
    plans = BNPLPlan.query.order_by(BNPLPlan.created_at.desc()).limit(80).all()
    changed = False
    for plan in plans:
        if not plan.device_remote_payload:
            build_bnpl_device_payload(plan)
            changed = True
        plan.remote_functional_code = bnpl_remote_functional_code(plan)
    if changed:
        db.session.commit()
    return render_template(
        'admin/bnpl.html',
        bnpl_plans=plans,
        bnpl_policies=BNPLProductPolicy.query.order_by(BNPLProductPolicy.updated_at.desc()).limit(80).all(),
        bnpl_installments=BNPLInstallment.query.order_by(BNPLInstallment.due_at.asc()).limit(120).all(),
        users=User.query.order_by(User.created_at.desc()).limit(120).all(),
        products=Product.query.filter_by(is_active=True, is_digital=False).order_by(Product.created_at.desc()).limit(120).all(),
    )


