@login_required
@admin_required
def admin_pos_cart_add():
    data = request.get_json(silent=True) or request.form
    barcode = (data.get('barcode') or '').strip()
    action = normalize_scan_action(data.get('action'))
    try:
        product_id = int(data.get('product_id') or 0)
    except (TypeError, ValueError):
        product_id = 0
    product = product_by_barcode(barcode) if barcode else Product.query.get(product_id) if product_id else None
    if not product:
        return jsonify({'success': False, 'error': 'Product not found'}), 404
    # A sold-out item must not join the sale. Hand the barcode back so the screen
    # can drop it into Register Product for a restock instead.
    if action != 'remove' and pos_product_out_of_stock(product):
        return jsonify(pos_out_of_stock_response(product, barcode)), 409
    if action == 'remove':
        remove_product_from_pos_terminal(product, int(data.get('quantity') or 1))
    else:
        add_product_to_pos_terminal(product, int(data.get('quantity') or 1))
    db.session.commit()
    return jsonify({'success': True, 'cart': pos_terminal_payload()})


@app.route('/admin/inventory', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_inventory():
    if request.method == 'POST':
        product = Product.query.get_or_404(request.form.get('product_id', type=int))
        adjustment = int(request.form.get('adjustment', 0) or 0)
        product.stock = max(0, (product.stock or 0) + adjustment)
        product.weight_kg = float(request.form.get('weight_kg', product.weight_kg or 0) or 0)
        product.is_active = request.form.get('is_active') == '1'
        db.session.commit()
        flash(f'Inventory updated for {product.name}.', 'success')
        return redirect(url_for('admin_inventory'))
    products = Product.query.order_by(Product.stock.asc(), Product.name.asc()).all()
    return render_template('admin/inventory.html', products=products, warnings=stock_warnings())


@app.route('/admin/products/add', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_add_product():
    categories = nav_categories(active_only=False)

    if request.method == 'POST':
        admin_user_id = current_user.id
        admin_is_admin = bool(current_user.is_admin)
        name = request.form.get('name', '').strip()
        description = request.form.get('description', '')
        short_description = request.form.get('short_description', '')[:300]
        category_id = request.form.get('category_id', type=int)
        buying_price = form_float('buying_price', 0, minimum=0)
        selling_price = form_float('selling_price', 0, minimum=0)
        discount_percent = form_float('discount_percent', 0, minimum=0, maximum=99)
        is_digital = request.form.get('is_digital') in ['1', 'on', 'true']
        stock = form_int('stock', 0, minimum=0)
        weight_kg = form_float('weight_kg', 0, minimum=0)
        is_active = request.form.get('is_active') in ['1', 'on', 'true']
        is_featured = request.form.get('is_featured') in ['1', 'on', 'true']
        product_condition = request.form.get('product_condition', 'new')
        sale_mode = request.form.get('sale_mode', 'direct')
        bid_price = form_float('bid_price', 0, minimum=0)
        commission_percent = form_float('commission_percent', 15, minimum=10.0, maximum=15.0)
        vat_applicable = request.form.get('vat_applicable') in ['1', 'on', 'true']
        vat_rate = form_float('vat_rate', 16 if vat_applicable else 0, minimum=0, maximum=100) if vat_applicable else 0
        admin_priority = request.form.get('admin_priority') in ['1', 'on', 'true']
        is_hot_sale = request.form.get('is_hot_sale') in ['1', 'on', 'true']
        is_original_source = admin_is_admin and request.form.get('is_original_source') in ['1', 'on', 'true']


        if not name or buying_price < 0 or selling_price <= 0:
            flash('Product name and valid prices are required.', 'danger')
            return render_template('admin/add_product.html', categories=categories)

        slug = unique_product_slug(name)

        product = Product(
            name=name, slug=slug, description=description,
            short_description=short_description, category_id=category_id,
            buying_price=buying_price, selling_price=selling_price,
            discount_percent=discount_percent,
            vat_applicable=vat_applicable, vat_rate=vat_rate,
            is_digital=is_digital, stock=stock, weight_kg=weight_kg,
            is_featured=is_featured, is_active=is_active,
            seller_id=admin_user_id, product_condition=product_condition,
            sale_mode=sale_mode, bid_price=bid_price,
            commission_percent=commission_percent, admin_priority=admin_priority or admin_is_admin,
            is_hot_sale=is_hot_sale, hot_sale_started_at=utcnow() if is_hot_sale else None,
            is_original_source=is_original_source
        )
        try:
            price_reference = market_price_reference(name, category_id, selling_price, buying_price, description=description)
            if price_reference['status'] != 'ok':
                flash(
                    f"Market price warning for {price_reference['label']}: {price_reference['message']} "
                    f"Kenya range KSh {price_reference['kenya_low']:,.2f} - KSh {price_reference['kenya_high']:,.2f}; "
                    f"manufacturer estimate KSh {price_reference['manufacturer_price']:,.2f}.",
                    'warning'
                )
        except Exception as exc:
            app.logger.warning('Product market price advisory skipped during create: %s', exc)
            flash('Product details are valid. Market price advisory could not refresh for this item right now.', 'warning')
        if product.sale_mode == 'bid' and product.bid_price < (product.selling_price * 0.75):
            flash('Bid price cannot be below three quarters of the direct sale price.', 'danger')
            return render_template('admin/add_product.html', categories=categories, product=None)
        if product.product_condition in ['second_hand', 'refurbished']:
            product.review_status = 'manual_second_review'
            product.is_active = False
        elif product.product_condition == 'thrifted':
            product.review_status = 'admin_review'
        else:
            product.review_status = 'approved'

        # An admin posting a second-hand phone is posting platform stock whose
        # history they already know, so it does not go through the evidence flow or
        # a review queue - there is nobody above them to review it. The IMEI is
        # still recorded below when supplied, which is what makes the duplicate
        # check work against platform stock too.
        admin_phone_listing = (admin_is_admin
                               and product.product_condition in PHONE_EVIDENCE_CONDITIONS
                               and is_phone_listing(name, db.session.get(Category, category_id)
                                                    if category_id else None))
        if admin_phone_listing:
            product.review_status = 'approved'
            product.is_active = is_active

        # Give the listing a pin so its card matches seller-listed products.
        apply_product_location(
            product,
            storefront=seller_storefront(current_user),
            label=request.form.get('location_label', ''),
            lat=request.form.get('location_lat', type=float),
            lng=request.form.get('location_lng', type=float),
        )

        product.excluded_countries = serialize_excluded_countries(
            request.form.getlist('excluded_countries'))
        product.free_delivery = bool(request.form.get('free_delivery'))

        # One-off brand stock. Admin-set, like the brand flag on a seller account.
        product.is_brand_partner = bool(request.form.get('is_brand_partner'))
        product.brand_label = (request.form.get('brand_label', '') or '').strip()[:80] \
            if product.is_brand_partner else None

        # Handle image upload
        product_images = uploaded_product_images()
        if product_images:
            product.image_url = product_images[0]
            if len(product_images) > 1:
                product.additional_images = json.dumps(product_images[1:])
        elif request.form.get('image_url', '').strip():
            product.image_url = request.form.get('image_url', '').strip()

        # Handle digital file upload
        if is_digital and 'digital_file' in request.files and request.files['digital_file'].filename:
            file = request.files['digital_file']
            if not allowed_digital_file(file.filename) or not allowed_digital_file_signature(file):
                flash('Digital uploads must match an allowed file type and valid file signature.', 'danger')
                return render_template('admin/add_product.html', categories=categories, product=None)
            product.file_path = save_uploaded_file(file, 'digital')
            product.file_size = os.path.getsize(
                os.path.join(app.config['UPLOAD_FOLDER'], 'digital',
                             os.path.basename(product.file_path))
            ) if os.path.exists(os.path.join(app.config['UPLOAD_FOLDER'], 'digital',
                                             os.path.basename(product.file_path))) else 0

        try:
            db.session.add(product)
            db.session.flush()

            # Register the handset against the listing so the next person to submit
            # this IMEI hits the duplicate check. Optional on the admin form: no
            # IMEI simply means no registration, not a blocked save.
            if admin_phone_listing and normalize_imei(request.form.get('device_imei', '')):
                record_phone_evidence(product, request.form.get('device_imei', ''),
                                      None, None, as_admin=True)

            if product.admin_priority and not Review.query.filter_by(product_id=product.id, is_admin_review=True).first():
                db.session.add(Review(
                    user_id=admin_user_id,
                    product_id=product.id,
                    rating=4,
                    comment='Trusted listing with responsive service and clear product details.',
                    is_visible=True,
                    is_admin_review=True
                ))

            # Auto-apply discount check
            apply_auto_discount(product)
            db.session.commit()
        except SQLAlchemyError as exc:
            db.session.rollback()
            app.logger.exception('Product create failed; retrying schema upgrade before returning admin form: %s', exc)
            try:
                ensure_phase_two_schema()
                Setting.set('phase_two_schema_version', phase_two_schema_fingerprint())
            except Exception:
                db.session.rollback()
                app.logger.exception('Product create schema repair failed')
            flash('Product could not be saved because the database schema was not ready. I ran the schema repair; please submit once more.', 'danger')
            return render_template('admin/add_product.html', categories=categories, product=None)
        except Exception as exc:
            db.session.rollback()
            app.logger.exception('Product create failed: %s', exc)
            flash('Product could not be saved. Check the server logs for the exact create-product error.', 'danger')
            return render_template('admin/add_product.html', categories=categories, product=None)

        if Setting.get('product_create_send_alerts_sync', '0') == '1':
            try:
                alert_count = notify_price_alerts()
                if alert_count:
                    flash(f'{alert_count} buyer price alert email(s) were triggered by this listing.', 'info')
            except Exception as exc:
                app.logger.warning('Price alert notification skipped after product create: %s', exc)

        invalidate_product_cache()
        flash(f'Product "{name}" created successfully!', 'success')
        return redirect(url_for('admin_products'))

    return render_template('admin/add_product.html', categories=categories, product=None)


@app.route('/admin/products/edit/<int:pid>', methods=['GET', 'POST'])
@login_required
@admin_required
def admin_edit_product(pid):
    product = Product.query.get_or_404(pid)
    categories = nav_categories(active_only=False)

    if request.method == 'POST':
        name = request.form.get('name', product.name).strip()
        buying_price = form_float('buying_price', product.buying_price or 0, minimum=0)
        selling_price = form_float('selling_price', product.selling_price or 0, minimum=0)
        if not name or selling_price <= 0:
            flash('Product name and valid selling price are required.', 'danger')
            return render_template('admin/add_product.html', categories=categories, product=product)

        product.name = name
        requested_slug = request.form.get('slug', '').strip()
        product.slug = unique_product_slug(requested_slug or product.name, current_id=product.id)
        product.description = request.form.get('description', product.description)
        product.short_description = request.form.get('short_description', product.short_description)[:300]
        product.category_id = request.form.get('category_id', type=int) or product.category_id
        product.buying_price = buying_price
        product.selling_price = selling_price
        product.is_digital = form_bool('is_digital')
        product.stock = form_int('stock', product.stock or 0, minimum=0)
        product.weight_kg = form_float('weight_kg', product.weight_kg or 0, minimum=0)
        product.is_featured = form_bool('is_featured')
        product.is_active = form_bool('is_active')
        product.discount_percent = form_float('discount_percent', product.discount_percent or 0, minimum=0, maximum=99)
        apply_product_location(
            product,
            storefront=seller_storefront(current_user) if product.seller_id == current_user.id else None,
            label=request.form.get('location_label', product.location_label or ''),
            lat=request.form.get('location_lat', type=float),
            lng=request.form.get('location_lng', type=float),
        )
        product.excluded_countries = serialize_excluded_countries(
            request.form.getlist('excluded_countries'))
        product.free_delivery = form_bool('free_delivery')
        product.is_brand_partner = current_user.is_admin and form_bool('is_brand_partner')
        product.brand_label = (request.form.get('brand_label', '') or '').strip()[:80] \
            if product.is_brand_partner else None
        product.vat_applicable = form_bool('vat_applicable')
        product.vat_rate = form_float('vat_rate', product.vat_rate or (16 if product.vat_applicable else 0), minimum=0, maximum=100) if product.vat_applicable else 0
        product.product_condition = request.form.get('product_condition', product.product_condition or 'new')
        product.sale_mode = request.form.get('sale_mode', product.sale_mode or 'direct')
        product.bid_price = form_float('bid_price', product.bid_price or 0, minimum=0)
        product.commission_percent = form_float('commission_percent', product.commission_percent or 15, minimum=10.0, maximum=15.0)
        product.admin_priority = form_bool('admin_priority')
        was_hot_sale = bool(product.is_hot_sale)
        product.is_hot_sale = form_bool('is_hot_sale')
        if product.is_hot_sale and not was_hot_sale:
            product.hot_sale_started_at = utcnow()
        elif not product.is_hot_sale:
            product.hot_sale_started_at = None
        product.is_original_source = current_user.is_admin and form_bool('is_original_source')
        price_reference = market_price_reference(
            product.name,
            product.category_id,
            product.selling_price,
            product.buying_price,
            exclude_id=product.id,
            description=product.description
        )
        if price_reference['status'] != 'ok':
            flash(
                f"Market price warning for {price_reference['label']}: {price_reference['message']} "
                f"Kenya range KSh {price_reference['kenya_low']:,.2f} - KSh {price_reference['kenya_high']:,.2f}; "
                f"manufacturer estimate KSh {price_reference['manufacturer_price']:,.2f}.",
                'warning'
            )

        if product.sale_mode == 'bid' and product.bid_price < (product.selling_price * 0.75):
            flash('Bid price cannot be below three quarters of the direct sale price.', 'danger')
            return render_template('admin/add_product.html', categories=categories, product=product)

        # Verify discount doesn't cause loss
        if product.discount_percent > 0:
            max_allowed = ((
                                       product.selling_price - product.buying_price) / product.selling_price) * 100 if product.selling_price > 0 else 0
            if product.discount_percent > max_allowed and product.buying_price > 0:
                flash(
                    f'WARNING: This discount ({product.discount_percent:.0f}%) exceeds the maximum ({max_allowed:.0f}%) and will cause a LOSS!',
                    'danger')

        # Handle image
        product_images = uploaded_product_images()
        extra_images = []
        if product.additional_images:
            try:
                extra_images = json.loads(product.additional_images)
            except Exception:
                extra_images = []
        if product_images:
            product.image_url = product_images[0]
            extra_images.extend(product_images[1:])
        elif request.form.get('image_url', '').strip():
            product.image_url = request.form.get('image_url', '').strip()
        if extra_images:
            product.additional_images = json.dumps(extra_images)

        # Handle digital file
        if product.is_digital and 'digital_file' in request.files and request.files['digital_file'].filename:
            file = request.files['digital_file']
            if not allowed_digital_file(file.filename) or not allowed_digital_file_signature(file):
                flash('Digital uploads must match an allowed file type and valid file signature.', 'danger')
                return render_template('admin/add_product.html', categories=categories, product=product)
            product.file_path = save_uploaded_file(file, 'digital')
            product.file_size = os.path.getsize(
                os.path.join(app.config['UPLOAD_FOLDER'], 'digital',
                             os.path.basename(product.file_path))
            ) if os.path.exists(os.path.join(app.config['UPLOAD_FOLDER'], 'digital',
                                             os.path.basename(product.file_path))) else 0

        db.session.commit()
        invalidate_product_cache()
        flash('Product updated successfully!', 'success')
        return redirect(url_for('admin_products'))

    return render_template('admin/add_product.html', categories=categories, product=product)


