# --- Driver dispatch & live tracking ---

DRIVER_STALE_MINUTES = 10  # no ping for this long => treat the fix as stale


def driver_ping_is_fresh(driver, minutes=DRIVER_STALE_MINUTES):
    if not (driver and driver.last_ping_at):
        return False
    return (utcnow() - driver.last_ping_at) <= timedelta(minutes=minutes)


def driver_payload(driver):
    return {
        'id': driver.id,
        'name': driver.display_name or (driver.user.username if driver.user else f'Driver {driver.id}'),
        'phone': driver.phone,
        'vehicle_type': driver.vehicle_type,
        'vehicle_registration': driver.vehicle_registration,
        'status': driver.status,
        'lat': driver.last_lat,
        'lng': driver.last_lng,
        'accuracy_m': driver.last_accuracy_m,
        'last_ping_at': driver.last_ping_at.isoformat() if driver.last_ping_at else None,
        'is_fresh': driver_ping_is_fresh(driver),
        'has_fix': driver.has_fix,
    }


DRIVER_TRAIL_MINUTES = 180   # how far back the dispatch map draws a journey
DRIVER_TRAIL_POINTS = 120    # cap so a long shift cannot bloat the poll payload


def driver_trail(driver_id, order_id=None, minutes=DRIVER_TRAIL_MINUTES, limit=DRIVER_TRAIL_POINTS):
    """Recent GPS breadcrumbs for one driver, oldest first.

    Scoped to an order when there is one, so the line drawn on the map is the
    journey of the delivery being watched rather than everywhere the phone has
    been today. Newest rows are taken first and then reversed - the tail of the
    trip is the part worth seeing, and the limit keeps the 15s poll small.
    """
    query = DriverLocationPing.query.filter(
        DriverLocationPing.driver_id == driver_id,
        DriverLocationPing.created_at >= utcnow() - timedelta(minutes=minutes),
    )
    if order_id:
        query = query.filter(DriverLocationPing.order_id == order_id)
    rows = query.order_by(DriverLocationPing.created_at.desc()).limit(limit).all()
    return [
        {
            'lat': row.lat,
            'lng': row.lng,
            'at': row.created_at.isoformat() if row.created_at else None,
            # Accuracy and an epoch are what let the matcher decide how far a fix
            # may be moved and whether a gap is travel or a bad reading.
            'accuracy_m': row.accuracy_m,
            'epoch_seconds': row.created_at.replace(tzinfo=timezone.utc).timestamp()
                             if row.created_at else None,
            'speed_kph': row.speed_kph,
            'heading': row.heading,
        }
        for row in reversed(rows)
    ]


# OSRM's /match service takes 100 coordinates per request by default, so the
# 120-point trail is trimmed from the tail before it is sent anywhere.
DRIVER_TRACE_MAX_POINTS = 100


def driver_trail_path(trail):
    """Road-following geometry for a breadcrumb trail.

    Raw pings joined end to end cut across blocks and buildings, because a fix
    every ~20s says nothing about the road taken in between. Map matching snaps
    the sequence onto the network so the drawn line is the route actually driven.

    Returns the shape the map layers consume::

        {'coordinates': [[lng, lat], ...], 'is_road_matched': bool,
         'provider': str, 'distance_km': float}

    `is_road_matched` is False when no matcher is configured (the default) - the
    coordinates are then the driver's own fixes with the obviously-bad ones
    removed, and the map draws them dashed to say so. Never raises: the dispatch
    poll refreshes every 15s and a matching outage must not take it down.
    """
    points = [
        TracePoint(
            lat=entry['lat'],
            lng=entry['lng'],
            accuracy_m=entry.get('accuracy_m'),
            epoch_seconds=entry.get('epoch_seconds'),
        )
        for entry in (trail or [])
        if entry.get('lat') is not None and entry.get('lng') is not None
    ]
    points = points[-DRIVER_TRACE_MAX_POINTS:]

    if len(points) < 2:
        return {'coordinates': [], 'is_road_matched': False,
                'provider': 'none', 'distance_km': 0.0}

    try:
        result = cached_match(cache, points)
        return {
            'coordinates': result.coordinates,
            'is_road_matched': result.is_road_matched,
            'provider': result.provider,
            'distance_km': round(result.distance_km or 0.0, 3),
        }
    except Exception:  # noqa: BLE001 - never let the map lose its trace
        app.logger.exception('driver trace matching failed')
        return {
            'coordinates': [[p.lng, p.lat] for p in points],
            'is_road_matched': False,
            'provider': 'error',
            'distance_km': 0.0,
        }


def active_assignment_for_order(order_id):
    return DeliveryAssignment.query.filter(
        DeliveryAssignment.order_id == order_id,
        DeliveryAssignment.status.in_(['assigned', 'picked_up', 'in_transit'])
    ).order_by(DeliveryAssignment.assigned_at.desc()).first()


def recalculate_assignment_eta(assignment, driver=None):
    """Refresh remaining distance/ETA from the driver's latest fix."""
    driver = driver or assignment.driver
    if not (driver and driver.has_fix):
        return assignment
    if assignment.destination_lat is None or assignment.destination_lng is None:
        return assignment

    route = cached_route(
        cache,
        GeoPoint(driver.last_lat, driver.last_lng),
        GeoPoint(assignment.destination_lat, assignment.destination_lng),
    )
    assignment.distance_remaining_km = route.rounded_km()
    assignment.eta_minutes = round(route.duration_minutes, 1) if route.duration_minutes else None
    assignment.eta_updated_at = utcnow()

    # Mirror onto the order so the customer tracking page stays a single read.
    order = assignment.order
    if order and assignment.eta_minutes is not None:
        order.estimated_minutes_to_destination = int(assignment.eta_minutes)
    return assignment


def driver_tracking_url(driver):
    """Absolute driver console link, or '' when there is no token to hand out.

    Built on the configured public base URL rather than the request host: a link
    texted to a driver has to work on their handset, and request.host_url is
    whatever the admin happened to be browsing - localhost during development,
    an internal hostname behind a proxy. Falls back to url_for when nothing is
    configured, and works outside a request context either way.
    """
    if not driver or not driver.tracking_token:
        return ''
    path = f'/driver/{driver.tracking_token}'
    try:
        base = public_base_url()
        if base:
            return base + path
    except Exception:
        pass
    try:
        return url_for('driver_console', token=driver.tracking_token, _external=True)
    except Exception:
        return path


def driver_link_message(driver, reason='created'):
    """The exact words sent to a driver, shared by every channel.

    Built once so the WhatsApp API message, the wa.me deep link and the SMS all
    say the same thing - a driver comparing two of them should see one message.
    """
    link = driver_tracking_url(driver)
    if not link:
        return ''
    name = driver.display_name or (driver.user.username if driver.user else 'there')
    opening = ('Your SMARKAFRICA driver tracking link is ready'
               if reason == 'created' else
               'Your SMARKAFRICA driver tracking link has been regenerated')
    return (f'Hi {name}. {opening}:\n\n{link}\n\n'
            'Open it once on the phone you deliver with and allow location - '
            'dispatch follows you on the map from there and you can keep using '
            'your phone normally. '
            'Keep the link to yourself; it reports your position as you.')


def notify_driver_tracking_link(driver, reason='created'):
    """Hand a driver their tracking link the moment it is minted.

    Every channel we have, because a link nobody opens tracks nothing: WhatsApp
    first (it is what drivers actually read), SMS as the fallback that lands on
    any handset, plus an in-app note and an email for the record. The returned
    dict says which channels genuinely delivered, so the admin is told what
    really went out rather than a hopeful "sent!".
    """
    result = {'link': driver_tracking_url(driver), 'share_url': '',
              'whatsapp': False, 'sms': False, 'email': False, 'in_app': False}
    message = driver_link_message(driver, reason)
    if not message:
        return result

    result['share_url'] = whatsapp_share_url(driver.phone, message)

    if driver.user_id:
        note = create_customer_notification(
            driver.user_id,
            'Your driver tracking link is ready' if reason == 'created'
            else 'Your driver tracking link changed',
            message,
            'driver_link',
        )
        result['in_app'] = note is not None
        try:
            db.session.commit()
        except SQLAlchemyError:
            db.session.rollback()
            app.logger.exception('Driver link notification failed for driver %s', driver.id)
            result['in_app'] = False

    if driver.phone:
        result['whatsapp'] = send_whatsapp_message(driver.phone, message)
        # SMS goes out either way: it is the one channel that lands without
        # WhatsApp installed, and a duplicate costs less than an untracked run.
        result['sms'] = send_sms_notification(normalize_mpesa_phone(driver.phone), message)

    user = driver.user
    if user and user.email:
        name = driver.display_name or user.username
        link = result['link']
        html = f"""
        <h2>Your driver tracking link</h2>
        <p>Hi {name},</p>
        <p>Open this once on the phone you deliver with and allow location.
           Dispatch follows your position on the map from there, and you can
           carry on using your phone as normal.</p>
        <p><a href="{link}" style="background:#0d6efd;color:#fff;padding:10px 18px;
           border-radius:6px;text-decoration:none;display:inline-block">Open my driver console</a></p>
        <p style="font-size:12px;color:#666">{link}</p>
        <p><strong>Keep this link private.</strong> Anyone holding it can report a position as you.</p>
        <br><p>SMARKAFRICA Dispatch</p>
        """
        try:
            send_email(user.email, 'Your SMARKAFRICA driver tracking link', html)
            result['email'] = True
        except Exception:
            app.logger.exception('Driver link email failed for driver %s', driver.id)

    return result


def flash_driver_link_result(driver, result, prefix):
    """Report the channel outcomes in one honest sentence."""
    who = driver.display_name or (driver.user.username if driver.user else 'the driver')
    sent = [label for label, key in (('WhatsApp', 'whatsapp'), ('SMS', 'sms'),
                                     ('email', 'email'), ('in-app', 'in_app'))
            if result.get(key)]
    if result.get('whatsapp'):
        flash(f'{prefix} Tracking link sent to {who} on {", ".join(sent)}.', 'success')
    elif sent:
        flash(f'{prefix} Tracking link sent to {who} by {", ".join(sent)}. WhatsApp is not '
              f'connected, so tap "WhatsApp" on their card to send it there too.', 'success')
    elif result.get('share_url'):
        flash(f'{prefix} Nothing could be sent automatically. Tap "WhatsApp" on '
              f'{who}\'s card to share the link in one tap.', 'warning')
    else:
        flash(f'{prefix} No phone or email on file for {who}, so the link could not be '
              f'sent - add a phone number, or copy the link from their card.', 'warning')


def driver_link_redirect(driver, result):
    """Back to dispatch, flagging whether the admin still has to press send.

    wa=1 means the Cloud API did not carry the message, so the page offers the
    one-tap wa.me hand-off instead of pretending WhatsApp already has it.
    """
    return redirect(url_for('admin_dispatch', share=driver.id,
                            wa=0 if result.get('whatsapp') else 1))


@app.route('/admin/dispatch')
@login_required
@admin_required
def admin_dispatch():
    drivers = DriverProfile.query.filter_by(is_active=True).order_by(DriverProfile.display_name.asc()).all()
    assignments = DeliveryAssignment.query.filter(
        DeliveryAssignment.status.in_(['assigned', 'picked_up', 'in_transit'])
    ).order_by(DeliveryAssignment.assigned_at.desc()).all()
    # Anything paid and not yet on the road. Shipping status has been written in
    # mixed case across the payment, admin and assignment paths ('Processing' from
    # checkout, 'processing' from a driver assignment), so it is matched case
    # insensitively - otherwise a freshly paid order never reaches this queue.
    # Rows predating the column default carry NULL and are included too.
    live_assignment_orders = db.session.query(DeliveryAssignment.order_id).filter(
        DeliveryAssignment.status.in_(['assigned', 'picked_up', 'in_transit'])
    ).scalar_subquery()
    pending_orders = Order.query.filter(
        Order.payment_status.in_(ORDER_PAID_STATUSES),
        or_(
            Order.shipping_status.is_(None),
            func.lower(func.trim(Order.shipping_status)).in_(
                ['', 'pending', 'processing', 'ready', 'ready for dispatch']),
        ),
        # An order already with a live driver is not offered for assignment twice.
        ~Order.id.in_(live_assignment_orders),
    ).order_by(Order.created_at.desc()).limit(50).all()
    origin_point, origin_label = shipping_origin_point()
    # One-tap WhatsApp hand-off per driver, prebuilt server side because the
    # message body carries that driver's own console link.
    share_links = {d.id: whatsapp_share_url(d.phone, driver_link_message(d)) for d in drivers}
    return render_template(
        'admin/dispatch.html',
        drivers=drivers,
        assignments=assignments,
        pending_orders=pending_orders,
        origin_lat=origin_point.lat,
        origin_lng=origin_point.lng,
        origin_label=origin_label,
        map_style_url=map_style_url(),
        share_links=share_links,
        share_driver_id=request.args.get('share', type=int),
        share_prompt_whatsapp=request.args.get('wa') == '1',
    )


@app.route('/admin/dispatch/drivers/save', methods=['POST'])
@login_required
@admin_required
def admin_save_driver():
    driver_id = (request.form.get('driver_id') or '').strip()
    driver = DriverProfile.query.get(int(driver_id)) if driver_id.isdigit() else None
    is_new = driver is None
    previous_phone = (driver.phone or '') if driver else ''

    if driver is None:
        username = (request.form.get('username') or '').strip()
        user = User.query.filter(func.lower(User.username) == username.lower()).first() if username else None
        if not user:
            flash(f'No user account found for "{username}". Create the account first.', 'danger')
            return redirect(url_for('admin_dispatch'))
        if DriverProfile.query.filter_by(user_id=user.id).first():
            flash(f'{user.username} already has a driver profile.', 'warning')
            return redirect(url_for('admin_dispatch'))
        driver = DriverProfile(user_id=user.id, tracking_token=secrets.token_urlsafe(32)[:64])
        db.session.add(driver)

    driver.display_name = (request.form.get('display_name') or '').strip() or driver.display_name
    driver.phone = (request.form.get('phone') or '').strip()
    driver.vehicle_type = (request.form.get('vehicle_type') or 'motorbike').strip()
    driver.vehicle_registration = (request.form.get('vehicle_registration') or '').strip()
    driver.is_active = form_bool('is_active')
    db.session.commit()
    log_admin_action('driver_saved', 'driver_profile', driver.id, {'name': driver.display_name})

    # A fresh profile means a fresh link, and a phone number arriving late means
    # the link was minted with nowhere to send it. Both deserve a send.
    phone_arrived = bool(driver.phone) and driver.phone != previous_phone
    if is_new or phone_arrived:
        result = notify_driver_tracking_link(driver, 'created')
        flash_driver_link_result(driver, result, 'Driver saved.')
        return driver_link_redirect(driver, result)

    flash('Driver saved.', 'success')
    return redirect(url_for('admin_dispatch'))


@app.route('/admin/dispatch/drivers/<int:driver_id>/send-link', methods=['POST'])
@login_required
@admin_required
def admin_send_driver_link(driver_id):
    """Resend an existing link - phone swapped, message deleted, new handset."""
    driver = DriverProfile.query.get_or_404(driver_id)
    result = notify_driver_tracking_link(driver, 'created')
    log_admin_action('driver_link_sent', 'driver_profile', driver.id,
                     {k: v for k, v in result.items() if k in ('whatsapp', 'sms', 'email', 'in_app')})
    flash_driver_link_result(driver, result, 'Link resent.')
    return driver_link_redirect(driver, result)


@app.route('/admin/dispatch/drivers/<int:driver_id>/rotate-token', methods=['POST'])
@login_required
@admin_required
def admin_rotate_driver_token(driver_id):
    driver = DriverProfile.query.get_or_404(driver_id)
    driver.tracking_token = secrets.token_urlsafe(32)[:64]
    db.session.commit()
    log_admin_action('driver_token_rotated', 'driver_profile', driver.id, {})
    # The old link died the moment that commit landed, so the new one has to go
    # out now or the driver silently drops off the map.
    result = notify_driver_tracking_link(driver, 'rotated')
    flash_driver_link_result(driver, result, 'Link regenerated.')
    return driver_link_redirect(driver, result)


@app.route('/admin/dispatch/assign', methods=['POST'])
@login_required
@admin_required
def admin_assign_delivery():
    order_id = int(form_float('order_id', 0))
    driver_id = int(form_float('driver_id', 0))
    order = Order.query.get_or_404(order_id)
    driver = DriverProfile.query.get_or_404(driver_id)

    existing = active_assignment_for_order(order.id)
    if existing:
        flash(f'Order {order.order_number} is already with {existing.driver.display_name or "a driver"}.', 'warning')
        return redirect(url_for('admin_dispatch'))

    # Snapshot the destination so a later address edit cannot break the ETA.
    dest_point, dest_county, dest_label = resolve_destination(
        country=order.shipping_country,
        county=order.shipping_state,
        city=order.shipping_city,
        address=order.shipping_address,
    )
    assignment = DeliveryAssignment(
        order_id=order.id,
        driver_id=driver.id,
        status='assigned',
        destination_lat=dest_point.lat if dest_point else None,
        destination_lng=dest_point.lng if dest_point else None,
        destination_label=(dest_label or '')[:240],
    )
    db.session.add(assignment)
    driver.status = 'on_delivery'
    order.shipping_status = 'processing'
    db.session.add(TrackingUpdate(
        order_id=order.id, status='Assigned to driver',
        location=dest_label, description=f'Assigned to {driver.display_name or driver.id}.'
    ))
    db.session.commit()
    recalculate_assignment_eta(assignment, driver)
    db.session.commit()
    log_admin_action('delivery_assigned', 'delivery_assignment', assignment.id,
                     {'order': order.order_number, 'driver': driver.id})
    flash(f'Order {order.order_number} assigned.', 'success')
    return redirect(url_for('admin_dispatch'))


@app.route('/admin/dispatch/assignments/<int:assignment_id>/status', methods=['POST'])
@login_required
@admin_required
def admin_update_assignment_status(assignment_id):
    assignment = DeliveryAssignment.query.get_or_404(assignment_id)
    new_status = (request.form.get('status') or '').strip()
    if new_status not in {'assigned', 'picked_up', 'in_transit', 'delivered', 'failed'}:
        flash('Unknown delivery status.', 'danger')
        return redirect(url_for('admin_dispatch'))
    apply_assignment_status(assignment, new_status)
    db.session.commit()
    flash(f'Delivery marked {new_status.replace("_", " ")}.', 'success')
    return redirect(url_for('admin_dispatch'))


def apply_assignment_status(assignment, new_status, note=None):
    """Move an assignment through its lifecycle and mirror onto the order."""
    assignment.status = new_status
    order = assignment.order
    now = utcnow()

    if new_status == 'picked_up' and not assignment.picked_up_at:
        assignment.picked_up_at = now
    if new_status == 'delivered':
        assignment.delivered_at = now
        assignment.eta_minutes = 0
        assignment.distance_remaining_km = 0

    status_map = {
        'assigned': 'processing',
        'picked_up': 'shipped',
        'in_transit': 'in transit',
        'delivered': 'delivered',
        'failed': 'processing',
    }
    if order:
        order.shipping_status = status_map.get(new_status, order.shipping_status)
        if new_status == 'delivered':
            order.status = 'completed'
            order.estimated_minutes_to_destination = 0

    if assignment.driver:
        assignment.driver.status = 'available' if new_status in {'delivered', 'failed'} else 'on_delivery'

    db.session.add(TrackingUpdate(
        order_id=assignment.order_id,
        status=new_status.replace('_', ' ').title(),
        location=assignment.destination_label,
        description=note or f'Delivery {new_status.replace("_", " ")}.',
    ))
    return assignment


@app.route('/api/dispatch/drivers')
@login_required
@admin_required
def api_dispatch_drivers():
    """Live driver positions for the dispatch map."""
    drivers = DriverProfile.query.filter_by(is_active=True).all()
    payload = []
    for driver in drivers:
        item = driver_payload(driver)
        active = DeliveryAssignment.query.filter(
            DeliveryAssignment.driver_id == driver.id,
            DeliveryAssignment.status.in_(['assigned', 'picked_up', 'in_transit'])
        ).first()
        if active:
            item['assignment'] = {
                'id': active.id,
                'order_id': active.order_id,
                'order_number': active.order.order_number if active.order else None,
                'status': active.status,
                'eta_minutes': active.eta_minutes,
                'distance_remaining_km': active.distance_remaining_km,
                'destination_label': active.destination_label,
                'destination_lat': active.destination_lat,
                'destination_lng': active.destination_lng,
            }
        # Breadcrumbs for anyone whose phone is reporting, scoped to the delivery
        # when there is one. A driver who has only just opened their link has no
        # assignment yet, and watching that first walk is the whole point of
        # sending it - so this cannot be gated on being assigned.
        if driver.has_fix:
            trail = driver_trail(driver.id, active.order_id if active else None)
            item['trail'] = trail
            # Road-snapped geometry for the drawn line; the raw trail above is
            # still what the fix dots and the movement readouts use.
            item['trail_path'] = driver_trail_path(trail)
            if trail:
                item['speed_kph'] = trail[-1].get('speed_kph')
                item['heading'] = trail[-1].get('heading')
        payload.append(item)
    return jsonify({'drivers': payload, 'server_time': utcnow().isoformat()})


def map_style_url():
    """MapLibre style URL.

    Defaults to the OSM raster style bundled below, which needs no API key.
    Point MAP_STYLE_URL at a vector tile provider for production polish.
    """
    return (os.environ.get('MAP_STYLE_URL') or Setting.get('map_style_url', '') or '').strip()


def driver_for_token(token):
    if not (token or '').strip():
        return None
    return DriverProfile.query.filter_by(tracking_token=token.strip(), is_active=True).first()


# A backgrounded phone buffers its fixes and posts them together, so one request
# can legitimately carry several minutes of driving. Bounded so a broken or
# hostile client cannot push an unbounded backlog through in a single call.
DRIVER_PING_BATCH_LIMIT = 60


def parse_client_timestamp(value):
    """A phone-supplied ISO timestamp, or None when it is absent or unusable.

    Buffered fixes carry the moment they were taken rather than the moment they
    reached us, otherwise a backlog posted after a tunnel would all land on the
    same second and the trail would show a stop where there was none. Anything
    unparseable, or far enough out of range to be a wrong device clock, is
    dropped so the caller falls back to server time.
    """
    if not value:
        return None
    try:
        text = str(value).strip().replace('Z', '+00:00')
        parsed = datetime.fromisoformat(text)
    except (TypeError, ValueError):
        return None
    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(timezone.utc).replace(tzinfo=None)
    now = utcnow()
    if parsed > now + timedelta(minutes=5) or parsed < now - timedelta(hours=24):
        return None
    return parsed


@app.route('/driver/<token>')
def driver_console(token):
    """Mobile page a driver keeps open; posts GPS on an interval.

    Token-addressed rather than login-gated so a driver can open the link on
    any phone without an app install. The token is rotatable from the admin.
    """
    driver = driver_for_token(token)
    if not driver:
        abort(404)
    assignments = DeliveryAssignment.query.filter(
        DeliveryAssignment.driver_id == driver.id,
        DeliveryAssignment.status.in_(['assigned', 'picked_up', 'in_transit'])
    ).order_by(DeliveryAssignment.assigned_at.asc()).all()
    # Seeded so the road already travelled is on the map the moment the page
    # opens - after a reload, or after the driver comes back from another app.
    trail = driver_trail(driver.id, assignments[0].order_id if assignments else None)
    return render_template(
        'driver_console.html',
        driver=driver,
        assignments=assignments,
        token=token,
        map_style_url=map_style_url(),
        ping_seconds=int(shipping_setting_float('driver_ping_seconds', 20) or 20),
        trail=trail,
        trail_path=driver_trail_path(trail),
    )


@app.route('/api/driver/<token>/ping', methods=['POST'])
@limiter.limit('120 per minute')
@csrf.exempt
def api_driver_ping(token):
    """Ingest one or more GPS fixes from a driver's phone.

    CSRF-exempt because the driver page authenticates with the bearer-style
    token in the URL rather than a session cookie.

    Accepts a batch under "points" as well as a single fix. A phone that goes
    through a tunnel, or whose browser is put in the background, buffers its
    fixes locally and posts the backlog on the next opportunity; taking them
    all in one request is what keeps the travelled line unbroken instead of
    jumping straight from the tunnel mouth to wherever the driver resurfaced.
    """
    driver = driver_for_token(token)
    if not driver:
        return jsonify({'ok': False, 'error': 'unknown driver'}), 404

    data = request.get_json(silent=True) or {}
    raw_points = data.get('points')
    if not isinstance(raw_points, list) or not raw_points:
        raw_points = [data]
    # Cap the batch so a bad client cannot post an unbounded backlog in one go.
    raw_points = raw_points[-DRIVER_PING_BATCH_LIMIT:]

    def _num(source, name):
        try:
            value = source.get(name)
            return float(value) if value is not None else None
        except (TypeError, ValueError):
            return None

    fixes = []
    for raw in raw_points:
        if not isinstance(raw, dict):
            continue
        try:
            lat = float(raw.get('lat'))
            lng = float(raw.get('lng'))
        except (TypeError, ValueError):
            continue
        if not GeoPoint(lat, lng).is_valid():
            continue
        fixes.append({
            'lat': lat,
            'lng': lng,
            'accuracy_m': _num(raw, 'accuracy_m'),
            'speed_kph': _num(raw, 'speed_kph'),
            'heading': _num(raw, 'heading'),
            'at': parse_client_timestamp(raw.get('at')),
        })

    if not fixes:
        return jsonify({'ok': False, 'error': 'lat and lng are required'}), 400

    active = DeliveryAssignment.query.filter(
        DeliveryAssignment.driver_id == driver.id,
        DeliveryAssignment.status.in_(['assigned', 'picked_up', 'in_transit'])
    ).order_by(DeliveryAssignment.assigned_at.asc()).first()

    for fix in fixes:
        db.session.add(DriverLocationPing(
            driver_id=driver.id,
            order_id=active.order_id if active else None,
            lat=fix['lat'], lng=fix['lng'], accuracy_m=fix['accuracy_m'],
            speed_kph=fix['speed_kph'], heading=fix['heading'],
            created_at=fix['at'] or utcnow(),
        ))

    # The denormalised position on the profile is what the dispatch map reads,
    # so it must follow the newest fix in the batch, not the first one stored.
    latest = fixes[-1]
    driver.last_lat = latest['lat']
    driver.last_lng = latest['lng']
    driver.last_accuracy_m = latest['accuracy_m']
    driver.last_ping_at = utcnow()
    # Derive availability from live work rather than trusting the stored value,
    # which drifts if an assignment is created outside the dispatch flow.
    driver.status = 'on_delivery' if active else 'available'

    response = {'ok': True, 'recorded_at': driver.last_ping_at.isoformat(),
                'accepted': len(fixes)}
    if active:
        recalculate_assignment_eta(active, driver)
        response['assignment'] = {
            'id': active.id,
            'order_number': active.order.order_number if active.order else None,
            'eta_minutes': active.eta_minutes,
            'distance_remaining_km': active.distance_remaining_km,
            'status': active.status,
        }
    db.session.commit()
    return jsonify(response)


@app.route('/api/driver/<token>/status', methods=['POST'])
@limiter.limit('60 per minute')
@csrf.exempt
def api_driver_status(token):
    """Driver marks a delivery picked up / in transit / delivered."""
    driver = driver_for_token(token)
    if not driver:
        return jsonify({'ok': False, 'error': 'unknown driver'}), 404

    data = request.get_json(silent=True) or {}
    new_status = (data.get('status') or '').strip()
    if new_status not in {'picked_up', 'in_transit', 'delivered', 'failed'}:
        return jsonify({'ok': False, 'error': 'unsupported status'}), 400

    assignment = DeliveryAssignment.query.filter_by(
        id=int(data.get('assignment_id') or 0), driver_id=driver.id
    ).first()
    if not assignment:
        return jsonify({'ok': False, 'error': 'assignment not found'}), 404

    apply_assignment_status(assignment, new_status, note=(data.get('note') or '').strip() or None)
    db.session.commit()
    return jsonify({'ok': True, 'status': assignment.status})


@app.route('/api/track/<order_number>')
@limiter.limit('60 per minute')
def api_track_order(order_number):
    """Public live position + ETA for the customer tracking map.

    The order number is the only credential, so it is rate limited to make
    enumeration impractical and the payload carries no personal data about
    the driver beyond a coarse position and vehicle type.
    """
    order = Order.query.filter_by(order_number=order_number).first()
    if not order:
        return jsonify({'ok': False, 'error': 'order not found'}), 404

    assignment = active_assignment_for_order(order.id)
    payload = {
        'ok': True,
        'order_number': order.order_number,
        'shipping_status': order.shipping_status,
        'destination_label': None,
        'destination_lat': None,
        'destination_lng': None,
        'driver': None,
        'eta_minutes': order.estimated_minutes_to_destination,
        'updates': [{
            'status': u.status,
            'location': u.location,
            'description': u.description,
            'created_at': u.created_at.isoformat() if u.created_at else None,
        } for u in (order.tracking_updates or [])[:12]],
    }

    if assignment:
        payload.update({
            'destination_label': assignment.destination_label,
            'destination_lat': assignment.destination_lat,
            'destination_lng': assignment.destination_lng,
            'eta_minutes': assignment.eta_minutes,
            'distance_remaining_km': assignment.distance_remaining_km,
            'delivery_status': assignment.status,
        })
        driver = assignment.driver
        # Only expose a live position while the parcel is actually moving, and
        # only a coarse fix - never the driver's phone number or identity.
        if driver and driver.has_fix and driver_ping_is_fresh(driver) and assignment.status in {'picked_up', 'in_transit'}:
            payload['driver'] = {
                'lat': driver.last_lat,
                'lng': driver.last_lng,
                'vehicle_type': driver.vehicle_type,
                'last_ping_at': driver.last_ping_at.isoformat() if driver.last_ping_at else None,
            }
    return jsonify(payload)


# --- Phase Two Marketplace Operations ---

def seller_hub_view():
    """The landing page a verified seller gets in place of the KYC form.

    Shows what they can do next rather than re-asking for documents: their
    storefront state, their live listings, and the shortcuts to sell.
    """
    storefront = seller_storefront(current_user)
    pending_storefront = None
    if not storefront:
        pending_storefront = BusinessStorefront.query.filter_by(
            owner_id=current_user.id
        ).order_by(BusinessStorefront.created_at.desc()).first()

    products = Product.query.filter_by(seller_id=current_user.id).order_by(
        Product.created_at.desc()).limit(12).all()
    total_products = Product.query.filter_by(seller_id=current_user.id).count()
    live_products = Product.query.filter_by(
        seller_id=current_user.id, is_active=True, review_status='approved').count()
    pending_review = Product.query.filter(
        Product.seller_id == current_user.id,
        Product.review_status != 'approved').count()

    return render_template(
        'seller_hub.html',
        storefront=storefront,
        pending_storefront=pending_storefront,
        products=products,
        stats={
            'total': total_products,
            'live': live_products,
            'pending_review': pending_review,
        },
    )


@app.route('/seller/apply', methods=['GET', 'POST'])
@login_required
def seller_apply():
    if Setting.get('seller_signup_enabled', '0') != '1':
        flash(SELLER_SOON_MESSAGE, 'info')
        return redirect(url_for('home'))

    if current_user.is_admin:
        flash('Admins are already approved platform operators.', 'info')
        return redirect(url_for('admin_dashboard'))

    # Verification is a one-time gate. Once it is passed the page becomes the
    # seller's listing hub, so approved sellers never see the KYC form again.
    if user_can_sell(current_user):
        return seller_hub_view()

    latest = SellerVerification.query.filter_by(user_id=current_user.id).order_by(SellerVerification.created_at.desc()).first()
    kyc_provider = selected_kyc_provider()
    if request.method == 'POST':
        if kyc_provider == 'didit':
            flash('Start the secure verification session to continue seller approval.', 'info')
            return redirect(url_for('seller_apply'))
        legal_name = request.form.get('legal_name', '').strip()
        country = request.form.get('country', '').strip()
        phone = request.form.get('phone', current_user.phone or '').strip()
        document_type = request.form.get('document_type', 'id')
        bank_card_last4 = request.form.get('bank_card_last4', '').strip()[-4:]
        liveness_passed = request.form.get('liveness_passed') == '1'
        phone = normalize_mpesa_phone(phone)
        account_name = f'{current_user.first_name or ""} {current_user.last_name or ""}'.strip()
        if account_name and legal_name.lower() != account_name.lower():
            flash('Legal names must match the registered account names exactly before KYC can proceed.', 'danger')
            return redirect(url_for('seller_apply'))
        if not liveness_passed:
            flash('Complete the guided face liveness capture before submitting.', 'danger')
            return redirect(url_for('seller_apply'))

        blacklist_match = matching_seller_blacklist(legal_name, country, phone, bank_card_last4)
        if blacklist_match:
            if request.form.get('action') == 'appeal':
                blacklist_match.status = 'appeal_pending'
                blacklist_match.appeal_message = request.form.get('appeal_message', '').strip()
                db.session.commit()
                flash('Your appeal has been submitted for MVP review.', 'warning')
            else:
                flash('You cannot become a seller on this platform due to security reasons unless an appeal is submitted and approved.', 'danger')
            return render_template('seller_apply.html', verification=latest, kyc_policy=own_kyc_security_policy(),
                                   kyc_provider=kyc_provider, didit_status=didit_config_status(),
                                   blocked_blacklist=blacklist_match)

        document_path = ''
        selfie_path = ''
        document_capture = request.form.get('document_capture', '')
        selfie_capture = request.form.get('selfie_capture', '')
        if document_capture:
            document_path = save_capture_data(document_capture, 'seller_docs')
        elif 'document_file' in request.files and request.files['document_file'].filename:
            document_path = save_uploaded_file(request.files['document_file'], 'seller_docs')
        if selfie_capture:
            selfie_path = save_capture_data(selfie_capture, 'seller_docs')
        elif 'selfie_file' in request.files and request.files['selfie_file'].filename:
            selfie_path = save_uploaded_file(request.files['selfie_file'], 'seller_docs')

        document_fingerprint = file_content_fingerprint(document_path)
        if document_fingerprint:
            existing_kyc = KYCIdentityVerification.query.filter(
                KYCIdentityVerification.document_fingerprint == document_fingerprint,
                KYCIdentityVerification.user_id != current_user.id
            ).first()
            existing_seller_doc = SellerVerification.query.filter(
                SellerVerification.document_fingerprint == document_fingerprint,
                SellerVerification.user_id != current_user.id
            ).first()
            if existing_kyc or existing_seller_doc:
                flash('This verification document is already linked to another account.', 'danger')
                return redirect(url_for('seller_apply'))

        status, score, notes = auto_verify_seller_payload(
            legal_name, country, phone,
            'capture.jpg' if document_capture else (request.files.get('document_file').filename if request.files.get('document_file') else ''),
            'capture.jpg' if selfie_capture else (request.files.get('selfie_file').filename if request.files.get('selfie_file') else ''),
            bank_card_last4
        )

        # Real face verification using OpenCV
        doc_path_on_disk = uploaded_static_url_to_path(document_path)
        selfie_path_on_disk = uploaded_static_url_to_path(selfie_path)
        face_match_score = score
        face_verified = False
        if doc_path_on_disk and selfie_path_on_disk and os.path.isfile(doc_path_on_disk) and os.path.isfile(selfie_path_on_disk):
            face_result = verify_kyc_faces(doc_path_on_disk, selfie_path_on_disk)
            doc_quality = verify_document_quality(doc_path_on_disk)
            face_match_score = face_result.get('face_match_score', 0)
            face_verified = face_result.get('verified', False)
            liveness_score = doc_quality.get('quality_score', 0)
            # Override status: require face verification for approval
            if face_verified and face_match_score >= 60 and score >= 80:
                status = 'approved'
            elif face_match_score < 30:
                status = 'manual_review'
            notes += f' Face match: {face_match_score}%, Doc quality: {liveness_score}%.'
        else:
            liveness_score = score

        system_status = status
        if system_status == 'approved' and not kyc_system_only_enabled():
            status = 'manual_review'
            notes += ' System checks passed, but manual admin review is required before seller approval.'

        verification = SellerVerification(
            user_id=current_user.id,
            document_type=document_type,
            document_path=document_path,
            selfie_path=selfie_path,
            legal_name=legal_name,
            country=country,
            phone=phone,
            bank_card_last4=bank_card_last4,
            document_fingerprint=document_fingerprint,
            status=status,
            automated_score=score,
            notes=notes
        )
        if document_fingerprint:
            db.session.add(KYCIdentityVerification(
                user_id=current_user.id,
                provider=selected_kyc_provider(),
                document_type=document_type,
                document_country=country,
                document_fingerprint=document_fingerprint,
                document_path=document_path,
                selfie_path=selfie_path,
                face_match_score=face_match_score,
                liveness_score=liveness_score,
                captcha_passed=True,
                status=status,
                notes=notes,
            ))
        current_user.country = country
        current_user.phone = phone
        current_user.bank_card_last4 = bank_card_last4
        current_user.verification_status = status
        current_user.verification_notes = notes
        current_user.seller_status = 'verified' if status == 'approved' else 'pending'
        current_user.is_verified_seller = status == 'approved'
        if current_user.is_verified_seller:
            current_user.verified_seller_at = utcnow()
        db.session.add(verification)
        db.session.commit()
        flash('Seller application submitted. Approved applications can list products; manual reviews remain pending.', 'success')
        return redirect(url_for('seller_apply'))

    return render_template('seller_apply.html', verification=latest, kyc_policy=own_kyc_security_policy(),
                           kyc_provider=kyc_provider, didit_status=didit_config_status())


@app.route('/seller/verification/start', methods=['POST'])
@login_required
def seller_verification_start():
    return start_hosted_seller_verification()


@app.route('/seller/kyc/didit/start', methods=['POST'])
@login_required
def seller_didit_start():
    return start_hosted_seller_verification()


def start_hosted_seller_verification():
    wants_json = wants_json_response()
    if Setting.get('seller_signup_enabled', '0') != '1':
        if wants_json:
            return jsonify({'success': False, 'error': SELLER_SOON_MESSAGE}), 403
        flash(SELLER_SOON_MESSAGE, 'info')
        return redirect(url_for('home'))
    if current_user.is_admin:
        if wants_json:
            return jsonify({'success': False, 'error': 'Admins are already approved platform operators.'}), 403
        flash('Admins are already approved platform operators.', 'info')
        return redirect(url_for('admin_dashboard'))
    if not didit_enabled():
        if wants_json:
            return jsonify({'success': False, 'error': 'Hosted seller verification is not enabled in settings.'}), 400
        flash('Hosted seller verification is not enabled in settings.', 'warning')
        return redirect(url_for('seller_apply'))
    status = didit_config_status()
    if not status['ready']:
        if wants_json:
            return jsonify({'success': False, 'error': 'Seller verification is not fully configured yet. Please try again shortly.'}), 503
        flash('Seller verification is not fully configured yet. Please try again shortly.', 'danger')
        return redirect(url_for('seller_apply'))
    try:
        session_data = create_didit_session_for_user(current_user)
        if wants_json:
            return jsonify({'success': True, 'url': session_data['url']})
        return redirect(session_data['url'])
    except requests.Timeout as exc:
        logger.error('Timed out creating Didit KYC session: %s', exc, exc_info=True)
        message = 'Verification is taking too long to open. Please try again.'
        if wants_json:
            return jsonify({'success': False, 'error': message}), 504
        flash(message, 'danger')
        return redirect(url_for('seller_apply'))
    except requests.HTTPError as exc:
        response_text = exc.response.text[:500] if exc.response is not None else ''
        logger.error('Could not create Didit KYC session: %s %s', exc, response_text, exc_info=True)
        message = 'Could not start seller verification right now. Please try again shortly.'
        if wants_json:
            return jsonify({'success': False, 'error': message}), 502
        flash(message, 'danger')
        return redirect(url_for('seller_apply'))
    except Exception as exc:
        logger.error('Could not create Didit KYC session: %s', exc, exc_info=True)
        if wants_json:
            return jsonify({'success': False, 'error': 'Could not start seller verification right now. Please try again shortly.'}), 500
        flash('Could not start seller verification right now. Please try again shortly.', 'danger')
        return redirect(url_for('seller_apply'))


@app.route('/api/kyc/didit/webhook', methods=['POST'])
@app.route('/webhooks/didit', methods=['POST'])
@csrf.exempt
def didit_webhook():
    payload = request.get_json(silent=True) or {}
    if not isinstance(payload, dict) or not didit_signature_is_valid(payload):
        logger.warning('Rejected Didit webhook with invalid signature or payload.')
        return jsonify({'error': 'invalid signature'}), 401

    event_id = str(payload.get('event_id') or payload.get('id') or '').strip()
    if event_id:
        # Replay guard. Held in the ephemeral store rather than the settings
        # table: providers retry within minutes, so a month is generous, and one
        # permanent settings row per webhook event grows forever.
        dedupe_key = f'didit_event_{event_id}'
        if ephemeral_get(dedupe_key):
            return jsonify({'status': 'ok'})

    applied = apply_didit_status(payload)
    if event_id:
        ephemeral_set(dedupe_key, utcnow().isoformat(),
                      ttl_seconds=WEBHOOK_DEDUPE_TTL_SECONDS)
    return jsonify({'status': 'ok', 'applied': applied})


@app.route('/claims/new/<int:order_id>', methods=['GET', 'POST'])
@login_required
def file_claim(order_id):
    order = Order.query.get_or_404(order_id)
    if order.user_id != current_user.id and not current_user.is_admin:
        abort(403)
    if request.method == 'POST':
        reason = request.form.get('reason', 'not_delivered')
        details = request.form.get('details', '').strip()
        claim = PaymentClaim(
            order_id=order.id,
            claimant_id=current_user.id,
            reason=reason,
            details=details,
            amount=order.amount_paid,
            status='open',
            refund_due_at=utcnow() + timedelta(days=7)
        )
        order.protection_status = 'disputed'
        db.session.add(claim)
        db.session.commit()
        flash('Claim filed. Refund review target is 3-7 business days, depending on case details.', 'success')
        return redirect(url_for('orders'))
    return render_template('claim_form.html', order=order)


SELLER_PRODUCT_CONDITIONS = ['new', 'second_hand', 'refurbished', 'thrifted']

# Second-hand phone ownership evidence.
#
# A second-hand handset is the one listing where "is this yours to sell" is a real
# question, and parking every one of them in a human queue does not scale - which is
# the whole point of this. So the checks below are arithmetic and image measurement,
# and they run without anybody looking.
#
# What this can and cannot do, stated plainly because the seller-facing copy has to
# say the same thing: there is no OCR installed, so nothing here reads the text on a
# receipt. It verifies that the IMEI is well formed, that it is not already on the
# platform, that the two photos are real photographs of adequate quality, that they
# are recent, and that they have not been used on another account. That is a strong
# filter against the cheap frauds - typed-in numbers, one receipt reused across six
# listings, a screenshot lifted from a marketplace - and it is not a guarantee that
# the receipt says what the seller claims.
#
# Both env vars have working defaults, so none of this needs configuring.
PHONE_EVIDENCE_MIN_SCORE = float_env('PHONE_EVIDENCE_MIN_SCORE', 70)
PHONE_EVIDENCE_REQUIRED = bool_env('PHONE_EVIDENCE_REQUIRED', True)
PHONE_EVIDENCE_RATE_LIMIT = os.environ.get('PHONE_EVIDENCE_RATE_LIMIT', '60 per hour')

# Conditions where the handset has had a previous owner. 'refurbished' is in here
# too: a refurbished phone came from somewhere, and that somewhere is the question.
PHONE_EVIDENCE_CONDITIONS = ('second_hand', 'refurbished')

# Local disk, deliberately. Deliberately NOT added to CLOUDINARY_PUBLIC_FOLDERS:
# a purchase receipt carries a name, a phone number and often a card tail, which
# makes this identity-adjacent material that must not sit on a permanently public
# URL. It follows seller_docs and kyc, which stay local for the same reason - and
# the image measurement below reads these back off disk with PIL and OpenCV, so
# they have to be local anyway.
PHONE_EVIDENCE_FOLDER = 'phone_docs'


def save_phone_evidence_upload(file):
    """Store one evidence photo on local disk, or '' if there was nothing to store.

    Wrapped rather than called directly so a rejected file becomes an empty result
    that the scoring reports as a missing item, instead of a 500 on a form the
    seller is in the middle of.
    """
    if not file or not file.filename:
        return ''
    try:
        return save_uploaded_file(file, PHONE_EVIDENCE_FOLDER)
    except (ValueError, OSError) as exc:
        app.logger.info('Phone evidence upload rejected: %s', exc)
        return ''


def phone_evidence_required(product, category=None):
    """Does this listing need ownership evidence before it can go live?"""
    if not PHONE_EVIDENCE_REQUIRED:
        return False
    if getattr(product, 'is_digital', False):
        return False
    if (product.product_condition or 'new') not in PHONE_EVIDENCE_CONDITIONS:
        return False
    if category is None and product.category_id:
        category = db.session.get(Category, product.category_id)
    return is_phone_listing(product.name, category)


def phone_listing_gate(user):
    """Return None if ``user`` may list a second-hand phone, else a reason.

    Two things beyond the ordinary storefront gate, because a stolen handset is the
    one item on the platform where the seller's identity is the evidence: an
    approved storefront, and completed KYC so there is a real person behind it.

    Admins are exempt entirely. They post platform stock whose history they already
    know, and there is nobody above them to appeal a rejection to.
    """
    if getattr(user, 'is_admin', False):
        return None
    if not seller_storefront(user):
        return ('Second-hand phones need an approved storefront. '
                'Apply for one and this opens up.')
    kyc = (KYCIdentityVerification.query
           .filter(KYCIdentityVerification.user_id == user.id,
                   KYCIdentityVerification.status == 'approved')
           .first())
    if not kyc:
        return ('Second-hand phones need your identity verified first. '
                'Complete ID verification and this opens up.')
    return None


def evidence_image_measure(image_url):
    """Measure one evidence photo. Returns (score 0-100, reasons, legible).

    Resolution and aspect follow verify_document_quality's bands. The blur check is
    Laplacian variance, which is the standard cheap answer to "is this in focus":
    a sharp photo has strong second derivatives, a blurred or re-photographed
    screen does not. Threshold is deliberately forgiving - a mid-range phone camera
    in a dim room still passes.

    ``legible`` answers the separate question of whether the photo can be read at
    all, and it is deliberately not inferred from the score. Each band below measures
    one property independently, so a photo far too small to read still collects the
    aspect and sharpness points and lands mid-range - a number that cannot be
    compared against a threshold to mean "readable".
    """
    path = uploaded_static_url_to_path(image_url)
    if not path or not os.path.exists(path):
        return 0, ['Photo did not arrive.'], False

    score, reasons, legible = 0, [], True
    try:
        from PIL import Image
        with Image.open(path) as img:
            width, height = img.size
    except Exception as exc:
        app.logger.info('Phone evidence image unreadable: %s', exc)
        return 0, ['That file is not a readable photo.'], False

    if width >= 640 and height >= 480:
        score += 55
    elif width >= 320 and height >= 240:
        score += 25
        reasons.append('Photo is low resolution - move closer and retake it.')
    else:
        reasons.append('Photo is too small to read. Retake it closer up.')
        legible = False

    aspect = max(width, height) / max(min(width, height), 1)
    if aspect <= 3.0:
        score += 15
    else:
        reasons.append('Photo is cropped too narrow to show the whole thing.')
        legible = False

    try:
        import cv2
        cv_img = cv2.imread(path)
        if cv_img is None:
            raise ValueError('cv2 could not decode the file')
        gray = cv2.cvtColor(cv_img, cv2.COLOR_BGR2GRAY)
        sharpness = float(cv2.Laplacian(gray, cv2.CV_64F).var())
        if sharpness >= 60:
            score += 30
        elif sharpness >= 25:
            score += 15
            reasons.append('Photo is slightly soft - hold steady and retake it.')
        else:
            reasons.append('Photo is too blurred to read.')
            legible = False
    except Exception as exc:
        # A missing or unhappy OpenCV must not fail an honest seller. Partial
        # credit, and the resolution check above still did real work.
        app.logger.info('Phone evidence sharpness check skipped: %s', exc)
        score += 15

    return min(score, 100), reasons, legible


def evidence_image_freshness(image_url, max_age_days=180):
    """Was this photographed recently, and by a camera?

    EXIF is the signal here. A photo straight off a phone camera carries a capture
    timestamp; a screenshot, a web download or a scan generally does not. Absent
    EXIF is not treated as a failure - browser camera capture strips it, and that
    is the flow this platform recommends - it just earns less than a fresh
    timestamp does.
    """
    path = uploaded_static_url_to_path(image_url)
    if not path or not os.path.exists(path):
        return 0.0, ['Photo did not arrive.']
    try:
        from PIL import Image
        with Image.open(path) as img:
            exif = img.getexif() or {}
        # 36867 DateTimeOriginal, 306 DateTime.
        stamp = exif.get(36867) or exif.get(306)
    except Exception:
        stamp = None

    if not stamp:
        # No timestamp to judge, so fall back to when it landed on disk. Half
        # credit: it says the upload is fresh, not that the photo is.
        return 0.5, []
    try:
        taken = datetime.strptime(str(stamp).strip(), '%Y:%m:%d %H:%M:%S')
    except (ValueError, TypeError):
        return 0.5, []
    age_days = (datetime.utcnow() - taken).days
    if age_days < -1:
        return 0.0, ['Photo is dated in the future - check the phone\'s clock.']
    if age_days <= max_age_days:
        return 1.0, []
    return 0.25, ['Photo was taken a long time ago. A recent one is stronger evidence.']


def imei_hard_conflicts(imei, user, product_id=None):
    """Reasons this IMEI cannot be listed at all. Empty list means it is clear.

    Every one of these is an immediate reject rather than a score deduction,
    because none of them get better with a nicer photograph.
    """
    reasons = []
    user_id = getattr(user, 'id', None)

    # Already on somebody's live listing. Scoped to active listings on purpose:
    # relisting your own phone after the first one lapsed is legitimate.
    clash = (db.session.query(PhoneOwnershipEvidence.id, PhoneOwnershipEvidence.user_id)
             .join(Product, Product.id == PhoneOwnershipEvidence.product_id)
             .filter(PhoneOwnershipEvidence.imei == imei,
                     PhoneOwnershipEvidence.status.in_(('approved', 'manual_second_review')),
                     Product.is_active.is_(True))
             .filter(Product.id != (product_id or 0))
             .first())
    if clash:
        reasons.append('This IMEI is already on an active listing.'
                       if clash.user_id == user_id else
                       'This IMEI is already listed by another account.')

    # Still being financed on the platform's own BNPL. Free anti-fraud: the
    # platform is the lienholder, so it does not need to ask anybody. A completed
    # plan is paid off and the handset is the buyer's to sell.
    financed = (db.session.query(BNPLPlan.id)
                .filter(BNPLPlan.device_imei == imei,
                        BNPLPlan.approval_status.in_(('approved', 'manual_review')))
                .first())
    if financed:
        reasons.append('This handset is still on an active BNPL plan and cannot be resold yet.')

    # The seller themselves is barred. Matched on identity rather than account id,
    # because that is what the blacklist stores - a barred seller opening a second
    # account still matches on name-and-country, phone, or card.
    if user is not None:
        legal_name = (f'{getattr(user, "first_name", "") or ""} '
                      f'{getattr(user, "last_name", "") or ""}'.strip()
                      or getattr(user, 'username', ''))
        if matching_seller_blacklist(legal_name, getattr(user, 'country', None),
                                     getattr(user, 'phone', None),
                                     getattr(user, 'bank_card_last4', None)):
            reasons.append('This account is not permitted to list second-hand devices.')

    return reasons


def score_phone_evidence(imei, imei_photo_url, proof_url, user, product_id=None):
    """Score one evidence submission out of 100. Returns a dict, commits nothing.

    Weighted so an honest seller who supplies exactly the two required items -
    the IMEI with a photo of it on screen, and a photo of purchase proof - clears
    the threshold, while a submission missing either one cannot.
    """
    imei = normalize_imei(imei)
    result = {
        'imei': imei, 'imei_valid': False, 'uniqueness_ok': False,
        'photo_score': 0.0, 'proof_score': 0.0, 'originality_score': 0.0,
        'total_score': 0.0, 'hard_fail': False, 'reasons': [],
        'proof_fingerprint': '',
    }

    # Hard fails first. No score is computed for any of these: a reject with a
    # number attached invites haggling over the number.
    if not imei:
        result.update(hard_fail=True, reasons=['Enter the handset\'s IMEI. Dial *#06# on the phone to see it.'])
        return result
    if not imei_checksum_valid(imei):
        result.update(hard_fail=True, reasons=[
            'That IMEI is not valid. It is 15 digits - dial *#06# on the handset and copy it exactly.'])
        return result
    if not imei_photo_url:
        result.update(hard_fail=True, reasons=['Add a photo of the IMEI showing on the phone\'s screen.'])
        return result
    if not proof_url:
        result.update(hard_fail=True, reasons=[
            'Add proof of purchase: the receipt, the box IMEI label, or the original M-Pesa message.'])
        return result

    conflicts = imei_hard_conflicts(imei, user, product_id)
    if conflicts:
        result.update(hard_fail=True, reasons=conflicts)
        return result

    # Evidence reused across accounts. Same precedent as the KYC document
    # fingerprint check: one receipt, six listings.
    fingerprint = file_content_fingerprint(proof_url)
    result['proof_fingerprint'] = fingerprint
    if fingerprint:
        reused = (db.session.query(PhoneOwnershipEvidence.id, PhoneOwnershipEvidence.user_id)
                  .filter(PhoneOwnershipEvidence.proof_fingerprint == fingerprint,
                          PhoneOwnershipEvidence.product_id != (product_id or 0))
                  .first())
        if reused:
            # The fingerprint is cleared rather than carried. The column means "this is
            # the attempt that claimed this image", and this attempt did not - the row
            # it collides with holds the claim. Storing it here trips the unique
            # constraint, so what should be a clean "already used elsewhere" rejection
            # arrives as an IntegrityError instead, which the route can only answer
            # with a misleading flash and no evidence row written at all: the record of
            # precisely the attempt most worth keeping is the one thing lost.
            result.update(hard_fail=True, proof_fingerprint='', reasons=[
                'This exact proof image has already been used for another listing.'
                if reused.user_id == getattr(user, 'id', None) else
                'This proof image is already linked to another account.'])
            return result
        # This listing already registered this image on an earlier attempt, so the
        # claim exists and stays unique platform-wide. Carrying it onto a second row
        # would collide with the listing's own history and turn the resubmission
        # after a rejection - the thing this flow promises is always available - into
        # an integrity error on commit.
        claimed = (db.session.query(PhoneOwnershipEvidence.id)
                   .filter(PhoneOwnershipEvidence.proof_fingerprint == fingerprint,
                           PhoneOwnershipEvidence.product_id == (product_id or 0))
                   .first())
        if claimed:
            result['proof_fingerprint'] = ''

    result['imei_valid'] = True
    result['uniqueness_ok'] = True
    total = 25.0 + 20.0  # valid IMEI, unique IMEI

    photo_measure, photo_reasons, photo_legible = evidence_image_measure(imei_photo_url)
    result['photo_score'] = round(25.0 * photo_measure / 100, 2)
    total += result['photo_score']
    result['reasons'].extend(f'IMEI photo: {reason}' for reason in photo_reasons)

    proof_measure, proof_reasons, proof_legible = evidence_image_measure(proof_url)
    result['proof_score'] = round(20.0 * proof_measure / 100, 2)
    total += result['proof_score']
    result['reasons'].extend(f'Purchase proof: {reason}' for reason in proof_reasons)

    # A required photo nobody can read is materially a missing one: the platform
    # cannot tell whether it shows what the seller says it shows, which is the whole
    # question being asked. So it is a refusal, not a deduction - and it has to be,
    # because the weights cannot express it. A flawless submission that forfeits every
    # one of the 20 proof points still totals 80, a comfortable pass, so no threshold
    # on this score could ever require both photos to be readable.
    #
    # Placed after both measures so a seller who got both wrong is told both at once,
    # rather than fixing one and only then discovering the other. Scores zeroed to
    # match the hard fails above: the named reasons are the useful diagnostic here,
    # and a refusal carrying a two-thirds-of-the-way number invites an argument about
    # the number instead of a retake.
    if not photo_legible or not proof_legible:
        result.update(hard_fail=True, photo_score=0.0, proof_score=0.0)
        return result

    imei_fresh, imei_fresh_reasons = evidence_image_freshness(imei_photo_url)
    proof_fresh, _ = evidence_image_freshness(proof_url)
    # Proof of purchase is legitimately old - a receipt from two years ago is
    # still the receipt - so only the IMEI photo is judged on age, and the proof
    # contributes just by being a readable photograph.
    result['originality_score'] = round(10.0 * (0.7 * imei_fresh + 0.3 * min(proof_fresh + 0.5, 1.0)), 2)
    total += result['originality_score']
    result['reasons'].extend(f'IMEI photo: {reason}' for reason in imei_fresh_reasons)

    result['total_score'] = round(total, 2)
    return result


def seller_has_prior_phone_listing(user_id):
    """Has this seller had a phone listing verified before?

    The first one always gets a human look regardless of score - the automated
    checks measure the evidence, not the seller, and a first-time phone seller is
    exactly where the platform has learned nothing yet.
    """
    return db.session.query(
        db.session.query(PhoneOwnershipEvidence.id)
        .filter(PhoneOwnershipEvidence.user_id == user_id,
                PhoneOwnershipEvidence.status.in_(('approved', 'manual_second_review')))
        .exists()
    ).scalar()


def record_phone_evidence(product, imei, imei_photo_url, proof_url, as_admin=False):
    """Score a submission, store it, and set the listing's review status.

    Returns the PhoneOwnershipEvidence row. Adds to the session but does not
    commit - the caller owns the transaction, so a listing and its verdict land
    together or not at all.
    """
    if as_admin:
        # An admin listing platform stock they already know the history of. Recorded
        # anyway, so the IMEI is still registered against the listing and the next
        # person to submit that number hits the duplicate check.
        evidence = PhoneOwnershipEvidence(
            product_id=product.id, user_id=current_user.id,
            imei=normalize_imei(imei), imei_photo_path=imei_photo_url or None,
            proof_path=proof_url or None,
            imei_valid=imei_checksum_valid(imei), uniqueness_ok=True,
            total_score=100.0, status='approved',
            notes=json.dumps(['Listed by an admin - device history already known.']),
            reviewed_by=current_user.id, reviewed_at=utcnow())
        product.review_status = 'approved'
        db.session.add(evidence)
        return evidence

    scored = score_phone_evidence(imei, imei_photo_url, proof_url,
                                  current_user, product_id=product.id)

    if scored['hard_fail']:
        status = 'auto_rejected'
    elif not seller_has_prior_phone_listing(current_user.id):
        # First phone from this seller. Their evidence may be perfect; one human
        # look is the price of the first one.
        status = 'manual_second_review'
        scored['reasons'].insert(0, 'First phone listing on this account - a person will confirm it.')
    elif scored['total_score'] >= PHONE_EVIDENCE_MIN_SCORE:
        status = 'approved'
    else:
        status = 'auto_rejected'
        scored['reasons'].insert(0, 'The evidence supplied was not strong enough to verify ownership '
                                    'automatically. Fix the items below and submit again.')

    evidence = PhoneOwnershipEvidence(
        product_id=product.id, user_id=current_user.id, imei=scored['imei'],
        imei_photo_path=imei_photo_url or None, proof_path=proof_url or None,
        proof_fingerprint=scored['proof_fingerprint'] or None,
        imei_valid=scored['imei_valid'], uniqueness_ok=scored['uniqueness_ok'],
        photo_score=scored['photo_score'], proof_score=scored['proof_score'],
        originality_score=scored['originality_score'],
        total_score=scored['total_score'], status=status,
        notes=json.dumps(scored['reasons']) if scored['reasons'] else None)
    db.session.add(evidence)

    product.review_status = status
    # Passing publishes. The listing was parked with is_active=False when it was
    # created, so carrying that flag forward would leave a verified phone invisible
    # and waiting on a toggle the seller has no reason to look for - which is the
    # manual step this whole flow exists to remove. Anything short of approved
    # stays down.
    product.is_active = status == 'approved'
    return evidence


def latest_phone_evidence(product_id):
    """The submission that decides a listing: its newest one."""
    return (PhoneOwnershipEvidence.query
            .filter(PhoneOwnershipEvidence.product_id == product_id)
            .order_by(PhoneOwnershipEvidence.created_at.desc(),
                      PhoneOwnershipEvidence.id.desc())
            .first())


def seller_listing_gate():
    """Return (storefront, redirect) for the seller listing pages.

    Listing is the reward for a verified storefront, so an approved storefront
    is the gate. Sellers stuck earlier in the funnel get sent to the step they
    actually need next rather than a bare 403.
    """
    storefront = seller_storefront(current_user)
    if storefront:
        return storefront, None
    if not user_can_sell(current_user):
        flash('Complete seller verification first, then apply for a storefront.', 'warning')
        return None, redirect(url_for('seller_apply'))
    pending = BusinessStorefront.query.filter_by(owner_id=current_user.id).first()
    if pending:
        flash('Your storefront is still under review. Product listing opens as soon as it is approved.', 'info')
    else:
        flash('Apply for a storefront to start listing products.', 'warning')
    return None, redirect(url_for('storefront_apply'))


def save_seller_product(product, storefront, is_new):
    """Read the listing form onto a product. Returns an error string or None."""
    name = request.form.get('name', '').strip()
    selling_price = form_float('selling_price', 0, minimum=0)
    buying_price = form_float('buying_price', 0, minimum=0)
    if not name:
        return 'Product name is required.'
    if selling_price <= 0:
        return 'Set a selling price above zero.'

    condition = request.form.get('product_condition', 'new')
    if condition not in SELLER_PRODUCT_CONDITIONS:
        condition = 'new'

    if is_new or name != product.name:
        product.slug = unique_product_slug(name, current_id=product.id)
    product.name = name
    product.description = request.form.get('description', '').strip() or name
    product.short_description = request.form.get('short_description', '').strip()[:300]
    product.category_id = request.form.get('category_id', type=int)
    product.buying_price = buying_price
    product.selling_price = selling_price
    product.discount_percent = form_float('discount_percent', 0, minimum=0, maximum=99)
    product.stock = form_int('stock', 0, minimum=0)
    product.weight_kg = form_float('weight_kg', 0, minimum=0)
    product.product_condition = condition
    product.is_active = request.form.get('is_active') in ['1', 'on', 'true']
    product.seller_id = current_user.id

    # Second-hand and thrifted goods still need a human to look at them; new
    # stock from a verified storefront goes live immediately.
    #
    # Second-hand phones are the exception, and the reason this branch is no longer
    # the last word: they route to the evidence flow below instead of a queue. The
    # status set here is the holding one, replaced by record_phone_evidence's verdict
    # once the seller has submitted the IMEI and the two photos.
    if condition in ['second_hand', 'refurbished']:
        product.review_status = 'manual_second_review'
        product.is_active = False
    elif condition == 'thrifted':
        product.review_status = 'admin_review'
    else:
        product.review_status = 'approved'

    if phone_evidence_required(product):
        blocked = phone_listing_gate(current_user)
        if blocked:
            return blocked
        # An edit to a listing whose evidence already passed keeps its verdict.
        # Re-verifying on every price change would send an approved phone back to
        # the start for no new reason, and product.id is None on a new listing so
        # there is nothing to look up there anyway.
        settled = latest_phone_evidence(product.id) if product.id else None
        if settled and settled.status == 'approved':
            product.review_status = 'approved'
        else:
            product.review_status = 'pending_evidence'
            product.is_active = False

    images = uploaded_product_images()
    if images:
        product.image_url = images[0]
        if len(images) > 1:
            product.additional_images = json.dumps(images[1:])
    elif request.form.get('image_url', '').strip():
        product.image_url = request.form.get('image_url', '').strip()

    apply_product_location(
        product,
        storefront=storefront,
        label=request.form.get('location_label', ''),
        lat=request.form.get('location_lat', type=float),
        lng=request.form.get('location_lng', type=float),
    )

    # Kenya is filtered out inside the parser, so a tampered form still cannot
    # block a domestic county.
    product.excluded_countries = serialize_excluded_countries(
        request.form.getlist('excluded_countries'))

    # Sellers may absorb the delivery charge on a listing; everything else is
    # priced automatically from the origin above.
    product.free_delivery = bool(request.form.get('free_delivery'))

    # Done last so it overrides the physical defaults set above: a digital listing
    # has nothing to weigh, no stock to run out of and no condition to grade.
    if form_bool('is_digital'):
        failure = attach_digital_file(product, request.files.get('digital_file'),
                                      required=not product.file_path)
        if failure:
            return failure
        apply_digital_defaults(product)
    else:
        product.is_digital = False
    return None


# Bulk digital listing. A tutor with two hundred exam papers should not fill the
# single-product form two hundred times, but the whole selection cannot arrive in
# one request either: MAX_CONTENT_LENGTH caps the entire body at 30MB, and a sync
# worker held for minutes by one enormous upload is the exact stall the rest of
# this work is removing. So the browser slices the selection into small posts and
# this endpoint answers each one with a per-file verdict.
#
# Every limit is an env var with a working default, so none of this needs
# configuring to run.
BULK_DIGITAL_MAX_FILES = int_env('BULK_DIGITAL_MAX_FILES_PER_REQUEST', 8)
BULK_DIGITAL_MAX_FILE_MB = float_env('BULK_DIGITAL_MAX_FILE_MB', 20)
BULK_DIGITAL_RATE_LIMIT = os.environ.get('BULK_DIGITAL_RATE_LIMIT', '120 per hour')

# Academic material is the obvious use for this, and it is also the material most
# likely to be somebody else's copyright, so bulk listings park for review by
# default. Set BULK_DIGITAL_REVIEW=0 to publish them straight away.
DIGITAL_REVIEW_REQUIRED = bool_env('BULK_DIGITAL_REVIEW', True)


def bulk_digital_request_budget():
    """Bytes the browser may put in one batch, kept clear of the hard body cap.

    Flask rejects an oversized body before any view runs, so a batch that guesses
    wrong is a 413 with no per-file detail - useless feedback for someone halfway
    through a hundred files. The browser packs to this figure instead, and the 2MB
    of headroom covers the form fields and multipart boundaries riding along.
    """
    hard_cap = int(app.config.get('MAX_CONTENT_LENGTH') or (30 * 1024 * 1024))
    headroom = 2 * 1024 * 1024
    asked = int(float_env('BULK_DIGITAL_REQUEST_BUDGET_MB', 24) * 1024 * 1024)
    return max(1024 * 1024, min(asked, hard_cap - headroom))


def bulk_digital_max_file_bytes():
    """Per-file ceiling. Never above the batch budget, or nothing could be sent."""
    return int(min(BULK_DIGITAL_MAX_FILE_MB * 1024 * 1024, bulk_digital_request_budget()))


def uploaded_file_size(file):
    """Bytes in an upload, measured off the stream and rewound for the next reader."""
    try:
        stream = file.stream
        stream.seek(0, os.SEEK_END)
        size = stream.tell()
        stream.seek(0)
        return int(size)
    except (AttributeError, OSError, ValueError):
        return 0


def attach_digital_file(product, file, required=True):
    """Validate one upload and hang it off ``product``. Error string or None.

    The size is taken from the stream rather than stat-ing the file afterwards:
    the bytes are already in hand, and a stat would be a second answer to a
    question we have answered.
    """
    if not file or not file.filename:
        return 'Attach the file buyers will download.' if required else None
    size = uploaded_file_size(file)
    ceiling = bulk_digital_max_file_bytes()
    if size <= 0:
        return 'That file came through empty.'
    if size > ceiling:
        # Deliberately not quoting the file's own size back: at one decimal place a
        # file a kilobyte over the line prints the same figure as the line itself,
        # which reads as a contradiction.
        return f'Too large for one file. The limit is {human_file_size(ceiling)}.'
    if not allowed_digital_file(file.filename) or not allowed_digital_file_signature(file):
        return ('Allowed file types are '
                f'{", ".join(sorted(ALLOWED_DIGITAL_EXTENSIONS))}, '
                'and the contents have to match the extension.')
    try:
        product.file_path = save_uploaded_file(file, 'digital')
    except ValueError as exc:
        return str(exc)
    product.file_size = size
    return None


def apply_digital_defaults(product, skip_review=False):
    """Force the fields a digital listing cannot meaningfully carry.

    Left to the form these would hold whatever the physical inputs posted, and a
    downloadable file with a shipping weight and a stock count of zero reads as
    out of stock everywhere that checks.

    ``skip_review`` is for admin uploads. The review queue exists so somebody
    checks a seller's copyright claim before academic material goes on sale, and
    an admin holding their own upload for their own approval is a queue that
    reviews itself. It deliberately does not change the default for sellers.
    """
    product.is_digital = True
    product.product_condition = 'new'
    product.stock = 0
    product.weight_kg = 0.0
    product.free_delivery = True
    if DIGITAL_REVIEW_REQUIRED and not skip_review:
        product.review_status = 'admin_review'
        product.is_active = False
    return product


def human_file_size(size):
    size = float(size or 0)
    for unit in ('B', 'KB', 'MB', 'GB'):
        if size < 1024 or unit == 'GB':
            return f'{size:.0f} {unit}' if unit == 'B' else f'{size:.1f} {unit}'
        size /= 1024
    return f'{size:.1f} GB'


def digital_product_name(filename, fallback='Digital download'):
    """Turn a filename into something a shopper would read.

    'NUR-201_Final_Exam_2024 (1).pdf' becomes 'NUR 201 Final Exam 2024'. Existing
    capitalisation is kept, because course codes carry meaning that title-casing
    would flatten; an all-lowercase name gets capitalised since that is a filename
    convention rather than a choice.
    """
    stem = os.path.splitext(os.path.basename(filename or ''))[0]
    # splitext reads a leading-dot name as an extensionless dotfile, so a file
    # called ".pdf" would come back as the name "Pdf" rather than the fallback.
    if os.path.basename(filename or '').startswith('.'):
        stem = ''
    cleaned = re.sub(r'[\s_]+', ' ', stem.replace('-', ' '))
    cleaned = re.sub(r'\s*\(\d+\)\s*$', '', cleaned)  # the "(1)" a re-download picks up
    cleaned = re.sub(r'\s{2,}', ' ', cleaned).strip(' .')
    if not cleaned:
        return fallback
    if cleaned.islower():
        cleaned = cleaned.title()
    return cleaned[:200]


def read_bulk_digital_form(as_admin=False):
    """The fields shared by every file in the batch, read once.

    Returns (shared, error). These arrive on every request rather than being
    stashed server-side between batches: a session-held draft would be one more
    thing to expire, and the browser already has them.
    """
    price = form_float('selling_price', 0, minimum=0)
    if price <= 0:
        return None, 'Set a price above zero for the batch.'
    if not form_bool('owns_rights'):
        return None, 'Confirm you hold the rights to sell these files.'
    return {
        'category_id': request.form.get('category_id', type=int),
        'selling_price': price,
        'discount_percent': form_float('discount_percent', 0, minimum=0, maximum=99),
        'description': request.form.get('description', '').strip(),
        'short_description': request.form.get('short_description', '').strip()[:300],
        'name_prefix': request.form.get('name_prefix', '').strip()[:60],
        'is_active': form_bool('is_active'),
        'first_page_preview': form_bool('first_page_preview'),
        'cover_url': (request.form.get('cover_url', '').strip() or None),
        # Sellers are held to the standard rate; the admin form can set it within
        # the same band the single-product admin form allows.
        'commission_percent': (form_float('commission_percent', 15, minimum=10.0, maximum=15.0)
                               if as_admin else 15.0),
    }, None


def bulk_digital_location(storefront):
    """Resolve the storefront pin once for the whole batch.

    apply_product_location geocodes when there are no coordinates to work from.
    Called per file that is a network round trip per file, and eight of those in a
    request that is also writing eight files to disk is how a sync worker reaches
    its timeout. So it is resolved once here and the answer is reused; a storefront
    that still has no pin afterwards is left without one rather than retried eight
    times, which is also why the empty label matters - it is the other branch in
    apply_product_location that would reach for the geocoder.
    """
    # Admin uploads have no storefront at all. Platform stock ships from the
    # platform, so there is no pin to resolve and nothing to geocode.
    if storefront is None:
        return {'storefront': None, 'lat': None, 'lng': None}
    try:
        geocode_storefront(storefront)
    except Exception:
        app.logger.exception('Bulk digital geocode failed for storefront %s', storefront.id)
    if storefront.location_lat is None or storefront.location_lng is None:
        return {'storefront': None, 'lat': None, 'lng': None}
    return {'storefront': storefront,
            'lat': storefront.location_lat,
            'lng': storefront.location_lng}


def build_bulk_digital_product(file, shared, location, as_admin=False):
    """One uploaded file becomes one product. Returns (product, error)."""
    product = Product(seller_id=current_user.id,
                      commission_percent=shared.get('commission_percent', 15.0))
    failure = attach_digital_file(product, file, required=True)
    if failure:
        return None, failure

    label = digital_product_name(file.filename)
    name = f'{shared["name_prefix"]} {label}'.strip()[:200] if shared['name_prefix'] else label
    product.name = name
    product.slug = unique_product_slug(name)
    product.description = shared['description'] or name
    product.short_description = shared['short_description'] or label[:300]
    product.category_id = shared['category_id']
    product.selling_price = shared['selling_price']
    product.buying_price = 0.0
    product.discount_percent = shared['discount_percent']
    product.first_page_preview = shared['first_page_preview']
    product.is_active = shared['is_active']
    product.image_url = shared['cover_url']
    # Platform stock, listed by the same admin who would otherwise review it, so it
    # carries admin placement and skips the copyright queue.
    product.admin_priority = bool(as_admin)
    apply_digital_defaults(product, skip_review=as_admin)

    # A download ships from nowhere, but the pin is what tells a buyer whose shop
    # this is, so it follows the storefront like every other listing.
    apply_product_location(product, storefront=location['storefront'], label='',
                           lat=location['lat'], lng=location['lng'])
    return product, None


def save_bulk_digital_batch(files, shared, storefront, as_admin=False):
    """Persist a batch, isolating each file so one bad one does not sink the rest.

    Each product goes in inside a savepoint. Without one, a name collision or a
    constraint failure on file seven would need a rollback that discarded the six
    already staged, and the seller would be told the whole batch failed when only
    one file was at fault.
    """
    location = bulk_digital_location(storefront)
    created, failed = [], []
    for file in files:
        filename = file.filename or 'unnamed file'
        try:
            with db.session.begin_nested():
                product, error = build_bulk_digital_product(file, shared, location,
                                                            as_admin=as_admin)
                if error:
                    raise BulkFileRejected(error)
                db.session.add(product)
                db.session.flush()
                created.append({
                    'id': product.id,
                    'name': product.name,
                    'slug': product.slug,
                    'filename': filename,
                    'size': human_file_size(product.file_size),
                    'review': product.review_status != 'approved',
                })
        except BulkFileRejected as exc:
            failed.append({'filename': filename, 'error': str(exc)})
        except SQLAlchemyError:
            app.logger.exception('Bulk digital product failed for %s', filename)
            failed.append({'filename': filename,
                           'error': 'Could not be saved. Try this one on its own.'})

    if created:
        try:
            db.session.commit()
        except SQLAlchemyError:
            db.session.rollback()
            app.logger.exception('Bulk digital batch commit failed')
            return [], failed + [{'filename': item['filename'],
                                  'error': 'The batch could not be saved.'}
                                 for item in created]
        # Once per request, not once per file: the cache version is a single key
        # and rewriting it eight times would invalidate the same thing eight times.
        invalidate_product_cache()
    else:
        db.session.rollback()
    return created, failed


class BulkFileRejected(Exception):
    """One file failed validation. Rolls back its savepoint, leaves the batch."""


