@app.route('/seller/products', methods=['GET', 'POST'])
@app.route('/seller/products/<int:product_id>', methods=['GET', 'POST'])
@login_required
def seller_products(product_id=None):
    """List and edit the products a verified storefront sells."""
    storefront, bounce = seller_listing_gate()
    if bounce:
        return bounce

    product = None
    if product_id:
        product = Product.query.filter_by(id=product_id, seller_id=current_user.id).first_or_404()

    if request.method == 'POST':
        is_new = product is None
        target = product or Product(seller_id=current_user.id, commission_percent=15.0)
        old_discount = float(target.discount_percent or 0) if not is_new else 0.0
        error = save_seller_product(target, storefront, is_new)
        if error:
            flash(error, 'danger')
        else:
            try:
                if is_new:
                    db.session.add(target)
                db.session.commit()
            except SQLAlchemyError:
                db.session.rollback()
                app.logger.exception('Seller product save failed')
                flash('The product could not be saved. Please try again.', 'danger')
            else:
                invalidate_product_cache()
                if is_new:
                    where = target.location_display or 'your storefront address'
                    flash(f'"{target.name}" is listed and pinned to {where}.', 'success')
                    notify_seller_listing_live(target, storefront)
                else:
                    flash(f'"{target.name}" updated.', 'success')
                # A second-hand phone goes straight to the evidence step. Sending
                # the seller back to the product list here would leave the listing
                # parked with nothing telling them what it is waiting for.
                if target.review_status == 'pending_evidence':
                    return redirect(url_for('seller_phone_ownership', product_id=target.id))
                if target.review_status != 'approved':
                    flash('This condition needs an admin check before it appears in the shop.', 'info')

                # When discount goes from zero to positive, followers hear about it.
                new_discount = float(target.discount_percent or 0)
                if old_discount == 0 and new_discount > 0 and target.is_active:
                    reached = notify_storefront_followers(
                        storefront,
                        f'Price drop: {target.name}',
                        f'{target.name} is now {int(new_discount)}% off.',
                        product_id=target.id,
                    )
                    if reached:
                        flash(f'{reached} follower{"" if reached == 1 else "s"} notified of the discount.', 'info')

                return redirect(url_for('seller_products'))

    # Paginated because bulk upload made this list unbounded in one action: a
    # tutor who uploads an afternoon of past papers has thousands of listings, and
    # rendering all of them would time out the page they need to manage them from.
    page = request.args.get('page', 1, type=int)
    pagination = (Product.query.filter_by(seller_id=current_user.id)
                  .order_by(Product.created_at.desc())
                  .paginate(page=max(1, page), per_page=SELLER_PRODUCTS_PER_PAGE,
                            error_out=False))
    categories = nav_categories()
    return render_template('seller_products.html', storefront=storefront,
                           products=pagination.items, pagination=pagination,
                           categories=categories, product=product,
                           conditions=SELLER_PRODUCT_CONDITIONS,
                           excludable_countries=excludable_countries(),
                           selected_exclusions=product_excluded_countries(product) if product else [])


@app.route('/seller/products/<int:product_id>/toggle', methods=['POST'])
@login_required
def seller_product_toggle(product_id):
    storefront, bounce = seller_listing_gate()
    if bounce:
        return bounce
    product = Product.query.filter_by(id=product_id, seller_id=current_user.id).first_or_404()
    if product.review_status != 'approved' and not product.is_active:
        flash('This listing is waiting on an admin review and cannot be published yet.', 'warning')
        return redirect(url_for('seller_products'))
    product.is_active = not product.is_active
    db.session.commit()
    invalidate_product_cache()
    flash(f'"{product.name}" is now {"visible" if product.is_active else "hidden"}.', 'success')
    return redirect(url_for('seller_products'))


@app.route('/seller/products/<int:product_id>/ownership', methods=['GET', 'POST'])
@login_required
@limiter.limit(PHONE_EVIDENCE_RATE_LIMIT)
def seller_phone_ownership(product_id):
    """The guided ownership-evidence step for a second-hand phone.

    The guidance is the point. Because a submission below the threshold is rejected
    outright with no middle band, the honest seller's protection is that every
    problem is findable while the handset is still in their hand: the IMEI is
    checksum-checked in the browser before it is sent, each photo is measured on
    submission, and a rejection names the item that failed and can be resubmitted
    on the spot.
    """
    storefront, bounce = seller_listing_gate()
    if bounce:
        return bounce
    product = Product.query.filter_by(id=product_id, seller_id=current_user.id).first_or_404()

    if not phone_evidence_required(product):
        flash('That listing does not need ownership evidence.', 'info')
        return redirect(url_for('seller_products'))

    blocked = phone_listing_gate(current_user)
    if blocked:
        flash(blocked, 'warning')
        return redirect(url_for('seller_products'))

    if request.method == 'POST':
        imei = normalize_imei(request.form.get('imei', ''))

        # Camera capture first, file upload second. The guided flow uses the camera,
        # and a seller who did both meant the one they just took.
        imei_photo = (save_capture_data(request.form.get('imei_photo_capture', ''),
                                       PHONE_EVIDENCE_FOLDER)
                      or save_phone_evidence_upload(request.files.get('imei_photo')))
        proof = (save_capture_data(request.form.get('proof_capture', ''),
                                  PHONE_EVIDENCE_FOLDER)
                 or save_phone_evidence_upload(request.files.get('proof_file')))

        # Carry over what was already accepted, so fixing one rejected item does not
        # mean rephotographing both.
        previous = latest_phone_evidence(product.id)
        if previous:
            imei_photo = imei_photo or previous.imei_photo_path
            proof = proof or previous.proof_path

        try:
            evidence = record_phone_evidence(product, imei, imei_photo, proof)
            db.session.commit()
        except IntegrityError:
            # The unique constraint on proof_fingerprint caught a reuse that the
            # query above raced past. Same answer, from the database instead.
            db.session.rollback()
            flash('That proof image is already linked to another listing. '
                  'Use the proof for this handset.', 'danger')
            return redirect(url_for('seller_phone_ownership', product_id=product.id))
        except SQLAlchemyError:
            db.session.rollback()
            app.logger.exception('Phone evidence save failed for product %s', product.id)
            flash('The evidence could not be saved. Please try again.', 'danger')
            return redirect(url_for('seller_phone_ownership', product_id=product.id))

        invalidate_product_cache()
        if evidence.status == 'approved':
            flash(f'Ownership verified. "{product.name}" is live in the shop now.', 'success')
            return redirect(url_for('seller_products'))
        if evidence.status == 'manual_second_review':
            flash('Evidence received. Your first phone listing gets one human check - '
                  'usually the same day.', 'info')
            return redirect(url_for('seller_products'))
        flash('That evidence was not enough to verify ownership. '
              'The reasons are below, and you can submit again straight away.', 'warning')
        return redirect(url_for('seller_phone_ownership', product_id=product.id))

    evidence = latest_phone_evidence(product.id)
    return render_template('seller_phone_ownership.html', product=product,
                           storefront=storefront, evidence=evidence,
                           # So the page can promise what it will actually do. The
                           # explainer said verification is automatic with no waiting
                           # for a person, which is false for exactly the seller
                           # reading it for the first time - their first listing is
                           # held for one human look whatever it scores. Telling them
                           # that after they submit, in the status box, is the wrong
                           # order: this page exists to set expectations before the
                           # phone leaves their hand, and a promise broken on the
                           # first use is the one that costs the most trust.
                           first_listing=not seller_has_prior_phone_listing(
                               current_user.id),
                           attempts=PhoneOwnershipEvidence.query
                           .filter_by(product_id=product.id)
                           .order_by(PhoneOwnershipEvidence.created_at.desc())
                           .limit(5).all(),
                           min_score=PHONE_EVIDENCE_MIN_SCORE)


@app.route('/seller/products/<int:product_id>/ownership/imei-check', methods=['POST'])
@login_required
@limiter.limit(PHONE_EVIDENCE_RATE_LIMIT)
def seller_phone_imei_check(product_id):
    """Check an IMEI before the seller photographs anything.

    The browser already does the Luhn arithmetic. What it cannot know is whether
    the number is already listed or still under finance, and finding that out after
    taking two photos is a wasted trip.
    """
    product = Product.query.filter_by(id=product_id, seller_id=current_user.id).first_or_404()
    imei = normalize_imei((request.get_json(silent=True) or {}).get('imei', ''))
    if not imei_checksum_valid(imei):
        return jsonify({'ok': False,
                        'reason': 'That is not a valid IMEI. Dial *#06# on the handset '
                                  'and copy all 15 digits.'})
    conflicts = imei_hard_conflicts(imei, current_user, product.id)
    if conflicts:
        return jsonify({'ok': False, 'reason': conflicts[0]})
    return jsonify({'ok': True, 'reason': 'IMEI looks good.'})


@app.route('/seller/withdrawals', methods=['GET', 'POST'])
@login_required
def seller_withdrawals():
    if not user_can_sell(current_user):
        flash('Complete seller verification before requesting withdrawals.', 'warning')
        return redirect(url_for('seller_apply'))
    if request.method == 'POST':
        action = request.form.get('action', 'withdraw')
        if action == 'save_payout_account':
            current_user.seller_payout_method = request.form.get('seller_payout_method', 'mpesa')
            current_user.seller_payout_account = request.form.get('seller_payout_account', '').strip()
            current_user.seller_payout_name = request.form.get('seller_payout_name', '').strip()
            db.session.commit()
            flash('Receiving account saved. Future seller disbursements can use this account.', 'success')
            return redirect(url_for('seller_withdrawals'))
        amount = float(request.form.get('amount', 0) or 0)
        method = request.form.get('method', 'mpesa')
        destination = request.form.get('destination', '').strip() or current_user.seller_payout_account or ''
        if current_user.seller_status == 'frozen':
            flash('Withdrawals are blocked while your account is frozen. Submit an appeal to admin.', 'danger')
        elif amount <= 0:
            flash('Enter a valid withdrawal amount.', 'danger')
        elif not destination:
            flash('Add a receiving account before requesting withdrawal.', 'danger')
        elif amount > seller_available_balance(current_user.id):
            flash('That amount is not available yet. Seller payments are released only after buyers receive their products.', 'warning')
        else:
            db.session.add(WithdrawalRequest(
                user_id=current_user.id,
                amount=amount,
                method=method,
                destination=destination,
                status='pending_review'
            ))
            db.session.commit()
            flash('Withdrawal request submitted for review.', 'success')
        return redirect(url_for('seller_withdrawals'))
    earnings = Transaction.query.filter_by(user_id=current_user.id).order_by(Transaction.created_at.desc()).all()
    withdrawals = WithdrawalRequest.query.filter_by(user_id=current_user.id).order_by(WithdrawalRequest.created_at.desc()).all()
    return render_template('seller_withdrawals.html', earnings=earnings, withdrawals=withdrawals,
                           available_balance=seller_available_balance(current_user.id))


# ========================================================================
# REFERRAL PROMO CODES
# ========================================================================
# The MVP thanks a customer by handing them a code. Whoever they pass it to
# gets money off, and the customer who introduced them is paid in coins. The
# rules live here rather than in the checkout view so the admin preview, the
# checkout POST and the tests all judge a code the same way.

PROMO_CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'  # no O/0, no I/1
PROMO_DEFAULT_PERCENT = 10.0
PROMO_DEFAULT_MIN_ORDER = 1000.0
PROMO_MAX_PERCENT = 100.0


def promo_default_coins():
    """Coins the introducer earns per paid order.

    Reuses the existing coins_referral_bonus knob on the admin coins page - a
    referral is exactly what this is, so a second setting would only give the
    two ways to disagree.
    """
    try:
        return max(0, int(float(Setting.get('coins_referral_bonus', '50') or 0)))
    except (TypeError, ValueError):
        return 50


def generate_promo_code(prefix='SMK'):
    """A short, unambiguous code that is safe to read down a phone line."""
    prefix = re.sub(r'[^A-Z0-9]', '', (prefix or 'SMK').upper())[:6] or 'SMK'
    for _ in range(40):
        body = ''.join(secrets.choice(PROMO_CODE_ALPHABET) for _ in range(6))
        code = f'{prefix}{body}'
        if not PromoCode.query.filter_by(code=code).first():
            return code
    # Astronomically unlikely; fall back to something certainly unique rather
    # than handing back a duplicate that would trip the unique index later.
    return f'{prefix}{secrets.token_hex(5).upper()}'


def normalize_promo_code(raw):
    return re.sub(r'[^A-Z0-9]', '', str(raw or '').upper())[:24]


def find_promo_code(raw):
    code = normalize_promo_code(raw)
    if not code:
        return None
    return PromoCode.query.filter_by(code=code).first()


def promo_code_is_exhausted(promo):
    cap = promo.max_redemptions or 0
    return cap > 0 and (promo.times_used or 0) >= cap


def promo_code_error(promo, user, subtotal):
    """Why this shopper cannot use this code right now, or None if they can.

    `subtotal` is goods only. Delivery is deliberately excluded from both the
    minimum spend and the discount: a shopper should not clear the threshold on
    courier charges, and the platform should not discount a fee it pays out.
    """
    if promo is None:
        return 'That promo code was not recognised.'
    if not promo.is_active:
        return 'That promo code is no longer active.'
    if promo.expires_at and promo.expires_at <= utcnow():
        return 'That promo code has expired.'
    if user is None or not getattr(user, 'id', None):
        return 'Sign in to use a promo code.'
    if promo.owner_id == user.id:
        # The whole point is introducing somebody new, so self-use is not a
        # discount we are willing to fund.
        return 'This is your own code - share it with someone else to earn coins.'
    if promo_code_is_exhausted(promo):
        return 'That promo code has reached its limit.'
    already = PromoCodeRedemption.query.filter_by(
        promo_code_id=promo.id, user_id=user.id).first()
    if already:
        return 'You have already used that promo code.'
    minimum = promo.min_order_amount or 0
    if minimum and (subtotal or 0) < minimum:
        short = minimum - (subtotal or 0)
        return (f'Spend KES {minimum:,.0f} or more on items to use this code - '
                f'add KES {short:,.0f} to qualify.')
    return None


def promo_discount_amount(promo, subtotal):
    """The cash taken off, rounded to whole cents and never below zero."""
    if promo is None:
        return 0.0
    percent = promo.discount_percent
    if percent is None:
        percent = PROMO_DEFAULT_PERCENT
    percent = max(0.0, min(float(percent), PROMO_MAX_PERCENT))
    return round(max(0.0, float(subtotal or 0)) * percent / 100.0, 2)


def evaluate_promo_code(raw, user, subtotal):
    """Judge a typed code against a goods subtotal.

    Returns {promo, code, error, discount, percent}. Callers show `error` and
    charge full price, or apply `discount`.
    """
    code = normalize_promo_code(raw)
    if not code:
        return {'promo': None, 'code': '', 'error': None, 'discount': 0.0, 'percent': 0.0}
    promo = find_promo_code(code)
    error = promo_code_error(promo, user, subtotal)
    if error:
        return {'promo': None, 'code': code, 'error': error, 'discount': 0.0, 'percent': 0.0}
    return {
        'promo': promo,
        'code': promo.code,
        'error': None,
        'discount': promo_discount_amount(promo, subtotal),
        'percent': promo.discount_percent or PROMO_DEFAULT_PERCENT,
    }


def record_promo_redemption(order):
    """Credit the introducer once the order is genuinely paid.

    Called from finalize_paid_order, which a callback and a status poll can both
    reach, so this has to be safe to run twice. The unique index on
    (promo_code_id, order_id) is the guard: a repeat insert is rolled back to a
    savepoint and the coins are not paid a second time.
    """
    promo_id = getattr(order, 'promo_code_id', None)
    if not promo_id:
        return None
    promo = db.session.get(PromoCode, promo_id)
    if promo is None or promo.owner_id == order.user_id:
        return None
    if PromoCodeRedemption.query.filter_by(
            promo_code_id=promo.id, order_id=order.id).first():
        return None

    discount = round(float(order.discount_amount or 0), 2)
    goods = round(float(order.amount_paid or 0) - float(order.shipping_cost or 0) + discount, 2)
    coins = promo.owner_coins if promo.owner_coins is not None else promo_default_coins()
    coins = max(0, int(coins))

    try:
        with db.session.begin_nested():
            db.session.add(PromoCodeRedemption(
                promo_code_id=promo.id,
                order_id=order.id,
                user_id=order.user_id,
                discount_amount=discount,
                order_subtotal=goods,
                coins_awarded=coins,
            ))
    except IntegrityError:
        # Another finalize call got there first. Nothing to do.
        return None

    promo.times_used = (promo.times_used or 0) + 1
    promo.total_discount_given = round((promo.total_discount_given or 0) + discount, 2)
    promo.total_coins_awarded = (promo.total_coins_awarded or 0) + coins

    if coins:
        award_coins(promo.owner_id, coins, 'referral',
                    f'Promo code {promo.code} used on order {order.order_number}',
                    str(order.id))
    # The order number keeps each notification distinct - the dedupe in
    # create_customer_notification matches on title+body, so without it the
    # second person to use the code would notify nobody.
    create_customer_notification(
        promo.owner_id,
        'Someone used your promo code',
        f'{promo.code} was used on paid order {order.order_number}. '
        + (f'You earned {coins} coins.' if coins else 'Thanks for spreading the word.'),
        'promo_code')
    return promo


def website_ad_link(product=None):
    """The public URL an ad clicks through to - always back into the website.

    Ads run from the SMARKAFRICA accounts, so the click has to land on our own
    product page: an off-site link spends our audience on somebody else's
    checkout. Built on public_base_url() rather than request.host_url because
    the link is pasted into a phone app, where "http://localhost/..." is dead.
    """
    base = public_base_url() or ''
    slug = getattr(product, 'slug', None) if product is not None else None
    try:
        path = url_for('product_page', slug=slug) if slug else url_for('shop')
    except Exception:
        path = f'/product/{slug}' if slug else '/shop'
    return f'{base}{path}' if base else path


def social_ad_request_error(user):
    """Why this account may not ask for a post on our social accounts, or ''.

    The rule is the seller's own trading credential: a verified seller badge or
    an approved storefront. Anyone else has nothing for us to vouch for when the
    ad goes out under the SMARKAFRICA name.
    """
    if not (user and getattr(user, 'is_authenticated', False)):
        return 'Sign in with your seller account to request a social media ad.'
    if user_can_sell(user) or user_has_storefront(user):
        return ''
    return ('Only verified sellers and approved storefronts can request a post on the '
            'SMARKAFRICA social accounts. Finish verification first.')


@app.route('/seller/ads', methods=['GET', 'POST'])
@login_required
def seller_ads():
    if current_user.is_admin:
        return redirect(url_for('admin_ads'))
    if Setting.get('seller_ads_enabled', '0') != '1':
        flash('Seller ads are currently disabled by admin.', 'info')
        return redirect(url_for('home'))
    eligibility_error = social_ad_request_error(current_user)
    if eligibility_error:
        flash(eligibility_error, 'warning')
        return redirect(url_for('seller_apply'))

    products = Product.query.filter_by(seller_id=current_user.id).all()
    ad_plan_prices = seller_ad_plan_prices()
    if request.method == 'POST':
        plan_key = request.form.get('plan', 'daily')
        ad_charge = ad_plan_prices.get(plan_key, ad_plan_prices['daily'])
        budget = form_float('budget', ad_charge, minimum=0)
        platform = request.form.get('platform', 'SMARKAFRICA')
        placement = (request.form.get('placement', 'social') or 'social').strip()
        # Anything that is not an on-platform banner goes out from our own social
        # accounts, so it carries the stricter rules below.
        wants_social = placement != 'smarkafrica'
        product_id = request.form.get('product_id', type=int)
        product = Product.query.filter_by(id=product_id, seller_id=current_user.id).first() if product_id else None
        mpesa_phone = request.form.get('mpesa_phone', '').strip() or current_user.phone or ''
        if ad_charge <= 0:
            flash('Ad payment amount must be greater than zero.', 'danger')
        elif product_id and not product:
            flash('Choose one of your own products for this ad.', 'danger')
        elif wants_social and not product:
            # The request is to advertise a product, and the post has to link to
            # its page - there is nothing to point the audience at without one.
            flash('Choose which of your products should be posted on the SMARKAFRICA social accounts.', 'danger')
        elif not normalize_mpesa_phone(mpesa_phone):
            flash('Enter the M-Pesa phone number that should receive the STK push.', 'danger')
        else:
            fee_percent = float(Setting.get('seller_ad_service_fee_percent', '2') or 2)
            commission = round(ad_charge * fee_percent / 100, 2)
            campaign = AdCampaign(
                seller_id=current_user.id,
                product_id=product_id,
                platform=platform,
                budget=budget,
                admin_commission=commission,
                objective=request.form.get('objective', 'Sales'),
                audience=request.form.get('audience', '').strip(),
                ad_copy=request.form.get('ad_copy', '').strip(),
                creative_url=request.form.get('creative_url', '').strip(),
                # Not seller-supplied. The post goes out from our accounts, so the
                # click comes back to our product page every time.
                destination_url=website_ad_link(product),
                placement=placement,
                total_charged=ad_charge,
                status='pending_payment'
            )
            db.session.add(campaign)
            db.session.flush()
            order_ref = f'AD-{campaign.id}-{utcnow().strftime("%Y%m%d%H%M")}'
            stk_result = stk_push(mpesa_phone, ad_charge, order_ref)
            if stk_result.get('success') and stk_result.get('checkout_request_id'):
                Setting.query.filter_by(key=f'ad_stk_{stk_result["checkout_request_id"]}').delete()
                db.session.add(Setting(key=f'ad_stk_{stk_result["checkout_request_id"]}', value=str(campaign.id)))
                flash(f'Ad details saved. STK Push sent to {mpesa_phone} for KSh {ad_charge:,.2f}. '
                      f'Your request reaches the social posting queue once the payment clears.', 'success')
            else:
                flash(stk_result.get('error') or f'Ad details saved, but the STK Push could not be sent. Try payment again from your ad list.', 'warning')
            db.session.commit()
        return redirect(url_for('seller_ads'))
    campaigns = AdCampaign.query.filter_by(seller_id=current_user.id).order_by(AdCampaign.created_at.desc()).all()
    # Show the seller where each paid request got to, so "is it live yet?" is
    # answered on the page instead of by a message to support.
    posts_by_campaign = {}
    campaign_ids = [c.id for c in campaigns]
    if campaign_ids:
        for post in SocialAdPost.query.filter(SocialAdPost.campaign_id.in_(campaign_ids)).all():
            posts_by_campaign[post.campaign_id] = post
    return render_template('seller_ads.html', products=products, campaigns=campaigns,
                           payment_instructions=Setting.get('seller_ad_payment_instructions', ''),
                           ad_plan_prices=ad_plan_prices,
                           posts_by_campaign=posts_by_campaign,
                           campaign_is_paid=social_ad_campaign_is_paid,
                           site_base_url=public_base_url())


