@app.route('/admin/revenue')
@login_required
@admin_required
def admin_revenue_dashboard():
    from_date = request.args.get('from')
    to_date = request.args.get('to')
    query = PlatformRevenue.query
    if from_date:
        query = query.filter(PlatformRevenue.created_at >= from_date)
    if to_date:
        query = query.filter(PlatformRevenue.created_at <= to_date)

    stream_totals = db.session.query(
        PlatformRevenue.revenue_stream,
        func.sum(PlatformRevenue.amount).label('total'),
        func.count(PlatformRevenue.id).label('count')
    ).group_by(PlatformRevenue.revenue_stream).all()

    total_revenue = sum(s.total or 0 for s in stream_totals)
    recent = query.order_by(PlatformRevenue.created_at.desc()).limit(100).all()
    return render_template('admin/revenue_dashboard.html',
                           stream_totals=stream_totals, total_revenue=total_revenue, recent=recent)


# ========================================================================
# INIT & MAIN
# ========================================================================

def _db_dialect():
    return db.session.get_bind().dialect.name


def _translate_ddl(ddl):
    """Rewrite the SQLite-flavoured column DDL above for the active dialect."""
    if _db_dialect() == 'sqlite':
        return ddl
    # DATETIME is not a Postgres type, and booleans reject 0/1 literals.
    ddl = re.sub(r'\bDATETIME\b', 'TIMESTAMP', ddl, flags=re.IGNORECASE)
    ddl = re.sub(r'(\bBOOLEAN\s+DEFAULT\s+)0\b', r'\1FALSE', ddl, flags=re.IGNORECASE)
    ddl = re.sub(r'(\bBOOLEAN\s+DEFAULT\s+)1\b', r'\1TRUE', ddl, flags=re.IGNORECASE)
    return ddl


def ensure_column(table, column, ddl):
    inspector = sa_inspect(db.session.get_bind())
    if not inspector.has_table(table):
        return
    if column in {col['name'] for col in inspector.get_columns(table)}:
        return
    try:
        db.session.execute(text(f"ALTER TABLE {table} ADD COLUMN {_translate_ddl(ddl)}"))
        db.session.commit()
    except Exception:
        # A failed DDL statement aborts the whole Postgres transaction, so roll
        # back rather than let every later column in the loop fail too.
        db.session.rollback()
        app.logger.warning('Could not add column %s to %s', column, table, exc_info=True)


def ensure_index(name, table, columns, unique=False):
    try:
        unique_sql = 'UNIQUE ' if unique else ''
        db.session.execute(text(f"CREATE {unique_sql}INDEX IF NOT EXISTS {name} ON {table} ({columns})"))
        db.session.commit()
    except Exception:
        db.session.rollback()
        app.logger.warning('Could not create index %s on %s(%s)', name, table, columns, exc_info=True)


